/*
 * Battle-object sprite setup (sub_8011504 / loc_8011508).
 *
 * Gives an existing battle object its sprite: loads the sprite sheet and its
 * animation frames, picks shadow or no shadow, switches the object to its
 * initial animation, then creates and shapes the collision box and mirrors the
 * sprite to match the object's facing.
 *
 * object:         battle object the setup belongs to (r5)
 * spriteSpec:     packed sprite description
 *                 [31:24] non-zero = the sprite casts a shadow,
 *                 [23:16] animation id written to oBattleObject_CurAnim,
 *                 [15:8] and [7:0] ids passed on to sprite_load
 * collisionSpec:  packed collision description; bytes [31:24], [23:16] and
 *                 [15:8] are the three object_setupCollisionData arguments
 *                 (in that order), byte [7:0] is unused
 *
 * Returns object_createCollisionData's result: 0 when no collision slot was
 * free (the object stays without collision data, r0 = 0), 1 on success.
 * Callers see r0 plus the flags: on the failure path from testing that result,
 * on the success path from "r0 = 1". r1-r3 and C/V are whatever the last
 * callee left behind on both paths, so the adapters don't touch them.
 */
static u32 battle_init_object_sprite(u32 object, u32 spriteSpec, u32 collisionSpec) {
    /* load sprite sheet 0x80 with the graphic/palette ids from the low half */
    sprite_load(0x80, (spriteSpec >> 8) & 0xFF, spriteSpec & 0xFF);
    sprite_loadAnimationData();

    /* the spec's top byte decides whether the sprite gets a shadow */
    if ((spriteSpec >> 24) != 0)
        sprite_hasShadow(spriteSpec >> 24);
    else
        sprite_noShadow(spriteSpec >> 24);

    /* switch the object to its initial animation; 0xFF marks the animation
     * copy dirty so it gets refreshed */
    ST8(object + oBattleObject_CurAnim, (spriteSpec >> 16) & 0xFF);
    ST8(object + oBattleObject_CurAnimCopy, 0xFF);

    /* reserve a collision slot; the original still carries the 0xFF above in
     * r0 when this runs, so pass it on */
    u32 collisionSlot = object_createCollisionData(0xFF);
    if (collisionSlot == 0)
        return collisionSlot;   /* no free slot: leave without collision box */

    /* shape the collision box out of the collision spec's upper three bytes */
    object_setupCollisionData(collisionSlot,
                              collisionSpec >> 24,
                              (collisionSpec >> 16) & 0xFF,
                              (collisionSpec >> 8) & 0xFF);

    /* face the sprite the way the object is facing */
    sprite_setFlip(object_getFlip());
    return 1;
}

