/* Give the battle object `obj` its sprite and collision data.
 *
 * spriteSpec: byte 0 and byte 1 are the arguments to sprite_load, byte 2 is the
 *             initial animation index, byte 3 != 0 means the sprite gets a shadow.
 * collisionSpec: bytes 3, 1 and 2 are passed to object_setupCollisionData.
 *
 * Returns 1 once the collision data exists, or 0 if none was created (the
 * object is then left without collision). */
static u32 setup_battle_object_sprite(u32 spriteSpec, u32 collisionSpec, u32 obj) {
    sprite_load_gfx(0x80, (spriteSpec >> 8) & 0xFF, spriteSpec & 0xFF);
    sprite_load_anim_data();

    if ((spriteSpec >> 24) != 0)
        sprite_enable_shadow();
    else
        sprite_disable_shadow();

    ST8(obj + oBattleObject_CurAnim, (spriteSpec >> 16) & 0xFF);
    ST8(obj + oBattleObject_CurAnimCopy, 0xFF);

    if (object_create_collision_data() == 0)
        return 0;

    object_setup_collision_data((collisionSpec >> 24) & 0xFF,
                                (collisionSpec >> 8) & 0xFF,
                                (collisionSpec >> 16) & 0xFF);
    sprite_set_flip(object_get_flip());
    return 1;
}

