/* Run the battle-tutorial script for the object's current slot, then hand the
 * chatbox over to it. Slots 0xFF and any unhandled value do nothing, as does a
 * handler that reports no script (index 0). */
static void run_battle_tutorial(u32 obj) {
    u32 script;

    switch (LD8(obj + 0xC)) {
    case 0:
        script = tutorial_script_slot0();
        break;
    case 1:
        script = tutorial_script_slot1();
        break;
    case 3:
        script = tutorial_script_slot3();
        break;
    default:
        return;
    }

    if (script == 0)
        return;

    /* The original reloads the slot here, in case the handler just changed it. */
    chatbox_run_script(LD32(A_TextScriptFirstBattleTutorials + LD8(obj + 0xC) * 4), script);

    /* Save the chatbox state and take the box over while the script runs. */
    ST8(obj + 0xD, LD8(obj + 1));
    ST8(obj + 1, 0x34);
    ST16(obj + 2, 0);
}

