/* Dispatch the first-battle tutorial dialogue based on the tutorial mode stored in the
 * state struct at [r5].  Advances the sub-state once the chatbox finishes. */
static void handle_first_battle_tutorial(u32 state) {
    u32 mode = LD8(state + oTutorialState_Mode);

    if (mode == 0xFF)
        return;                         /* tutorial already completed / not started */

    u32 script_idx;
    if (mode == 0)
        script_idx = tutorial_script_for_mode0(state);
    else if (mode == 1)
        script_idx = tutorial_script_for_mode1(state);
    else if (mode == 3)
        script_idx = tutorial_script_for_mode3(state);
    else
        return;                         /* unrecognized mode – no-op */

    if (script_idx == 0)
        return;                         /* callee decided no dialogue is needed */

    /* Fetch the per-mode script archive pointer from the tutorial table */
    u32 archive = LD32(A_TextScriptFirstBattleTutorials + (mode << 2));
    run_battle_tutorial_script(state, archive, script_idx);

    /* Advance the tutorial sub-state: save old byte, set next phase, clear counter */
    ST8(state + oTutorialState_SavedSub, LD8(state + oTutorialState_SubState));
    ST8(state + oTutorialState_SubState, TUTORIAL_STATE_NEXT);
    ST16(state + oTutorialState_SubCounter, 0);
}

