/* Advance the first-battle tutorial script state.
 * t is the address of the tutorial state object.  Depending on the active
 * phase we ask the matching step routine for the next script index; if it
 * answers 0 there is nothing to do.  Otherwise we look up the script archive
 * for the current phase, run that script, and shift the ids: the old id is
 * stashed, the "running a tutorial" id (0x34) is installed, and the counter
 * is reset. */
static void update_first_battle_tutorial(u32 t) {
    u32 script_idx;

    switch (LD8(t + oFirstBattleTutorial_Phase)) {
    case 0: script_idx = step0_script_index(); break;
    case 1: script_idx = step1_script_index(); break;
    case 3: script_idx = step3_script_index(); break;
    default: return;
    }

    if (script_idx == 0)
        return;

    run_chatbox_script(
        LD32(A_TextScriptFirstBattleTutorials +
             (u32)LD8(t + oFirstBattleTutorial_Phase) * 4),
        script_idx);

    ST8(t + oFirstBattleTutorial_SavedScriptId, LD8(t + oFirstBattleTutorial_ScriptId));
    ST8(t + oFirstBattleTutorial_ScriptId, 0x34);
    ST16(t + oFirstBattleTutorial_Unk02, 0);
}

