/* Advance the first-battle tutorial. Depending on the object's state byte, pick a
 * chatbox script (0 = nothing to say this frame); otherwise play it in the chatbox,
 * remember which chatbox state gets replaced, and park the object in state 0x34
 * ("text playing") with the new chatbox state so it resumes once the text ends. */
static void run_first_battle_tutorial_text(u32 tutorial) {
    u32 state = LD8(tutorial + 0xC);
    u32 script_index;

    if (state == 0)
        script_index = pick_tutorial_script_state0();
    else if (state == 1)
        script_index = pick_tutorial_script_state1();
    else if (state == 3)
        script_index = pick_tutorial_script_state3();
    else
        return;

    if (script_index == 0)
        return;

    /* Re-read the state: the pick_* helpers may have changed it before choosing. */
    state = LD8(tutorial + 0xC);
    run_chatbox_script(tutorial_archive_for_state(state), script_index);

    ST8(tutorial + 0xD, LD8(tutorial + 1));
    ST8(tutorial + 1, 0x34);
    ST16(tutorial + 2, 0);
}

