/* Execute one step of the first-battle tutorial state machine. */
static void advance_first_battle_tutorial(u32 state) {
    u8 phase = LD8(state + 0xC);

    /* 0xFF means the tutorial is already finished; any other unknown value
     * also means "nothing to do" (matches the original's fall-through). */
    if (phase == 0xFF)
        return;

    u32 script_idx;
    if (phase == 0)
        script_idx = tutorial_get_script_phase0(state);
    else if (phase == 1)
        script_idx = tutorial_get_script_phase1(state);
    else if (phase == 3)
        script_idx = tutorial_get_script_phase3(state);
    else
        return;  /* phase 2 or other value – skip */

    if (script_idx == 0)
        return;  /* callee had nothing to show */

    /* TextScriptFirstBattleTutorials is a pointer table indexed by phase. */
    u32 archive = LD32(A_TextScriptFirstBattleTutorials + (u32)(phase << 2));
    run_chatbox_script(archive, script_idx);

    /* Advance the state machine: move the "next sub-state" byte forward
     * and set the tutorial step to the "after first battle" phase (0x34). */
    ST8(state + 0xD, LD8(state + 1));
    ST8(state + 1, 0x34);
    ST16(state + 2, 0);
}

