#define NUM_GFX_ANIMS 0x12

/* register form: calls a GFX animation handler through the computed dispatch table;
 * the handler receives r7 = state pointer, r0 = command position, r1 = command byte-offset */
static void dispatch_gfx_handler(u32 handler_addr, u32 state, u32 cmd_pos, u32 cmd_offset) {
    R7 = state;
    R0 = cmd_pos;
    R1 = cmd_offset;
    GUEST_CALL(handler_addr);
}

/* Tick every active animation state: decrement timer, and when it reaches zero
 * advance the command pointer and invoke the per-command handler (palette upload,
 * tile transfer, SFX, flag set/clear, etc.). */
static void process_gfx_anims(void) {
    for (u32 i = 0; i < NUM_GFX_ANIMS; i++) {
        u32 state = A_eGFXAnimState0 + i * oGFXAnimState_Size;

        if (LD8(state + oGFXAnimState_IsActive) == 0)
            continue;

        /* Decrement the frame timer (32-bit register arithmetic, 16-bit storage). */
        u32 timer = (u32)LD16(state + oGFXAnimState_Timer) - 1;
        ST16(state + oGFXAnimState_Timer, timer);

        if ((s32)timer > 0)
            continue;

        /* Timer expired – fetch the next command in the animation script. */
        u32 cmd = LD8(state + oGFXAnimState_Command);
        u32 cmd_pos = LD32(state + oGFXAnimState_CommandPos)
                    + LD32(A_byte_8001C08 + cmd);   /* skip 8-byte per-entry header */

        u32 opcode = LD32(cmd_pos);

        if (opcode == 0) {
            /* End of script – deactivate this animation slot. */
            ST8(state + oGFXAnimState_IsActive, 0);
            continue;
        }

        if (opcode == 2) {
            /* SETLOOP: redirect to the branch target and remember it. */
            cmd_pos = LD32(cmd_pos + 4);
            ST32(state + oGFXAnimState_LoopAddress, cmd_pos);
        } else if (opcode == 1) {
            /* LOOP: jump back to the stored loop address. */
            cmd_pos = LD32(state + oGFXAnimState_LoopAddress);
        }

        /* Store the (possibly redirected) command position and read the next entry's timer. */
        ST32(state + oGFXAnimState_CommandPos, cmd_pos);
        ST16(state + oGFXAnimState_Timer, LD32(cmd_pos + 4));

        /* Dispatch the handler indexed by the command byte-offset (0,4,8,…,0x18). */
        u32 handler = LD32(A_off_8001C24 + cmd);
        dispatch_gfx_handler(handler, state, cmd_pos, cmd);
    }
}

/* ProcessGFXAnims() – iterates all 18 GFX animation states, advancing their timers
 * and dispatching per-frame handlers.  All caller registers are preserved. */
Next ProcessGFXAnims(void) {
    process_gfx_anims();
    RETURN_TO_CALLER();
}

