 * param0 = 0xFF means "no fade" and the function returns immediately.
 * param1 = fade brightness value (0xFF → 0x100, i.e. "full bright").
 * The fade slot lives at eScreenFade (offset 0 for the first bank). */

/* register form: calls screenFade_StopAndFreePalettes_8006330 outside this file, which has no typed C interface yet */
static u32 fade_stop_and_free(u32 slot_offset) {
    R0 = slot_offset;
    GUEST_CALL(screenFade_StopAndFreePalettes_8006330);
    return R0;
}

typedef struct {
    u32 r0;
    u32 r1;
    u32 r2;
    u32 flag_val;   /* value that was compared against 0xFF for the last SET_FLAGS */
} FadeSetResult;

static FadeSetResult set_screen_fade(u32 param0, u32 param1, u32 orig_r2) {
    FadeSetResult res;

    if (param0 == 0xFF) {
        /* No fade requested – return unchanged, flags show equal. */
        res.r0 = param0;
        res.r1 = param1;
        res.r2 = orig_r2;
        res.flag_val = param0;
        return res;
    }

    u32 fade = A_eScreenFade;               /* r3 = 0 → first fade slot */
    u32 idx = fade_stop_and_free(0);        /* stop any running fade, get table index */

    ST8(fade + 1, idx);                     /* record palette index */

    /* Look up this fade's parameter block in the table at off_8006040 */
    u32 params = A_off_8006040 + (idx << 2);

    ST32(fade + 0x10, LD32(params + oFadeParams_Ptr_00));   /* pointer A */
    ST32(fade + 0x14, LD32(params + oFadeParams_Ptr_04));   /* pointer B */
    ST16(fade + 0x18, (u16)LD8(params + oFadeParams_Unk_0c));
    ST16(fade + 0x1C, (u16)LD8(params + oFadeParams_Unk_0d));
    ST16(fade + 0x08, (u16)LD8(params + oFadeParams_Unk_0e));
    ST16(fade + 0x0A, (u16)(LD8(params + oFadeParams_Unk_0f) << 4));

    ST8(fade, 1);                           /* fade active */
    ST8(fade + oScreenFade_Unk_03, 1);      /* ?running? flag */
    ST8(fade + 2, 0);                       /* reset step counter */

    /* 0xFF brightness means "stay fully lit"; encode as 0x100 so the
     * comparison loop will never decrement below it. */
    u32 brightness = (param1 == 0xFF) ? param1 + 1 : param1;
    ST16(fade + 4, (u16)brightness);

    res.r0 = 0;                             /* last mov r0,#0 before return */
    res.r1 = brightness;
    res.r2 = params;
    res.flag_val = param1;                  /* cmp r1,#0xff set before the add */
    return res;
}

/* SetScreenFade(r0 = trigger, r1 = brightness) → r0 r1 r2 r3 r5 lr nzcv */
Next SetScreenFade(void) {
    FadeSetResult res = set_screen_fade(R0, R1, R2);
    R0 = res.r0;
    R1 = res.r1;
    R2 = res.r2;
    R3 = 0;
    SET_FLAGS_CMP(res.flag_val, 0xFF);
    RETURN_TO_CALLER();
}

