    timer--;
    ST16(state + oGFXAnimState_Timer, timer);
    if ((s32)timer > 0)
        return;                 /* frame still running */

    u32 cmd = LD8(state + oGFXAnimState_Command);
    /* Skip past this anim's fixed-size data to reach the next stream entry. */
    u32 entry = LD32(state + oGFXAnimState_CommandPos)
              + LD32(A_byte_8001C08 + cmd);

    u32 opcode = LD32(entry);
