        ST8(state + oGFXAnimState_IsActive, 0);
        return;
    }
    if (opcode == 2) {
        /* Loop marker: the next word is where the stream loops back to. */
        entry = LD32(entry + 4);
        ST32(state + oGFXAnimState_LoopAddress, entry);
    } else if (opcode == 1) {
        /* Wrap marker: continue from the recorded loop address. */
        entry = LD32(state + oGFXAnimState_LoopAddress);
    }

    ST32(state + oGFXAnimState_CommandPos, entry);
    ST16(state + oGFXAnimState_Timer, LD32(entry + 4));

    switch (cmd) {
    case 0: anim_cmd_queue_palette(state, entry);      break; /* copy palette */
    case 1: anim_cmd_copy_tiles_20(state, entry);      break; /* copy 0x20-sized tiles */
    case 2: anim_cmd_08(state, entry);                 break;
    case 3: anim_cmd_palette_transform(state, entry);  break; /* manual palette transform */
    case 4: anim_cmd_play_sfx(state, entry);           break; /* play sound effect */
    case 5: anim_cmd_event_flag(state, entry);         break; /* set or clear event flag */
    case 6: anim_cmd_copy_tiles_40(state, entry);      break; /* copy 0x40-sized tiles */
    }
