    res.r3 = bank;

    if (fade_index == 0xFF) {
        /* Nothing to do; preserve caller's r1/r2, flags from CMP(0xFF,0xFF). */
        res.r0 = 0xFF;
        res.r1 = fade_value;
        res.r2 = r2_in;
        res.flags_cmp = 0xFF;
        return res;
    }

    u32 fade = A_eScreenFade + bank;

    /* Release palettes owned by this bank (return value is discarded). */
    stop_and_free_palettes(bank);

    /* Store fade index into struct byte 1. */
    ST8(fade + 1, fade_index);

    /* Locate this fade's parameter record in the table. */
    u32 params = A_off_8006040 + (fade_index << 2);
    res.r2 = params;

    /* Copy parameter pointers into the fade struct. */
    ST32(fade + 0x10, LD32(params + oFadeParams_Ptr_00));
    ST32(fade + 0x14, LD32(params + oFadeParams_Ptr_04));

    /* Copy parameter bytes (zero-extended to halfwords). */
    ST16(fade + 0x18, LD8(params + oFadeParams_Unk_0c));
    ST16(fade + 0x1C, LD8(params + oFadeParams_Unk_0d));
    ST16(fade + 8,    LD8(params + oFadeParams_Unk_0e));
    ST16(fade + 0xA,  LD8(params + oFadeParams_Unk_0f) << 4);

    /* Mark fade as active; clear the unused byte and the "paused" flag. */
    ST8(fade, 1);
    ST8(fade + oScreenFade_Unk_03, 1);
    ST8(fade + 2, 0);

    /* Fade value 0xFF means "reset to 0" (increment wraps to 0x100 → 0 as u16). */
    if (fade_value == 0xFF) {
        fade_value = 0x100;   /* stored as halfword: low 16 bits = 0 */
        res.flags_cmp = 0x101; /* CMP(0x101, 0xFF) ≡ ADDS(0xFF, 1): NZCV match */
    } else {
        res.flags_cmp = fade_value; /* CMP(r1, 0xFF) is the original flag op */
    }
    ST16(fade + 4, fade_value);

    res.r0 = 0;              /* last value written to r0 by the original */
    res.r1 = fade_value;
    return res;
}

/* SetScreenFade(r0 = fade_index, r1 = fade_value, r5, lr) -> r0 r1 r2 r3 + flags */
Next SetScreenFade(void) {
    FadeResult res = set_screen_fade(R0, R1, R2, 0);
    R0 = res.r0;
    R1 = res.r1;
    R2 = res.r2;
    R3 = res.r3;
    SET_FLAGS_CMP(res.flags_cmp, 0xFF);
    RETURN_TO_CALLER();
}

/* Second entry point (0x08006274): same logic for the other fade bank (offset 0x20). */
Next SetScreenFade_bank2(void) {
    FadeResult res = set_screen_fade(R0, R1, R2, FADE_BANK_SIZE);
    R0 = res.r0;
    R1 = res.r1;
    R2 = res.r2;
    R3 = res.r3;
    SET_FLAGS_CMP(res.flags_cmp, 0xFF);
    RETURN_TO_CALLER();
}

/* sub_8011504 / loc_8011508 -- (re)load a battle object's sprite graphics.
 *
 * Entry sub_8011504 copies r0 into r6, then both entries run the same tail:
 *   sprite_load(0x80, byte1, byte0 of the descriptor) + animation data,
 *   keep or drop the object's shadow from the descriptor's top byte,
 *   store the current animation id into oBattleObject_CurAnim, poke 0xFF
 *   (the "re-read CurAnim" sentinel) into oBattleObject_CurAnimCopy,
 *   then, if object_createCollisionData succeeds, set up the collision shape
 *   from the animation-args register and mirror the object's flip state.
 * Returns guest r0 = 1 when the collision data was built, 0 otherwise.
 *
 * The descriptor register (guest r0 at sub_8011504, guest r6 at loc_8011508)
 * packs, from LSB up: frame index, sprite bank, animation id, shadow flag.
 * The animation-args register (guest r1) packs the three arguments of
 * object_setupCollisionData in its top three bytes. */

#define ANIM_NONE       0xFF    /* sentinel in oBattleObject_CurAnimCopy */
#define SPRITE_BANK     0x80    /* first argument of every sprite_load call here */

/* register form: calls sprite_load outside this file, which has no typed C interface yet.
 * The original leaves the descriptor in guest r6 and the animation args in guest r7
 * ("mov r6,r0" / "mov r7,r1"), and every callee of this sequence preserves r6/r7,
 * so they are planted here once, before the first call. */
static void call_sprite_load(u32 desc_r6, u32 args_r7, u32 bank, u32 anim, u32 frame)
{
    R0 = bank;
    R1 = anim;
    R2 = frame;
    R6 = desc_r6;
    R7 = args_r7;
    GUEST_CALL(sprite_load);
}

/* register form: calls sprite_loadAnimationData outside this file, which has no typed C interface yet */
static void call_load_animation_data(void)
{
    GUEST_CALL(sprite_loadAnimationData);
}

/* register form: calls sprite_hasShadow / sprite_noShadow outside this file, which have no
 * typed C interface yet.  The original tests the descriptor's top byte and calls one or the
 * other with that same value still in r0. */
static void call_set_shadow(u32 shadowFlag)
{
    R0 = shadowFlag;
    if (shadowFlag != 0)
        GUEST_CALL(sprite_hasShadow);
    else
        GUEST_CALL(sprite_noShadow);
}

/* register form: calls object_createCollisionData outside this file, which has no typed C
 * interface yet.  The original still holds 0xFF in r0 at this call; keep it there. */
static u32 call_create_collision_data(u32 r0_val)
{
    R0 = r0_val;
    GUEST_CALL(object_createCollisionData);
    return R0;
}

/* register form: calls object_setupCollisionData outside this file, which has no typed C
 * interface yet.  r0 is left alone: the original still carries object_createCollisionData's
 * return value in it here. */
static void call_setup_collision_data(u32 a, u32 b, u32 c)
{
    R1 = a;
    R2 = b;
    R3 = c;
    GUEST_CALL(object_setupCollisionData);
}

/* register form: calls object_getFlip outside this file, which has no typed C interface yet */
static u32 call_object_get_flip(void)
{
    GUEST_CALL(object_getFlip);
    return R0;
}

/* register form: calls sprite_setFlip outside this file, which has no typed C interface yet */
static void call_sprite_set_flip(u32 flip)
{
    R0 = flip;
    GUEST_CALL(sprite_setFlip);
}

/* Returns 1 on success; 0 (the raw object_createCollisionData result) on failure. */
static u32 load_battle_object_sprite(u32 spriteDesc, u32 animArgs, u32 obj)
{
    call_sprite_load(spriteDesc, animArgs, SPRITE_BANK,
                     (spriteDesc >> 8) & 0xFF,          /* sprite bank   */
                     spriteDesc & 0xFF);                /* frame index   */
    call_load_animation_data();
    call_set_shadow(spriteDesc >> 24);                  /* nonzero top byte = keep shadow */

    ST8(obj + oBattleObject_CurAnim,     (spriteDesc >> 16) & 0xFF);
    ST8(obj + oBattleObject_CurAnimCopy, ANIM_NONE);

    if (call_create_collision_data(ANIM_NONE) == 0)
        return 0;   /* no collision data built: stop here, guest r0 stayed 0 */

    call_setup_collision_data(animArgs >> 24,           /* shape args, top to bottom byte */
                              (animArgs >> 16) & 0xFF,
                              (animArgs >> 8) & 0xFF);
    call_sprite_set_flip(call_object_get_flip());
    return 1;
}

/* sub_8011504(r0 = sprite descriptor, r1 = animation args, r5 = object) -> r0, nz c v */
Next sub_8011504(void)
{
    u32 r6_saved = R6, r7_saved = R7;   /* caller's r6/r7 are popped back on return */
    u32 status = load_battle_object_sprite(R0, R1, R5);
    R6 = r6_saved;
    R7 = r7_saved;
    SET_FLAGS_NZ(status);
    RETURN_TO_CALLER();
}

/* loc_8011508: same sequence, but the descriptor is already in r6 (the "mov r6,r0" step
 * of the primary entry point is skipped). */
Next loc_8011508(void)
{
    u32 r6_saved = R6, r7_saved = R7;
    u32 status = load_battle_object_sprite(R6, R1, R5);
    R6 = r6_saved;
    R7 = r7_saved;
    SET_FLAGS_NZ(status);
    RETURN_TO_CALLER();
}

/* Register offsets within the screen fade state (relative to eScreenFade + set). */
#define oScreenFade_Active        0x0
#define oScreenFade_Type          0x1
#define oScreenFade_Unk_02        0x2
#define oScreenFade_Unk_03        0x3
#define oScreenFade_Step          0x4
#define oScreenFade_Speed0        0x8
#define oScreenFade_Speed1        0xA
#define oScreenFade_TablePtr      0x10
#define oScreenFade_TablePtr4     0x14
#define oScreenFade_Unk_18        0x18
#define oScreenFade_Unk_1C        0x1C

/* Register offsets within the per-fade-type parameter table entry (at off_8006040). */
#define oFadeParams_Ptr_00        0x00
#define oFadeParams_Ptr_04        0x04
#define oFadeParams_Unk_0c        0x0C
#define oFadeParams_Unk_0d        0x0D
#define oFadeParams_Unk_0e        0x0E
#define oFadeParams_Unk_0f        0x0F

/* register form: calls screenFade_StopAndFreePalettes_8006330 outside this file, which has no typed C interface yet */
static void stop_and_free_palettes(u32 set_index, u32 fade_base) {
    R0 = set_index;
    R5 = fade_base;
    GUEST_CALL(screenFade_StopAndFreePalettes_8006330);
}

typedef struct {
    u32 r0;          /* fade type index */
    u32 r1;          /* fade step (0x100 when input was 0xFF, else unchanged) */
    u32 r2;          /* pointer into the fade-params table (or original on early exit) */
    u32 r3;          /* set index (always 0 for the main entry) */
    u32 cmp_a;       /* first operand of the final flag-setting instruction */
    u32 cmp_b;       /* second operand of the final flag-setting instruction */
} FadeResult;

/* Configure a screen fade: select a palette set, copy fade parameters from the
 * table at off_8006040 into the eScreenFade state, and activate it.
 * Returns early with everything unchanged if fade_type is 0xFF. */
static FadeResult set_screen_fade(u32 fade_type, u32 fade_step, u32 r2_in) {
    FadeResult res;
    res.r0 = fade_type;
    res.r1 = fade_step;
    res.r2 = r2_in;
    res.r3 = 0;
    res.cmp_a = fade_type;
    res.cmp_b = 0xFF;

    if (fade_type == 0xFF)
        return res;                         /* nothing to do; flags from CMP r0, 0xFF */

    u32 fade = A_eScreenFade;               /* r5 = eScreenFade + r3 (r3 == 0 here) */

    stop_and_free_palettes(0, fade);

    ST8(fade + oScreenFade_Type, fade_type);

    /* Select parameter entry: params = fadeParamsTable + fade_type * 4 */
    u32 params = A_off_8006040 + (fade_type << 2);

    ST32(fade + oScreenFade_TablePtr,  LD32(params + oFadeParams_Ptr_00));
    ST32(fade + oScreenFade_TablePtr4, LD32(params + oFadeParams_Ptr_04));
    ST16(fade + oScreenFade_Unk_18,    (u16)LD8(params + oFadeParams_Unk_0c));
    ST16(fade + oScreenFade_Unk_1C,    (u16)LD8(params + oFadeParams_Unk_0d));
    ST16(fade + oScreenFade_Speed0,    (u16)LD8(params + oFadeParams_Unk_0e));
    ST16(fade + oScreenFade_Speed1,    (u16)(LD8(params + oFadeParams_Unk_0f) << 4));

    ST8(fade + oScreenFade_Active,  1);     /* mark fade active */
    ST8(fade + oScreenFade_Unk_03,  1);     /* enable fade */
    ST8(fade + oScreenFade_Unk_02,  0);     /* clear */

    if (fade_step == 0xFF) {
        res.r1 = fade_step + 1;             /* 0x100; lower half stored → step 0 */
        res.cmp_a = 0;
        res.cmp_b = 0xFFFFF00;              /* flags equivalent to ADDS(0xFF, 1) */
    } else {
        res.cmp_a = fade_step;              /* flags from CMP r1, 0xFF (Z=0) */
        res.cmp_b = 0xFF;
    }
    ST16(fade + oScreenFade_Step, (u16)res.r1);
    res.r2 = params;

    return res;
}

/* SetScreenFade(r0 = fade type, r1 = fade step) -> r0, r1, r2, r3; flags */
Next SetScreenFade(void) {
    FadeResult f = set_screen_fade(R0, R1, R2);
    R0 = f.r0;
    R1 = f.r1;
    R2 = f.r2;
    R3 = f.r3;
    SET_FLAGS_CMP(f.cmp_a, f.cmp_b);
    RETURN_TO_CALLER();
}

/* ===== SetScreenFade (0x08006270) =====
 *
 * Arms a palette fade on one of the two 0x20-byte slots at eScreenFade
 * (slot 0x00 for the normal entry, slot 0x20 for loc_8006274). fade_id
 * indexes the parameter table at off_8006040; 0xFF means "leave the slot
 * alone". duration becomes the slot's frame counter; a duration of 0xFF
 * is stored as 0x100, exactly like the original's adds r1,#1.
 *
 * Register contract notes:
 *  - r3 is always forced to the slot offset (0 or 0x20) by the entry.
 *  - r5/r2 are read but not used on the early-exit path, so they are
 *    passed in and returned unchanged there.
 *  - lr is only clobbered on the path that makes the internal bl; the
 *    GUEST_CALL helper leaves it in exactly the state the original does,
 *    and the early-exit path never calls it.
 *  - The original's last flag-setting instruction is cmp r0,#0xFF on the
 *    early-exit path, cmp r1,#0xFF when duration != 0xFF, and adds
 *    r1,#1 when duration == 0xFF. All three are reproduced without
 *    branching by SET_FLAGS_ADD on a returned (a, b) pair:
 *      ADDS a,b ≡ SUBS a,b for NZCV, and ADDS 0xFFFFFFFF+1 == CMP 0xFF,0xFF.
 */

typedef struct {
    u32 r0, r1, r2, r3, r5;
    u32 flag_a, flag_b;   /* operands so SET_FLAGS_ADD(flag_a, flag_b) gives the original's NZCV */
} ScreenFadeResult;

/* register form: calls screenFade_StopAndFreePalettes_8006330 outside this file, which has no typed C interface yet */
static void screen_fade_stop_and_free(u32 slot_offset, u32 fade_slot) {
    /* Kill any fade running in this slot and free its palettes.
     * The original pushes r0/r1 around this call and pops them back,
     * so whatever the callee returns in r0 is discarded. */
    R0 = slot_offset;
    R3 = slot_offset;
    R5 = fade_slot;
    GUEST_CALL(screenFade_StopAndFreePalettes_8006330);
}

static ScreenFadeResult set_screen_fade(u32 slot_offset, u32 fade_id, u32 duration, u32 in_r2, u32 caller_r5) {
    ScreenFadeResult out;

    if (fade_id == 0xFF) {
        /* Keep the slot as it is; only the flags of "cmp r0, #0xFF" are left behind. */
        out.r0 = fade_id;
        out.r1 = duration;
        out.r2 = in_r2;
        out.r3 = slot_offset;
        out.r5 = caller_r5;
        out.flag_a = 0xFFFFFFFF;
        out.flag_b = 1;               /* 0xFFFFFFFF + 1 == flags of CMP fade_id,0xFF with fade_id == 0xFF */
        return out;
    }

    u32 slot = A_eScreenFade + slot_offset;

    screen_fade_stop_and_free(slot_offset, slot);

    ST8(slot + 1, fade_id);

    /* Copy this fade's parameters from the ROM table (fade id * 4 is the entry stride). */
    u32 params = A_off_8006040 + (fade_id << 2);
    ST32(slot + 0x10, LD32(params + oFadeParams_Ptr_00));
    ST32(slot + 0x14, LD32(params + oFadeParams_Ptr_04));
    ST16(slot + 0x18, LD8(params + oFadeParams_Unk_0c));
    ST16(slot + 0x1C, LD8(params + oFadeParams_Unk_0d));
    ST16(slot + 8,    LD8(params + oFadeParams_Unk_0e));
    ST16(slot + 0xA,  LD8(params + oFadeParams_Unk_0f) << 4);

    /* Mark the fade active and reset its progress counters. */
    ST8(slot, 1);
    ST8(slot + oScreenFade_Unk_03, 1);
    ST8(slot + 2, 0);

    u32 flag_a, flag_b;
    u32 counter = duration;
    if (duration == 0xFF) {
        counter = duration + 1;
        flag_a = 0xFF;
        flag_b = 1;                   /* ADDS duration,1 */
    } else {
        flag_a = duration;
        flag_b = 0u - 0xFFu;          /* ADDS duration,-0xFF == CMP duration,0xFF */
    }
    ST16(slot + 4, counter);

    out.r0 = 0;
    out.r1 = counter;
    out.r2 = params;
    out.r3 = slot_offset;
    out.r5 = caller_r5;
    out.flag_a = flag_a;
    out.flag_b = flag_b;
    return out;
}

/* SetScreenFade(r0 = fade id, r1 = duration) -> r0 r1 r2 r3, nz c v; preserves r5 */
Next SetScreenFade(void) {
    ScreenFadeResult r = set_screen_fade(0, R0, R1, R2, R5);
    R0 = r.r0, R1 = r.r1, R2 = r.r2, R3 = r.r3, R5 = r.r5;
    SET_FLAGS_ADD(r.flag_a, r.flag_b);
    RETURN_TO_CALLER();
}

/* Alternative entry point: same, but arms the fade in the second eScreenFade slot. */
Next loc_8006274(void) {
    ScreenFadeResult r = set_screen_fade(0x20, R0, R1, R2, R5);
    R0 = r.r0, R1 = r.r1, R2 = r.r2, R3 = r.r3, R5 = r.r5;
    SET_FLAGS_ADD(r.flag_a, r.flag_b);
    RETURN_TO_CALLER();
}

/* ProcessGFXAnims: tick and advance all active GFX animation states each frame. */

#define NUM_GFX_ANIMS 0x12

/* register form: indirect call to a GFX anim command handler via function pointer table;
   handlers have no typed C interface yet */
static void call_gfx_anim_handler(u32 handler_addr, u32 data_ptr, u8 command, u32 state_ptr) {
    R0 = data_ptr;
    R1 = (u32)command;
    R2 = (u32)command;
    R3 = R12;          /* original passes r3 = caller's r12 (never modified in the loop) */
    R7 = state_ptr;
    GUEST_CALL(handler_addr);
}

/* Iterate 18 GFX animation slots: decrement active timers, and when a timer expires
 * advance the command list (handling 0 = end, 1 = loop, 2 = set-loop-and-jump),
 * then dispatch the per-command-type handler. */
static void process_gfx_anims(void) {
    u32 state = eGFXAnimStates;

    for (int i = 0; i < NUM_GFX_ANIMS; i++, state += oGFXAnimState_Size) {
        if (!LD8(state + oGFXAnimState_IsActive))
            continue;

        /* Decrement the per-frame timer; skip if still counting. */
        s32 timer = (s32)LD16(state + oGFXAnimState_Timer) - 1;
        ST16(state + oGFXAnimState_Timer, (u16)timer);
        if (timer > 0)
            continue;

        /* Timer expired – process the current command entry. */
        u8 command = LD8(state + oGFXAnimState_Command);

        /* data_ptr = command_pos + per-command-type header size (always 8) */
        u32 data_ptr = LD32(state + oGFXAnimState_CommandPos)
                     + LD32(A_byte_8001C08 + command);

        u32 opcode = LD32(data_ptr);   /* 0 = end of list, 1 = loop, 2 = jump-to-loop */

        if (opcode == 0) {
            /* No more entries: deactivate this animation. */
            ST8(state + oGFXAnimState_IsActive, 0);
            continue;
        }

        if (opcode == 2) {
            /* Record the loop target, then jump to it. */
            data_ptr = LD32(data_ptr + 4);
            ST32(state + oGFXAnimState_LoopAddress, data_ptr);
        } else if (opcode == 1) {
            /* Jump back to previously saved loop target. */
            data_ptr = LD32(state + oGFXAnimState_LoopAddress);
        }

        /* Advance command position and load the new timer for the next entry. */
        ST32(state + oGFXAnimState_CommandPos, data_ptr);
        ST16(state + oGFXAnimState_Timer, (u16)LD32(data_ptr + 4));

        /* Dispatch the command-type handler (palette copy, tile upload, sound, etc.). */
        u32 handler = LD32(A_off_8001C24 + command);
        call_gfx_anim_handler(handler, data_ptr, command, state);
    }
}

Next ProcessGFXAnims(void) {
    process_gfx_anims();
    RETURN_TO_CALLER();
}

/* Register form: calls screenFade_StopAndFreePalettes (outside this file, no typed C
   interface).  It passes the fade-slot offset in r0 and is invoked with r0–r2 and r5
   already pushed, so the callee's clobbers are restored on return; r3 must survive
   (SYNC_SNAP/SYNC_CHECK), so r3 is set from the slot offset before the call. */
static void stop_and_free_palettes(u32 fade_slot,
                                   u32 r0, u32 r1, u32 r2,
                                   u32 r5, u32 r3, u32 lr) {
    R0 = r0; R1 = r1; R2 = r2; R3 = r3; R5 = r5; LR = lr;
    GUEST_CALL(screenFade_StopAndFreePalettes_8006330);
}

typedef struct {
    u32 r0;   /* final r0: 0 if fade started, else unchanged palette */
    u32 r1;   /* final r1: fade_flag, or 0x100 when fade_flag was 0xFF */
    u32 r2;   /* indexed fade-parameter table entry address */
    u32 add_op;   /* 1 when flags come from ADDS(0xFF,1), 0 from CMP r1,#0xFF */
} FadeResult;

/* Set up one screen-fade slot.  Returns early (no writes, palette in r0) when
 * palette == 0xFF; otherwise configures the slot at eScreenFade + fade_slot. */
static FadeResult set_screen_fade(u32 palette, u32 fade_flag,
                                  u32 fade_slot, u32 caller_r5) {
    FadeResult res;
    res.r0 = palette;
    res.r1 = fade_flag;
    res.r2 = R2;
    res.add_op = 0;

    if (palette == 0xFF) {
        return res;               /* early-out: flags stay from CMP(palette,0xFF) */
    }

    /* Pointer to this fade slot inside the eScreenFade array */
    u32 slot = A_eScreenFade + fade_slot;

    /* Release any previous palette in this slot (preserves r0–r3 via push/pop) */
    stop_and_free_palettes(fade_slot, fade_slot, fade_flag,
                           R2, caller_r5, fade_slot, LR);

    /* Record the palette index in the slot */
    ST8(slot + 1, palette);

    /* Index into the fade-parameter table (4 bytes per entry) */
    u32 params = A_off_8006040 + (palette << 2);
    res.r2 = params;

    /* Copy parameters into the fade slot */
    ST32(slot + 0x10, LD32(params));              /* first palette-pointer word  */
    ST32(slot + 0x14, LD32(params + 4));          /* second palette-pointer word */
    ST16(slot + 0x18, LD8(params + oFadeParams_Unk_0c));
    ST16(slot + 0x1C, LD8(params + oFadeParams_Unk_0d));
    ST16(slot + 8,    LD8(params + oFadeParams_Unk_0e));
    ST16(slot + 0xA,  LD8(params + oFadeParams_Unk_0f) << 4);

    /* Activate the fade */
    ST8(slot,      1);                            /* fade active */
    ST8(slot + oScreenFade_Unk_03, 1);             /* fade sub-flag */
    ST8(slot + 2,  0);                             /* reset step */

    /* Store the flag byte: 0xFF wraps to 0x100 (halfword → 0x0100) */
    if (fade_flag == 0xFF) {
        res.r1 = 0x100;
        res.add_op = 1;         /* flags from ADDS(0xFF, 1), not CMP */
    }
    ST16(slot + 4, res.r1);

    res.r0 = 0;                 /* last mov r0, #0 before the CMP r1 */
    return res;
}

/* SetScreenFade (0x08006270): configure screen-fade slot 0.
 * Entry at 0x08006274 uses slot 0x20 — same body, only fade_slot differs.
 * r0 = palette index (0xFF → no-op), r1 = flag byte (0xFF → stored as 0). */
Next SetScreenFade(void) {
    FadeResult res = set_screen_fade(R0, R1, 0, R5);
    u32 flag_base = R1 - 0xFF;                    /* CMP r1, #0xFF (SUBS)          */
    flag_base |= res.add_op * 0x101;              /* override → ADDS(0xFF,1) flags */
    R0 = res.r0; R1 = res.r1; R2 = res.r2; R3 = 0;
    cpu.flags = flag_base;                         /* nzcv from the last flag op   */
    RETURN_TO_CALLER();
}

