/*
 * SetScreenFade — start a screen fade from one of the two fade slots at
 * eScreenFade. Entry at 0x8006270 uses the slot at offset 0, entry
 * loc_8006274 the slot at offset 0x20.
 *
 * Inputs (both entries):
 *   r0 = fade id (0xFF = cancel: leave the slot untouched)
 *   r1 = destination screen (0xFF is stored bumped to 0x100)
 * All registers the original leaves behind (r0 r2 r3 r5 on cancel,
 * r0..r3 r5 after setting the fade) are reported so callers see the same
 * values. The exit flags come from the last flag-setting op on each path —
 * CMP r0,#0xFF (cancel), CMP r1,#0xFF (normal) or ADDS r1,#1 when r1 was
 * 0xFF — each of which is reproduced exactly by one ADDS with the operand
 * pair computed below, so the adapter can set them without branching.
 */
typedef struct {
    u32 r0;      /* final r0: 0 after arming a fade, unchanged (0xFF) on cancel */
    u32 r1;      /* final r1: bumped destination screen */
    u32 r2;      /* final r2: entry of the fade parameter table */
    u32 r3;      /* final r3: slot offset (0 or 0x20) */
    u32 r5;      /* final r5: address of the fade slot */
    u32 addL;    /* left operand of the ADDS that reproduces the exit flags */
    u32 addR;    /* right operand of that ADDS */
} ScreenFadeExit;

/* register form: calls screenFade_StopAndFreePalettes_8006330 outside this file, which has no typed C interface yet */
static void screenFade_stop_and_free_palettes(u32 slotOffset, u32 dstScreen, u32 callerR2, u32 fadeSlot)
{
    /* the callee sees the registers exactly as at the BL in the original */
    R0 = slotOffset;
    R1 = dstScreen;
    R2 = callerR2;
    R3 = slotOffset;
    R5 = fadeSlot;
    GUEST_CALL(screenFade_StopAndFreePalettes_8006330);
}

static ScreenFadeExit set_screen_fade(u32 slotOffset, u32 fadeId, u32 dstScreen,
                                      u32 callerR2, u32 callerR5)
{
    ScreenFadeExit out;

    if (fadeId == 0xFF) {
        /* Cancel: nothing is touched or freed, everything stays as it was. */
        out.r0 = fadeId;
        out.r1 = dstScreen;
        out.r2 = callerR2;
        out.r3 = slotOffset;
        out.r5 = callerR5;
        out.addL = 0xFFFFFFFF;          /* ADDS(0xFFFFFFFF,1) == CMP(fadeId,0xFF) == 0 */
        out.addR = 1;
        return out;
    }

    u32 slot = A_eScreenFade + slotOffset;

    /* stop any fade already running in this slot and release its palettes */
    screenFade_stop_and_free_palettes(slotOffset, dstScreen, callerR2, slot);

    ST8(slot + 1, fadeId);              /* fade kind */

    /* copy this fade's parameters from the static table */
    u32 params = A_off_8006040 + (fadeId << 2);
    ST32(slot + 0x10, LD32(params + oFadeParams_Ptr_00));
    ST32(slot + 0x14, LD32(params + oFadeParams_Ptr_04));
    /* the original stores these bytes with STRH, zero-extending them */
    ST16(slot + 0x18, LD8(params + oFadeParams_Unk_0c));
    ST16(slot + 0x1C, LD8(params + oFadeParams_Unk_0d));
    ST16(slot + 0x08, LD8(params + oFadeParams_Unk_0e));
    ST16(slot + 0x0A, LD8(params + oFadeParams_Unk_0f) << 4);

    ST8(slot, 1);                       /* fade is active */
    ST8(slot + oScreenFade_Unk_03, 1);
    ST8(slot + 2, 0);                   /* not finished */

    u32 screen = dstScreen;
    if (screen == 0xFF)
        screen = 0x100;                 /* "stay in the same screen" is stored one past 0xFF */
    ST16(slot + 4, screen);

    out.r0 = 0;
    out.r1 = screen;
    out.r2 = params;
    out.r3 = slotOffset;
    out.r5 = slot;
    if (screen == 0x100) {
        out.addL = 0xFF;                /* exactly the original's ADDS(0xFF,1) */
        out.addR = 1;
    } else {
        out.addL = screen;              /* ADDS(screen,0xFFFFFF01) == CMP(screen,0xFF) */
        out.addR = 0xFFFFFF01;
    }
    return out;
}

Next SetScreenFade(void) {
    ScreenFadeExit st = set_screen_fade(0, R0, R1, R2, R5);
    R0 = st.r0; R1 = st.r1; R2 = st.r2; R3 = st.r3; R5 = st.r5;
    SET_FLAGS_ADD(st.addL, st.addR);
    RETURN_TO_CALLER();
}

