/* Advance all active sprite GFX animation states by one frame.
 * For each active state: decrement timer; when it reaches zero, read the next command
 * from the extended data stream, handle loop opcodes, update CommandPos/Timer, and
 * dispatch the per-command handler via the function-pointer table. */
static void process_gfx_anims(void) {
    u32 state_ptr = A_eGFXAnimState0;

    for (int i = 0; i < NUM_GFX_ANIMS; i++) {
        if (LD8(state_ptr + oGFXAnimState_IsActive) == 0) {
            state_ptr += oGFXAnimState_Size;
            continue;
        }

        /* Decrement timer; skip if still counting */
        s32 timer = (s32)(u16)LD16(state_ptr + oGFXAnimState_Timer) - 1;
        ST16(state_ptr + oGFXAnimState_Timer, (u16)timer);
        if (timer > 0) {
            state_ptr += oGFXAnimState_Size;
            continue;
        }

        /* Timer expired – advance to next command entry */
        u32 cmd_type = LD8(state_ptr + oGFXAnimState_Command);
        u32 cmd_pos  = LD32(state_ptr + oGFXAnimState_CommandPos)
                       + LD32(A_byte_8001C08 + cmd_type);

        u32 entry = LD32(cmd_pos);

        if (entry == 0) {
            /* End-of-anim marker: deactivate this state */
            ST8(state_ptr + oGFXAnimState_IsActive, 0);
        } else {
            /* Resolve next position: opcodes 1/2 are loop commands */
            if (entry == 2) {
                cmd_pos = LD32(cmd_pos + 4);
                ST32(state_ptr + oGFXAnimState_LoopAddress, cmd_pos);
            } else if (entry == 1) {
                cmd_pos = LD32(state_ptr + oGFXAnimState_LoopAddress);
            }

            ST32(state_ptr + oGFXAnimState_CommandPos, cmd_pos);
            ST16(state_ptr + oGFXAnimState_Timer, LD16(cmd_pos + 4));

            /* Dispatch the command handler for this anim type */
            u32 handler = LD32(A_off_8001C24 + cmd_type);
            dispatch_anim_command(handler, state_ptr, cmd_pos);
        }

        state_ptr += oGFXAnimState_Size;
    }
}

