/* Advance every active GFX animation by one tick: decrement its frame timer,
 * and when it expires step to the next frame in its command data and run the
 * handler for that animation's command type. Slots with a still-ticking timer
 * or an inactive animation are left alone. */
static void process_gfx_anim_states(void) {
    u32 gfx_state = A_eGFXAnimState0;

    for (u32 slot = 0; slot < NUM_GFX_ANIMS; slot++, gfx_state += oGFXAnimState_Size) {
        if (LD8(gfx_state + oGFXAnimState_IsActive) == 0)
            continue;

        /* tick the frame timer; it wraps below zero, which means "fire now" */
        u32 timer = (u32)LD16(gfx_state + oGFXAnimState_Timer) - 1;
        ST16(gfx_state + oGFXAnimState_Timer, timer);
