            /* start of a new loop section */
            frame_data = LD32(entry + 4);
            ST32(gfx_state + oGFXAnimState_LoopAddress, frame_data);
        } else if (link == 1) {
            /* loop back to the remembered loop start */
            frame_data = LD32(gfx_state + oGFXAnimState_LoopAddress);
        } else {
            frame_data = entry;
