 * ProcessGFXAnims (0x08001b94)
 *
 * Ticks every active extended-GFX animation state. Each state holds a frame
 * timer and a pointer into a stream of frame entries; when the timer runs
 * out, one entry is consumed: it either ends the animation, loops back to a
 * recorded loop-start entry, or is handed to the command's handler routine
 * (palette copy, tile copy, SFX, event flag, ...) with the state as self.
 *
 * GFXAnimState layout (offsets from the disassembly):
 *   +0x00 IsActive (u8)  +0x02 Timer (u16)  +0x04 LoopAddress
 *   +0x08 CommandPos     +oGFXAnimState_Command: Command (byte offset that
 *   indexes byte_8001C08 (frame stride) and off_8001C24 (handler table))
 */

/* Opcode in the first word of each frame entry. */
enum {
    GFX_FRAME_END            = 0, /* no entries left - the animation stops */
    GFX_FRAME_JUMP_LOOP      = 1, /* resume from the recorded loop-start entry */
    GFX_FRAME_SET_LOOP_START = 2, /* the next word records the loop-start entry */
};

/* Command byte values: byte offsets into both per-command tables. */
