    GFX_CMD_COPY_PALETTE      = 0x00,
    GFX_CMD_COPY_TILES_0x20   = 0x04,
    GFX_CMD_UNKNOWN_0x08      = 0x08,
    GFX_CMD_PALETTE_TRANSFORM = 0x0c,
    GFX_CMD_PLAY_SFX          = 0x10,
    GFX_CMD_SET_EVENT_FLAG    = 0x14,
    GFX_CMD_COPY_TILES_0x40   = 0x18,
};

