    R0 = frame_entry;
    R1 = command;
    R2 = command;
    R7 = self;
    switch (command) {
    case GFX_CMD_COPY_PALETTE:      GUEST_CALL(sprite_QueueAnimFrameGfxUpload_8001C44); break;
    case GFX_CMD_COPY_TILES_0x20:   GUEST_CALL(sub_8001C94);                            break;
    case GFX_CMD_UNKNOWN_0x08:      GUEST_CALL(sub_8001C52);                            break;
    case GFX_CMD_PALETTE_TRANSFORM: GUEST_CALL(sprite_gfxAnimState_GotoNext_8002310);    break;
    case GFX_CMD_PLAY_SFX:          GUEST_CALL(sub_800232A);                            break;
    case GFX_CMD_SET_EVENT_FLAG:    GUEST_CALL(sub_8002338);                            break;
    case GFX_CMD_COPY_TILES_0x40:   GUEST_CALL(sub_8001CFC);                            break;
