}

/* Tick one active anim state: decrement its frame timer, and if it has run
 * out, consume the next frame entry from its stream. */
static void advance_gfx_anim_state(u32 state) {
    /* Decrement first so a stale zero timer also falls through to the stream. */
    u32 timer = LD16(state + oGFXAnimState_Timer) - 1;
    ST16(state + oGFXAnimState_Timer, timer);
    if ((s32)timer > 0)
        return;

    /* Step from the stream header to the current entry. */
    u32 command = LD8(state + oGFXAnimState_Command);
    u32 entry = LD32(state + oGFXAnimState_CommandPos) + LD32(A_byte_8001C08 + command);

    u32 opcode = LD32(entry);
    if (opcode == GFX_FRAME_END) {
        ST8(state + oGFXAnimState_IsActive, 0); /* no more frames - deactivate */
        return;
    }
    if (opcode == GFX_FRAME_JUMP_LOOP) {
        entry = LD32(state + oGFXAnimState_LoopAddress);
    } else if (opcode == GFX_FRAME_SET_LOOP_START) {
        entry = LD32(entry + 4);
        ST32(state + oGFXAnimState_LoopAddress, entry);
    }

    /* The new entry becomes current, its delay word the next timer value. */
    ST32(state + oGFXAnimState_CommandPos, entry);
    ST16(state + oGFXAnimState_Timer, LD32(entry + 4));
    dispatch_gfx_anim_command(command, state, entry);
}

