    u32 state = A_eGFXAnimState0;
    for (u32 index = 0; index < NUM_GFX_ANIMS; index++) {
        if (LD8(state + oGFXAnimState_IsActive))
            advance_gfx_anim_state(state);
        state += oGFXAnimState_Size;
