    GFX_ANIM_LIST_END      = 0, /* no more records: the animation finishes */
    GFX_ANIM_LIST_LOOP     = 1, /* continue from the recorded loop start */
    GFX_ANIM_LIST_SET_LOOP = 2, /* the record's second word is the loop start */
