/* Run one animation's next frame once its timer reaches zero, then hand the new
 * frame record to the command handler for its load type. */
static void advance_gfx_anim_state(u32 state) {
    /* Count the current frame down and wait while it is still running. */
    u32 timer = LD16(state + oGFXAnimState_Timer) - 1;
    ST16(state + oGFXAnimState_Timer, timer);
    if ((s32)timer > 0)
        return;

    /* Move to the next frame record; its distance from the extended data base
     * depends on the animation's load type (per-type offset table). */
    u32 command = LD8(state + oGFXAnimState_Command);
    u32 fieldOffset = LD32(A_byte_8001C08 + command);
    u32 entry = LD32(state + oGFXAnimState_CommandPos) + fieldOffset;

    u32 marker = LD32(entry);
    if (marker == GFX_ANIM_LIST_END) {
        /* Ran off the end of the command list: deactivate the animation. */
        ST8(state + oGFXAnimState_IsActive, 0);
        return;
    }
    if (marker == GFX_ANIM_LIST_SET_LOOP) {
        /* Remember where to restart from when a LOOP marker comes up later. */
        entry = LD32(entry + 4);
        ST32(state + oGFXAnimState_LoopAddress, entry);
    } else if (marker == GFX_ANIM_LIST_LOOP) {
        entry = LD32(state + oGFXAnimState_LoopAddress);
    }

    /* Sit on this record until its frame timer runs out. */
    ST32(state + oGFXAnimState_CommandPos, entry);
    ST16(state + oGFXAnimState_Timer, LD32(entry + 4));

    run_gfx_anim_command(command, fieldOffset, state, entry);
}

