/* Advance every active GFX animation: tick its timer down and, when the timer
 * expires, step it to the next command in its data stream and run that
 * command's handler. */
static void process_gfx_anims(void) {
    /* register form: the handlers are game code that may clobber r8, r9 and
     * r12; the original pushes them so its caller still sees the incoming
     * values. */
    u32 saved_r8  = R8;
    u32 saved_r9  = R9;
    u32 saved_r12 = R12;

    u32 state = A_eGFXAnimState0;
    u32 i;
    for (i = 0; i < NUM_GFX_ANIMS; i++, state += oGFXAnimState_Size) {
        if (LD8(state + oGFXAnimState_IsActive) == 0)
            continue;

        u32 timer = (u32)LD16(state + oGFXAnimState_Timer) - 1;
        ST16(state + oGFXAnimState_Timer, timer);
        if ((s32)timer > 0)
            continue;

        u32 command = LD8(state + oGFXAnimState_Command);
        /* skip this command's header to reach the frame's data */
        u32 entry = LD32(state + oGFXAnimState_CommandPos) + LD32(A_byte_8001C08 + command);
        u32 marker = LD32(entry);

        if (marker == GFX_ANIM_ENTRY_END) {
            /* no more entries: deactivate the animation */
            ST8(state + oGFXAnimState_IsActive, 0);
            continue;
        }
        if (marker == GFX_ANIM_ENTRY_SET_LOOP) {
            /* the following word becomes the loop address, then jump to it */
            entry = LD32(entry + 4);
            ST32(state + oGFXAnimState_LoopAddress, entry);
        } else if (marker == GFX_ANIM_ENTRY_LOOP) {
            /* jump back to the stored loop address */
            entry = LD32(state + oGFXAnimState_LoopAddress);
        }

        ST32(state + oGFXAnimState_CommandPos, entry);
        ST16(state + oGFXAnimState_Timer, LD32(entry + 4));
        run_gfx_anim_handler(command, state, entry);
    }

    R8  = saved_r8;
    R9  = saved_r9;
    R12 = saved_r12;
}

