        play_sound(SOUND_MENU_CUR_MOVE);
        ST8(state_ptr + 3, LD8(state_ptr + 4));
        ST8(state_ptr + 4, 8);
        ST8(state_ptr + 6, 0);
        ST8(state_ptr + 7, 0);
