    u32 row = LD8(state_ptr + 4);
    if (row >= 8) {
        begin_jack_in(state_ptr);
        return;
    }
    /* Rows 6-7 are blocked when the COMM_SAVE_DISABLED event flag is set */
    if (event_flag_set_immediate(0x17, 6) && (row == 6 || row == 7)) {
        play_sound(SOUND_CANT_JACK_IN);
        return;
    }
    play_sound(SOUND_MENU_SELECT);
    ST8(state_ptr, 0x10);
    ST8(state_ptr + 1, 4);
}

/* Main typed implementation of the PET/Comm menu per-frame update. */
static void pet_comm_menu_update(u32 state_ptr, u32 toolkit_ptr) {
    copy_bg_tiles_pet();
    copy_bg_tiles_navi_select();
    pet_menu_setup();

    if (gfx_anim_active(0x10))
        goto teardown;

    u32 timer = LD8(state_ptr + 9);
    if (timer != 0) {
        ST8(state_ptr + 9, timer - 1);
        goto teardown;
    }

    if (!screen_fade_active())
        goto teardown;

    /* START+B forces jack-in regardless of current selection */
    if (button_pressed(JOYPAD_START | JOYPAD_B)) {
        begin_jack_in(state_ptr);
        goto teardown;
    }

    if (button_pressed(JOYPAD_A)) {
        u32 row_before = LD8(state_ptr + 4);
        handle_confirm(state_ptr);
        /* "Can't jack in" (blocked rows) falls through to navigation;
         * success paths (jack-in or select) are done. */
        if (LD8(state_ptr + 4) == row_before &&
            LD8(state_ptr) != 8 && LD8(state_ptr) != 0x10) {
            navigate_pet_menu(state_ptr, toolkit_ptr, LD8(state_ptr + 4));
        }
        goto teardown;
    }

    navigate_pet_menu(state_ptr, toolkit_ptr, LD8(state_ptr + 4));

teardown:
    pet_menu_anim_update();
    pet_menu_display_update();
    pet_menu_hud_update();
}

