/* Decide whether the special battle display this routine gates should be active.
 * It is forced off while time is stopped or the battle is over; otherwise a navi
 * that is in one of the two special modes opens the gate when flag 2 is set, and
 * flag 0x10 opens it unconditionally.  `r1_in` is the caller's r1, which the
 * original only writes on the flag-check paths (2 or 0x10); it is handed back
 * unchanged through `r1_out` on the two early exits. */
static bool battle_special_ui_visible(u32 r1_in, u32 *r1_out) {
    if (battle_is_time_stop()) {
        *r1_out = r1_in;
        return false;
    }
    if (battle_is_battle_over() != 0) {
        *r1_out = r1_in;
        return false;
    }

    u32 mode = get_battle_navi_stats_byte(0, NAVI_STATS_MODE);
    bool special = (mode == NAVI_MODE_17 || mode == NAVI_MODE_18);
    if (!special) {
        mode = get_battle_navi_stats_byte(1, NAVI_STATS_MODE);
        special = (mode == NAVI_MODE_17 || mode == NAVI_MODE_18);
    }

    if (special && (battle_get_flags() & BATTLE_FLAG_2) != 0) {
        *r1_out = BATTLE_FLAG_2;
        return true;
    }
    if ((battle_get_flags() & BATTLE_FLAG_10) != 0) {
        *r1_out = BATTLE_FLAG_10;
        return true;
    }
    *r1_out = BATTLE_FLAG_10;
    return false;
}

