/* Return whether the battle is in a "can act" state.
 * Returns r0 (0 = blocked, 1 = allowed) and the last TST/CMP value for flag setup. */
static void check_battle_usable(u32 *out_result, u32 *out_flag_val) {
    u32 ts = time_stop_stat();
    if (ts != 0) {                       /* time stop active → blocked */
        *out_result = 0;
        *out_flag_val = ts;              /* flags as left by the callee */
        return;
    }

    u32 bo = battle_over_stat();
    if (bo != 0) {                       /* battle over → blocked */
        *out_result = 0;
        *out_flag_val = bo;              /* original: tst r0, r0 */
        return;
    }

    /* Does either navi carry the "soul unready" signature (0x17/0x18) in stat 0x2C? */
    u32 s0 = navi_stat_byte(0, 0x2C);
    u32 s1;
    if (s0 == 0x17 || s0 == 0x18) {
        *out_flag_val = 0;               /* caller branch taken, don't call again */
    } else {
        s1 = navi_stat_byte(1, 0x2C);
        if (s1 == 0x17 || s1 == 0x18) {
            *out_flag_val = 0;
        } else {
            /* No soul signature → only check flag 0x10 */
            u32 fl = battle_flags();
            u32 t = fl & 0x10;
            R1 = 0x10;                   /* register form: original does mov r1,#0x10 before tst */
            *out_result = (t != 0) ? 1 : 0;
            *out_flag_val = t;
            return;
        }
    }

    /* Soul-signature path: check flag 0x02 first, then 0x10 */
    u32 fl = battle_flags();
    u32 t2 = fl & 0x02;
    if (t2 != 0) {
        R1 = 0x02;                       /* register form: original does mov r1,#2 before tst */
        *out_result = 1;
        *out_flag_val = t2;
    } else {
        fl = battle_flags();             /* original calls battle_getFlags again */
        u32 t10 = fl & 0x10;
        R1 = 0x10;                       /* register form: original does mov r1,#0x10 before tst */
        *out_result = (t10 != 0) ? 1 : 0;
        *out_flag_val = t10;
    }
}

