/*
 * PET menu handler: manages background redraw, countdown, START+B/A
 * selection, empty-slot jack-in animation, and cursor navigation
 * between PET slots and between slot/nav-cursor rows.
 */
static void pet_menu_logic(u32 state_ptr, u32 toolkit_ptr) {
    /* Redraw background tiles for the PET and Navi-select screens */
    call_copy_bg_pet();
    call_copy_bg_navi_select();
    call_pet_menu_update();

    /* If the PET-select animation (ID 0x10) is playing, skip input handling */
    if (gfx_anim_active(GFX_ANIM_PET_SELECT))
        goto final_render;

    /* Decrement the cursor countdown timer if it is still running */
    u32 countdown = LD8(state_ptr + oPetCountdown);
    if (countdown != 0) {
        ST8(state_ptr + oPetCountdown, countdown - 1);
        goto final_render;
    }

    /* Timer expired: only respond to input if a screen fade is not in progress */
    if (!screen_fade_active())
        goto final_render;

    /* --- Input handling during countdown-zero phase --- */
    bool confirm = button_pressed(BTN_START_B);
    if (!confirm)
        confirm = button_pressed(BTN_A);

    if (confirm) {
        u32 slot = LD8(state_ptr + oPetCurSlot);

        if (slot >= PET_SLOT_EMPTY) {
            /* Empty slot: trigger jack-in animation */
            ST8(state_ptr + oPetMode, PET_MODE_JACKIN);
            ST8(state_ptr + oPetJackPending, 1);
            load_gfx_anim(A_byte_811EB04);
            load_gfx_anim(A_byte_811EB5C);
        } else {
            /* Valid slot: check whether saving is disabled for this PET */
            bool save_disabled = event_flag_set(EVENT_PET_COMM_SAVE_DISABLED);

            if (save_disabled && (slot == 6 || slot == 7)) {
                /* Slots 6/7 with save-disabled flag: can't jack in */
                play_sound(SOUND_CANT_JACK_IN);
                goto handle_cursor_move;
            }

            /* Acceptable selection: play confirm, enter active mode */
            play_sound(SOUND_MENU_SELECT);
            ST8(state_ptr + oPetMode, PET_MODE_ACTIVE);
            ST8(state_ptr + oPetSubMode, PET_JACKIN_SUB);
        }
        goto final_render;
    }

handle_cursor_move:
    /* --- Cursor movement --- */
    u32 slot = LD8(state_ptr + oPetCurSlot);

    if (slot >= PET_SLOT_EMPTY) {
        /* On the empty row: UP/DOWN/LEFT returns to the nav-cursor row */
        if (button_pressed(BTN_DUPDOWNL)) {
            play_sound(SOUND_MENU_CUR_MOVE);
            /* Swap current slot with saved slot (go back to nav-cursor) */
            ST8(state_ptr + oPetCurSlot, LD8(state_ptr + oPetSavedSlot));
            ST8(state_ptr + oPetCountdown, PET_COUNTDOWN_MOVE);
        }
        goto final_render;
    }

    if (button_pressed(BTN_RIGHT)) {
        /* Move right: go to the empty/no-selection row */
        play_sound(SOUND_MENU_CUR_MOVE);
        ST8(state_ptr + oPetSavedSlot, LD8(state_ptr + oPetCurSlot));
        ST8(state_ptr + oPetCurSlot, PET_SLOT_EMPTY);
        ST8(state_ptr + oPetAnimX, 0);
        ST8(state_ptr + oPetAnimY, 0);
        goto final_render;
    }

    /* No directional button: let the shared cursor helper handle UP/DOWN */
    u32 joypad_ptr = LD32(toolkit_ptr + oToolkit_JoypadPtr);
    u16 held = (u16)LD16(joypad_ptr + oJoypad_LowSensitivityHeld);
    u32 new_slot = cursor_move_updown(held, PET_SLOT_EMPTY, 1, slot);
    ST8(state_ptr + oPetCurSlot, (u8)new_slot);

final_render:
    /* Redraw background, window, and sprites; leaves nz/c/v and r0-r3 */
    call_render_bg();
    call_render_window();
    call_render_sprites();
}

