/* Handle one frame of player input for the Navi-select menu. */
static void navi_select_handle_input(u32 menu, u32 toolkit) {
    if (button_pressed(JOYPAD_START | JOYPAD_B)) {
        navi_select_confirm_jack_in(menu);
        return;
    }

    if (button_pressed(JOYPAD_A)) {
        u8 cursor = LD8(menu + oNaviSel_Cursor);
        if (cursor >= 8) {
            navi_select_confirm_jack_in(menu);
            return;
        }
        /* A on a jack-in slot: refuse if PET communication saving is disabled. */
        if (event_flag_set_immediate(EVENT_PET_COMM_SAVE_DISABLED, 6) &&
            (cursor == 6 || cursor == 7)) {
            play_sound_effect(SOUND_CANT_JACK_IN);
            /* fall through to the cursor-movement handling below */
        } else {
            play_sound_effect(SOUND_MENU_SELECT);
            ST8(menu + oNaviSel_Mode, 0x10);
            ST8(menu + oNaviSel_SubMode, 4);
            return;
        }
    }

    if (LD8(menu + oNaviSel_Cursor) >= 8) {
        /* On the "more" slot: any of down/up/left returns to the saved slot. */
        if (!button_pressed(JOYPAD_DOWN | JOYPAD_UP | JOYPAD_LEFT))
            return;
        play_sound_effect(SOUND_MENU_CUR_MOVE);
        ST8(menu + oNaviSel_Cursor, LD8(menu + oNaviSel_SavedCursor));
        ST8(menu + oNaviSel_Delay, 3);
        return;
    }

    if (button_pressed(JOYPAD_RIGHT)) {
        /* Move onto the "more" slot. */
        play_sound_effect(SOUND_MENU_CUR_MOVE);
        ST8(menu + oNaviSel_SavedCursor, LD8(menu + oNaviSel_Cursor));
        ST8(menu + oNaviSel_Cursor, 8);
        ST8(menu + oNaviSel_ScrollX, 0);
        ST8(menu + oNaviSel_ScrollY, 0);
        return;
    }

    {
        u32 held = LD16(LD32(toolkit + oToolkit_JoypadPtr) + oJoypad_LowSensitivityHeld);
        ST8(menu + oNaviSel_Cursor,
            (u8)menu_move_cursor_up_down(held, 8, 1, LD8(menu + oNaviSel_Cursor)));
    }
}

/* Per-frame update of the PET / Navi-select screen.
 * menu    = menu state block (r5)
 * toolkit = toolkit base, used to read the joypad (r10) */
static void navi_select_menu_update(u32 menu, u32 toolkit) {
    copy_background_tiles_pet();
    copy_background_tiles_navi_select();
    navi_select_redraw();

    if (!gfx_anim_active(0x10)) {
        if (LD8(menu + oNaviSel_Delay) != 0) {
            ST8(menu + oNaviSel_Delay, LD8(menu + oNaviSel_Delay) - 1);
        } else if (!screen_fade_running()) {
            navi_select_handle_input(menu, toolkit);
        }
    }

    navi_select_draw_a();
    navi_select_draw_b();
    navi_select_draw_c();   /* leaves nz/c/v for the caller */
}

