/* ProcessGFXAnims: 08001B94
 *
 * Runs the NUM_GFX_ANIMS GFX animation slots.  Each active slot counts its timer down; when
 * the timer reaches zero the next record of the slot's command stream is decoded and the
 * handler it names (palette/tile copy, sound effect, event flag, ...) is executed.
 *
 * The handlers may clobber r4-r9/r12, which this function's callers keep live values in, so
 * those are taken in on entry and handed back untouched.  r10/r11 are left holding whatever
 * the last handler put there, exactly as in the original. */

typedef struct {
    u32 r4, r5, r6, r7, r8, r9, r12;
} GfxAnimSavedRegs;

/* Handlers are picked from the off_8001C24 table by the slot's command byte
 * (0x00, 0x04, ... 0x18); each one takes the slot state in r7 and the data record in r0. */
/* register form: calls the GFX anim handlers outside this file, which have no typed C interface yet */
static void run_gfx_anim_handler(u32 command, u32 anim, u32 data) {
    R0 = data;
    R1 = command;
    R7 = anim;
    switch (command) {
    case 0x00: GUEST_CALL(sprite_QueueAnimFrameGfxUpload_8001C44); break; /* copy palette */
    case 0x04: GUEST_CALL(sub_8001C94); break;                           /* copy 0x20-sized tiles */
    case 0x08: GUEST_CALL(sub_8001C52); break;
    case 0x0C: GUEST_CALL(sprite_gfxAnimState_GotoNext_8002310); break;  /* manual palette transform */
    case 0x10: GUEST_CALL(sub_800232A); break;                           /* play sound effect */
    case 0x14: GUEST_CALL(sub_8002338); break;                           /* set or clear event flag */
    case 0x18: GUEST_CALL(sub_8001CFC); break;                           /* copy 0x40-sized tiles */
    }
}

static GfxAnimSavedRegs process_gfx_anims(GfxAnimSavedRegs saved) {
    u32 anim = A_eGFXAnimState0;

    for (u32 i = 0; i < NUM_GFX_ANIMS; i++, anim += oGFXAnimState_Size) {
        if (!LD8(anim + oGFXAnimState_IsActive))
            continue;

        /* Tick the slot's timer; the command only runs once it has expired. */
        s32 timer = (s32)LD16(anim + oGFXAnimState_Timer) - 1;
        ST16(anim + oGFXAnimState_Timer, (u16)timer);
        if (timer > 0)
            continue;

        u8 command = LD8(anim + oGFXAnimState_Command);
        u32 data = LD32(anim + oGFXAnimState_CommandPos) + LD32(A_byte_8001C08 + command);

        u32 op = LD32(data);
        if (op == 0) {
            /* End of the command stream: the slot goes inactive. */
            ST8(anim + oGFXAnimState_IsActive, 0);
            continue;
        }
        if (op == 2) {
            /* Remember the loop address and continue from it. */
            data = LD32(data + 4);
            ST32(anim + oGFXAnimState_LoopAddress, data);
