/* Battle "force end" check: decides whether the current battle should be cut
 * short right away. It returns 1 when time-stop is active, the battle is
 * already over, a navi is in one of the "out" states reported by its stats
 * byte at 0x2C (0x17 or 0x18) with battle flag bit 2 set, or battle flag
 * bit 0x10 is set. On the early bail-out paths r1 is left as it came in,
 * afterwards it holds the flag mask the original last tested (2 or 0x10). */
typedef struct { u32 result; u32 r1; } force_end_result;

