static force_end_result battle_check_forced_end(u32 r1_in) {
    force_end_result out;
    out.r1 = r1_in;
    out.result = 0;

    if (battle_time_stop() || battle_is_over())
        return out;               /* r1 untouched, result 0 */

    /* Either navi sitting in state 0x17/0x18 makes flag bit 2 significant. */
    u32 stats0 = navi_stats_byte(0, 0x2C);
    bool navi_out = (stats0 == 0x17 || stats0 == 0x18);

    if (!navi_out) {
        u32 stats1 = navi_stats_byte(1, 0x2C);
        navi_out = (stats1 == 0x17 || stats1 == 0x18);
    }

    if (navi_out) {
        out.r1 = 2;
        if (battle_flags() & 2) {
            out.result = 1;
            return out;
        }
    }

    out.r1 = 0x10;
    out.result = (battle_flags() & 0x10) != 0 ? 1 : 0;
    return out;
}

