static void handle_menu_input(u32 menu, u32 toolkit) {
    u32 slot = LD8(menu + 4);

    if (button_pressed(JOYPAD_START | JOYPAD_B) || !button_pressed(JOYPAD_A)
        || (s32)slot >= 8) {
        /* Back out to the jack-in screen. */
        ST8(menu, 8);
        ST8(menu + 0xD, 1);
        load_gfx_anim(A_byte_811EB04);
        load_gfx_anim(A_byte_811EB5C);
