        /* These two icons lead to the save-data menu; refuse if it is locked. */
        play_sound(SOUND_CANT_JACK_IN);
        return;
    }

    play_sound(SOUND_MENU_SELECT);
    ST8(menu, 0x10);              /* state: opening the selected icon's submenu */
    ST8(menu + 1, 4);

    /* Cursor movement runs on every non-cancel frame. */
