        /* Already inside a submenu: down/up/left moves back to the icons. */
        if (button_pressed(JOYPAD_DOWN | JOYPAD_UP | JOYPAD_LEFT)) {
            play_sound(SOUND_MENU_CUR_MOVE);
            ST8(menu + 4, LD8(menu + 3));   /* restore the remembered slot */
            ST8(menu + 9, 3);               /* settle delay */
