        u32 joypad = LD32(toolkit + oToolkit_JoypadPtr);
        u32 held = LD16(joypad + oJoypad_LowSensitivityHeld);
        ST8(menu + 4, move_cursor_up_down(held, 8, 1, slot));
    }
}

