/* Read current menu cursor (pet item index) from state struct. */
static u32 pet_cursor(u32 st) { return LD8(st + oPetMenu_Cursor); }

/* Begin the jack-in sequence: set state=8, raise flag, load two anim scripts. */
static void begin_jack_in(u32 st) {
    ST8(st + oPetMenu_State, PET_MENU_STATE_JACK_IN);
    ST8(st + oPetMenu_JackInFlag, 1);
    load_gfx_anim(A_byte_811EB04);
    load_gfx_anim(A_byte_811EB5C);
