/* Confirm selection of a pet item: play sound, transition to "selected" state. */
static void select_pet_item(u32 st) {
    play_sound(SOUND_MENU_SELECT);
    ST8(st + oPetMenu_State, PET_MENU_STATE_SELECTED);
    ST8(st + oPetMenu_SubState, PET_MENU_SUB_SELECTED);
