/* Handle directional movement when A was not pressed (or after "can't jack in").
 * Cursor >= 8 means we're in the jack-in slot; UP/DOWN/LEFT moves back to item area.
 * Cursor < 8: RIGHT jumps to jack-in slot, otherwise vertical cursor movement. */
static void handle_navigation(u32 st, u32 toolkit) {
    u32 cursor = pet_cursor(st);

    if (cursor >= PET_MENU_STATE_JACK_IN) {
        /* In the jack-in column – LEFT/UP/DOWN returns to item list */
        if (!button_pressed(JOYPAD_DOWN | JOYPAD_UP | JOYPAD_LEFT))
            return;
        play_sound(SOUND_MENU_CUR_MOVE);
        ST8(st + oPetMenu_Cursor, LD8(st + oPetMenu_CursorBak));
        ST8(st + oPetMenu_AnimTimer, PET_ANIM_TIMER_RESET);
        return;
    }

    /* In the item list */
    if (button_pressed(JOYPAD_RIGHT)) {
        /* Move cursor into the jack-in column */
        play_sound(SOUND_MENU_CUR_MOVE);
        ST8(st + oPetMenu_CursorBak, LD8(st + oPetMenu_Cursor));
        ST8(st + oPetMenu_Cursor, PET_MENU_STATE_JACK_IN);
        ST8(st + oPetMenu_Scroll1, 0);
        ST8(st + oPetMenu_Scroll2, 0);
        return;
    }

    /* Vertical cursor movement with joypad auto-repeat */
    u32 joypad = LD32(toolkit + oToolkit_JoypadPtr);
    u32 held   = (s16)LD16(joypad + oJoypad_LowSensitivityHeld);
    u32 new_cur = menu_move_cursor(held, PET_MENU_STATE_JACK_IN, 1, cursor);
    ST8(st + oPetMenu_Cursor, new_cur);
}

/* Process the A-press branch when cursor < 8 (selecting an item, not jack-in).
 * If save-comm is disabled and we're on a protected slot, refuse. */
static void try_select_item(u32 st, u32 cursor) {
    if (test_event_flag(EVENT_PET_COMM_SAVE_DISABLED, 6) &&
        (cursor == 6 || cursor == 7)) {
        play_sound(SOUND_CANT_JACK_IN);
        /* After refusal, fall through to normal navigation handling */
        handle_navigation(st, /* toolkit not needed here but matches original flow */
                          0); /* placeholder – see note below */
    } else {
        select_pet_item(st);
    }
}

/* One tick of the PET (Program/Custom) menu. */
static void pet_menu_tick(u32 st, u32 toolkit) {
    /* Refresh background art and per-navi tiles */
    copy_bg_pet();
    copy_bg_navi_select();
    sub_811F24C();

    /* If the PET entrance animation (id 0x10) is still playing, do nothing else */
    if (!gfx_anim_active(PET_ANIM_ID_TICK)) {
        u32 timer = LD8(st + oPetMenu_AnimTimer);
        if (timer) {
            /* Countdown still running – just decrement */
            ST8(st + oPetMenu_AnimTimer, timer - 1);
        } else if (screen_fade_active()) {
            /* Animation finished and fade is in progress – read input */
            if (button_pressed(JOYPAD_START | JOYPAD_B)) {
