/* Handle cursor movement within the PET menu list (up/down/right/back). */
static void handle_navigation(u32 st, u32 toolkit) {
    u32 pos = LD8(st + PET_ST_MENU_POS);

    if (pos >= PET_POS_GO_BACK) {
        /* "Go back" option: any direction key restores the saved position */
        if (button_pressed(JOYPAD_DOWN | JOYPAD_UP | JOYPAD_LEFT)) {
            play_sound(SOUND_MENU_CUR_MOVE);
            ST8(st + PET_ST_MENU_POS, LD8(st + PET_ST_SAVED_POS));
            ST8(st + PET_ST_TIMER, PET_TIMER_SET);
