    } else {
        if (button_pressed(JOYPAD_RIGHT)) {
            /* Move into sub-menu */
            play_sound(SOUND_MENU_CUR_MOVE);
            ST8(st + PET_ST_SAVED_POS, (u8)pos);
            ST8(st + PET_ST_MENU_POS, PET_POS_GO_BACK);
            ST8(st + PET_ST_CUR_OFF1, 0);
            ST8(st + PET_ST_CUR_OFF2, 0);
        } else {
            /* Scroll cursor up/down */
            u32 joypad = LD32(toolkit + oToolkit_JoypadPtr);
            u16 held = LD16(joypad + oJoypad_LowSensitivityHeld);
            u8 new_pos = menu_cursor_move(held, 8, 1, pos);
            ST8(st + PET_ST_MENU_POS, new_pos);
        }
    }
}

/* Main tick: update animation, timers, and process button input for the
 * PET communication screen.  state_ptr (r5) points to the menu struct;
 * toolkit_ptr (r10) gives access to the joypad. */
static void pet_menu_update(u32 st, u32 toolkit) {
    call_copy_bg_pet();
    call_copy_bg_navi();
    call_update_phase();

    /* Gate: only respond to buttons when no animation plays,
     * the countdown has expired, and the screen is mid-fade. */
    bool buttons_live = false;
    if (!gfx_anim_active(0x10)) {
        u32 timer = LD8(st + PET_ST_TIMER);
        if (timer != 0) {
            ST8(st + PET_ST_TIMER, timer - 1);
        } else if (screen_fade_active()) {
            buttons_live = true;
        }
    }

    bool do_nav = false;

    if (buttons_live) {
        u32 pos = LD8(st + PET_ST_MENU_POS);

        if (button_pressed(JOYPAD_START | JOYPAD_B) ||
            (button_pressed(JOYPAD_A) && pos >= PET_POS_GO_BACK)) {
            /* Begin jack-in sequence */
            ST8(st + PET_ST_STATE, PET_STATE_JACK_IN);
            ST8(st + PET_ST_JACK_FLAG, 1);
            load_gfx_anim(A_byte_811EB04);
            load_gfx_anim(A_byte_811EB5C);

        } else if (button_pressed(JOYPAD_A)) {
            /* A pressed on a PET (pos < 8): attempt selection */
            if (event_flag_set(EVENT_PET_COMM_SAVE_DISABLED) &&
                (pos == 6 || pos == 7)) {
                /* Save disabled for this PET – play deny and fall to nav */
                play_sound(SOUND_CANT_JACK_IN);
                do_nav = true;
            } else {
                play_sound(SOUND_MENU_SELECT);
                ST8(st + PET_ST_STATE, PET_STATE_CONFIRMED);
                ST8(st + PET_ST_SUBSTATE, 4);
            }
        } else {
            do_nav = true;
        }
    }

    if (do_nav) {
        handle_navigation(st, toolkit);
    }

    call_tail_anim();
    call_tail_draw();
    call_tail_update();
}

