/* Move the PET cursor between the menu list (0..7) and the jack-in icon (8). */
static void move_pet_cursor(u8 *work, u32 toolkit) {
    u32 cursor = LD8(work + 4);

    if (cursor >= 8) {
        /* over the icon: any of DOWN/UP/LEFT returns to the list position */
        if (!is_button_pressed(JOYPAD_DOWN | JOYPAD_UP | JOYPAD_LEFT))
            return;
        play_sound_effect(SOUND_MENU_CUR_MOVE);
        ST8(work + 4, LD8(work + 3));   /* restore remembered list position */
        ST8(work + 9, 3);               /* brief input lockout */
        return;
    }

    if (is_button_pressed(JOYPAD_RIGHT)) {
        play_sound_effect(SOUND_MENU_CUR_MOVE);
        ST8(work + 3, LD8(work + 4));   /* remember list position */
        ST8(work + 4, 8);               /* cursor -> jack-in icon */
        ST8(work + 6, 0);
        ST8(work + 7, 0);
        return;
    }

    /* while in the list: up/down scrolls the three entries at reduced speed,
     * using the low-sensitivity held-button state the toolkit tracks */
    u32 held = LD16(LD32(toolkit + oToolkit_JoypadPtr) + oJoypad_LowSensitivityHeld);
    ST8(work + 4, move_cursor_up_down(held, 8, 1, cursor));
}

/* Input handling for the PET screen. Returns early (without touching state)
 * while an animation plays, the lockout counts down, or a fade is running. */
static void handle_pet_input(u8 *work, u32 toolkit) {
    u32 lockout = LD8(work + 9);
    if (lockout != 0) {
        ST8(work + 9, lockout - 1);
        return;
    }

    if (!is_screen_fade_active())
        return;

    /* START or B cancels back out of the PET screen */
    if (is_button_pressed(JOYPAD_START | JOYPAD_B)) {
        jack_out_of_pet(work);
        return;
    }

    if (!is_button_pressed(JOYPAD_A)) {
        move_pet_cursor(work, toolkit);
        return;
    }

    u32 cursor = LD8(work + 4);
    if (cursor >= 8) {
        /* A over the jack-in icon acts like B/START */
        jack_out_of_pet(work);
        return;
    }

    /* A on a list entry: entries 6/7 refuse while PET save/comm is disabled */
    if (event_flag_from_immediate(EVENT_PET_COMM_SAVE_DISABLED, 6)
            && (cursor == 6 || cursor == 7)) {
        play_sound_effect(SOUND_CANT_JACK_IN);
    } else {
        play_sound_effect(SOUND_MENU_SELECT);
        ST8(work + 0, 0x10);            /* advance to the next screen */
        ST8(work + 1, 4);               /* selected-entry parameter for it */
    }
    move_pet_cursor(work, toolkit);
}

