/*
 * PET communication menu: redraws the background, manages a short input-lock
 * timer, then handles cursor movement and selection (start comm / jack in).
 * state  = pointer to PET menu state block (originally r5)
 * toolkit = pointer to toolkit (originally r10)
 */
static void pet_comm_update(u32 state, u32 toolkit) {
    /* Refresh background tiles and navi-select sprites */
    call_copy_bg_pet();
    call_copy_bg_navi_select();
    call_update_pet_text();

    /* While a transition animation is playing, skip all input processing */
    if (!gfx_anim_active(0x10)) {
        u8 timer = LD8(state + PET_STATE_TIMER);

        if (timer != 0) {
            /* Countdown still running – lock input for a few frames */
            ST8(state + PET_STATE_TIMER, timer - 1);
        } else if (screen_fade_active()) {
            /* Fade is in progress; accept menu navigation */
            u8 cursor = LD8(state + PET_STATE_CURSOR);
            bool enter_comm = button_pressed(JOYPAD_START | JOYPAD_B);
            bool a_press = button_pressed(JOYPAD_A);
            bool do_navigate = false;

            if (enter_comm) {
                /* Start+B: begin communication immediately */
                ST8(state + PET_STATE_MODE, 8);
                ST8(state + PET_STATE_ENTER_COMM, 1);
                load_gfx_anim(GFX_ANIM_SCRIPT_COMM_ENTER);
                load_gfx_anim(GFX_ANIM_SCRIPT_COMM_BG);
            } else if (a_press) {
                if (cursor >= 8) {
                    /* A on COMM entry: same as Start+B */
                    ST8(state + PET_STATE_MODE, 8);
                    ST8(state + PET_STATE_ENTER_COMM, 1);
                    load_gfx_anim(GFX_ANIM_SCRIPT_COMM_ENTER);
                    load_gfx_anim(GFX_ANIM_SCRIPT_COMM_BG);
                } else if (event_flag_set(FLAG_PET_COMM_SAVE_DISABLED, 6)
                           && (cursor == 6 || cursor == 7)) {
                    /* Slot 6/7 blocked by save-disable flag */
                    play_sound(SOUND_CANT_JACK_IN);
                    do_navigate = true;
                } else {
                    /* Select a navi slot */
                    play_sound(SOUND_MENU_SELECT);
                    ST8(state + PET_STATE_MODE, 0x10);
                    ST8(state + PET_STATE_SUBMODE, 4);
                }
            } else {
                do_navigate = true;
            }

            if (do_navigate) {
                if (cursor >= 8) {
                    /* On COMM entry: Down/Up/Left returns to navi list */
                    if (button_pressed(JOYPAD_DOWN | JOYPAD_UP | JOYPAD_LEFT)) {
                        play_sound(SOUND_MENU_CUR_MOVE);
                        ST8(state + PET_STATE_CURSOR, LD8(state + PET_STATE_SAVED_CURSOR));
                        ST8(state + PET_STATE_TIMER, 3);
                    }
                } else if (button_pressed(JOYPAD_RIGHT)) {
                    /* On a navi slot: Right moves to COMM entry */
                    play_sound(SOUND_MENU_CUR_MOVE);
                    ST8(state + PET_STATE_SAVED_CURSOR, LD8(state + PET_STATE_CURSOR));
                    ST8(state + PET_STATE_CURSOR, 8);
                    ST8(state + PET_STATE_FLAG6, 0);
                    ST8(state + PET_STATE_FLAG7, 0);
                } else {
                    /* Up/Down scrolls through navi slots */
                    u32 joypad = LD32(toolkit + oToolkit_JoypadPtr);
                    u32 held = LD16(joypad + oJoypad_LowSensitivityHeld);
                    u32 new_pos = menu_move_cursor(held, 8, 1, cursor);
                    ST8(state + PET_STATE_CURSOR, new_pos);
                }
            }
        }
    }

    /* Post-update: refresh HUD elements */
    call_sub_811F1B8();
    call_sub_811F0C8();
    call_sub_811F11C();
}

