typedef struct {
    u32 result;     /* caller-visible r0: 1 = gate open, 0 = gate closed */
    u32 r1;         /* caller-visible r1 on exit */
    u32 flag_test;  /* value whose zero/nonzero state the adapter reproduces as the exit N/Z flags */
} GateResult;

/* sub_800A1D0: gate deciding whether the effect a caller wants to apply may
 * run.  It stays closed while the battle clock is stopped or the battle is
 * over; otherwise it opens only when one of the two navis is in one of the
 * checked forms and the matching battle-flag situation holds.  Callers also
 * branch on the exit flags, so every path describes them via flag_test. */
static GateResult gate_state(void) {
    GateResult res;

    bool time_stop = time_stop_active();
    /* register form: on the two early-exit paths the original leaves the
     * callee's outgoing r1 visible to sub_800A1D0's callers, and that leftover
     * exists only in the guest register file (the callee clobbered r0-r3) */
    u32 time_stop_r1 = R1;
    if (time_stop) {
        res.result = 0;
        res.r1 = time_stop_r1;
        res.flag_test = time_stop;    /* predicate is true here; set N/Z from it */
        return res;
    }

    u32 battle_over = battle_over_result();
    u32 battle_over_r1 = R1;          /* register form: see the note above */
    if (battle_over != 0) {
        res.result = 0;
        res.r1 = battle_over_r1;
        res.flag_test = battle_over;  /* original: tst r0, r0 */
        return res;
    }

    /* Either navi being in one of the checked forms opens the form gate. */
    u32 navi_form = navi_stat(0, NAVI_STAT_FORM);
    bool form_gate_open = (navi_form == GATE_FORM_A || navi_form == GATE_FORM_B);
    if (!form_gate_open) {
        u32 other_form = navi_stat(1, NAVI_STAT_FORM);
        form_gate_open = (other_form == GATE_FORM_A || other_form == GATE_FORM_B);
    }

    /* With the form gate open, bit 2 of the battle flags ends it immediately.
     * Note the original re-reads the flags for the second test. */
    if (form_gate_open) {
        u32 flags = battle_flags();
        if (flags & GATE_FLAG_A) {
            res.result = 1;
            res.r1 = GATE_FLAG_A;
            res.flag_test = flags & GATE_FLAG_A;  /* original: tst r0, r1 */
            return res;
        }
    }

    /* Otherwise the gate state tracks bit 0x10 of the battle flags. */
    u32 flags = battle_flags();
    res.flag_test = flags & GATE_FLAG_B;      /* original: tst r0, r1 */
    res.r1 = GATE_FLAG_B;
    res.result = (flags & GATE_FLAG_B) != 0 ? 1 : 0;
    return res;
}

/* sub_800A1D0() -> r0 = 1 when the gate is open, else r0 = 0 */
Next sub_800A1D0(void) {
    GateResult res = gate_state();
    R0 = res.result;
    R1 = res.r1;
    SET_FLAGS_NZ(res.flag_test);
    RETURN_TO_CALLER();
}

