/* Start the jack-in transition and play its animation. */
static void open_jack_in(u32 menu) {
    ST8(menu + PET_MENU_MODE, 8);
    ST8(menu + PET_MENU_JACKIN_FLAG, 1);
    load_gfx_anim(byte_811EB04);
    load_gfx_anim(byte_811EB5C);
}

/* Move the cursor: between the navi grid and the jack-in button, or up/down inside the grid. */
static void move_pet_menu_cursor(u32 menu, u32 toolkit) {
    if (LD8(menu + PET_MENU_CURSOR) >= 8) {
        /* Sitting on the jack-in button: down/up/left returns to the navi grid. */
        if (button_pressed(JOYPAD_DOWN | JOYPAD_UP | JOYPAD_LEFT)) {
            play_sound_effect(SOUND_MENU_CUR_MOVE);
            ST8(menu + PET_MENU_CURSOR, LD8(menu + PET_MENU_PREV_CURSOR));
            ST8(menu + PET_MENU_REPEAT_DELAY, 3);
        }
        return;
    }

    if (button_pressed(JOYPAD_RIGHT)) {
        /* Leave the navi grid for the jack-in button. */
        play_sound_effect(SOUND_MENU_CUR_MOVE);
        ST8(menu + PET_MENU_PREV_CURSOR, LD8(menu + PET_MENU_CURSOR));
        ST8(menu + PET_MENU_CURSOR, 8);
        ST8(menu + PET_MENU_GRID_A, 0);
        ST8(menu + PET_MENU_GRID_B, 0);
        return;
    }

    /* Up/down inside the navi grid (also the key repeat while a direction is held). */
    u32 held = LD16(LD32(toolkit + oToolkit_JoypadPtr) + oJoypad_LowSensitivityHeld);
    ST8(menu + PET_MENU_CURSOR, menu_move_cursor_up_down(held, 8, 1, LD8(menu + PET_MENU_CURSOR)));
}

/* Handle a frame of player input for the PET jack-in menu. */
static void pet_jack_menu_input(u32 menu, u32 toolkit) {
    if (button_pressed(JOYPAD_START | JOYPAD_B)) {
        open_jack_in(menu);
        return;
    }

    if (button_pressed(JOYPAD_A)) {
        u8 cursor = LD8(menu + PET_MENU_CURSOR);
        if (cursor >= 8) {
            open_jack_in(menu);
            return;
        }
        if (event_flag_set(EVENT_PET_COMM_SAVE_DISABLED) && (cursor == 6 || cursor == 7)) {
            /* These two slots cannot be used while the flag is set; the cursor still moves. */
            play_sound_effect(SOUND_CANT_JACK_IN);
        } else {
            play_sound_effect(SOUND_MENU_SELECT);
            ST8(menu + PET_MENU_MODE, 0x10);
            ST8(menu + PET_MENU_SUBMODE, 4);
            return;
        }
    }

    move_pet_menu_cursor(menu, toolkit);
}

/* Per-frame update of the PET "jack in" (navi select) screen. */
static void pet_jack_screen_update(u32 menu, u32 toolkit) {
    copy_background_tiles_pet();
    copy_background_tiles_navi_select();
    pet_menu_draw_background();

    if (gfx_anim_active(PET_MENU_GFX_ANIM)) {
        /* The open/close animation is still playing. */
