        ST8(menu + PET_MENU_REPEAT_DELAY, LD8(menu + PET_MENU_REPEAT_DELAY) - 1);
    } else if (screen_fade_ready()) {
        pet_jack_menu_input(menu, toolkit);
    }

    pet_menu_draw_1();
    pet_menu_draw_2();
    pet_menu_draw_3();
}

