/* Cursor movement: left/right between the list and the right column,
 * up/down within the right column, otherwise free movement in the list. */
static void pet_comm_move_cursor(u32 state, u32 toolkit)
{
    if (LD8(state + PETCOMM_CURSOR) >= 8) {
        /* Right column: up/down/left returns to the remembered list row. */
        if (is_button_pressed(JOYPAD_DOWN | JOYPAD_UP | JOYPAD_LEFT)) {
            play_sound_effect(SOUND_MENU_CUR_MOVE);
            ST8(state + PETCOMM_CURSOR, LD8(state + PETCOMM_PREV_CURSOR));
            ST8(state + PETCOMM_INPUT_DELAY, 3);
