            play_sound_effect(SOUND_MENU_CUR_MOVE);
            ST8(state + PETCOMM_PREV_CURSOR, LD8(state + PETCOMM_CURSOR));
            ST8(state + PETCOMM_CURSOR, 8);
            ST8(state + PETCOMM_UNK6, 0);
            ST8(state + PETCOMM_UNK7, 0);
        } else {
            u32 joypad = LD32(toolkit + oToolkit_JoypadPtr);
            u32 held = LD16(joypad + oJoypad_LowSensitivityHeld);
            ST8(state + PETCOMM_CURSOR,
                menu_move_cursor_up_down(held, 8, 1, LD8(state + PETCOMM_CURSOR)));
        }
    }
