 * and fall back to ordinary cursor movement. */
static void pet_comm_confirm_selection(u32 state, u32 toolkit)
{
    u8 cursor = LD8(state + PETCOMM_CURSOR);

    if (test_event_flag_immediate(EVENT_PET_COMM_SAVE_DISABLED, 6) &&
        (cursor == 6 || cursor == 7)) {
        play_sound_effect(SOUND_CANT_JACK_IN);
        pet_comm_move_cursor(state, toolkit);
    } else {
        play_sound_effect(SOUND_MENU_SELECT);
        ST8(state + PETCOMM_MODE, 0x10);
        ST8(state + PETCOMM_SUBMODE, 4);
    }
}

/* One frame of button handling once the screen is ready for input. */
static void pet_comm_handle_input(u32 state, u32 toolkit)
{
    if (is_button_pressed(JOYPAD_START | JOYPAD_B)) {
        pet_comm_close(state);
        return;
    }
    if (!is_button_pressed(JOYPAD_A)) {
        pet_comm_move_cursor(state, toolkit);
        return;
    }
    if (LD8(state + PETCOMM_CURSOR) < 8)
        pet_comm_confirm_selection(state, toolkit);
    else
        pet_comm_close(state);
}

