static void build_npc_event_tables(u32 start_flag, u32 count,
                                   u32 *out_r1, u32 *out_r2, u32 *out_r3,
                                   u32 *out_cmp_b) {
    zero_fill_by_byte(A_unk_2026700, NPC_TBL_SIZE);

    *out_r1 = count;
    *out_r2 = NPC_EVENT_ATTR;  /* left over from phase-3 OR */
    *out_r3 = count;
    *out_cmp_b = (count == 0) ? 1 : 0;

    if (count == 0)
        return;

    u32 flag = start_flag;
    for (u32 i = 0; i < count; i++) {
        u32 record_base = A_unk_2026700 + NPC_RECORD_SIZE * i;
        u32 second_base = record_base + NPC_HALF_OFFSET;

        /* Ask which event/hidden flags apply to entry i */
