            ST16(record_base + off, flag | hidden_flag);
            ST16(second_base  + off, (flag | hidden_flag) + 1);
            flag += 2;
            off  += 2;
        }

        /* Phase 2: middle entries use the hidden-attribute constant */
        off += 2;
        while (off < 0x28) {
            ST16(record_base + off, flag | NPC_HIDDEN_ATTR);
            ST16(second_base  + off, (flag | NPC_HIDDEN_ATTR) + 1);
            flag += 2;
            off  += 2;
        }

        /* Phase 3: trailing entries return to the event-attribute constant */
        off += 2;
        while (off < 0x2E) {
            ST16(record_base + off, flag | NPC_EVENT_ATTR);
            ST16(second_base  + off, (flag | NPC_EVENT_ATTR) + 1);
            flag += 2;
            off  += 2;
        }
