    u32 r2;   /* 0x7000 after normal completion */
    u32 r3;   /* loop index == count after normal completion */
} NpcFillResult;

/* Fill the NPC battle-table at unk_2026700 for `count` entries.
 * Each entry occupies 0x5C bytes: 0x2E primary + 0x2E secondary.
 * Primary/secondary u16 values are sequential NPC IDs with per-section flags ORed in. */
static NpcFillResult fill_npc_battle_table(u32 base, u32 count) {
    NpcFillResult result;

    zero_fill(NPC_TABLE_ADDR, NPC_TABLE_SIZE);

    result.r1 = count;
    result.r2 = NPC_FLAG_EVENT;
    result.r3 = count;

    if (count == 0)
        return result;

    for (u32 idx = 0; idx < count; idx++) {
        u32 entry_offset = NPC_ENTRY_SIZE * idx;
        u32 primary  = NPC_TABLE_ADDR + entry_offset;
        u32 secondary = primary + NPC_SECONDARY_OFF;

        u32 per_entry_flag;
        u32 entry_id = npc_get_entry_flag(base, entry_offset,
                                          NPC_FLAG_EVENT, idx, 0,
                                          &per_entry_flag);

        /* Section 1: offsets 0x00..0x14, flag = per-entry event flag from callee */
        u32 off = 0;
        while (off < NPC_SECTION1_LIMIT) {
            ST16(primary + off, entry_id | per_entry_flag);
            ST16(secondary + off, (entry_id | per_entry_flag) + 1);
            entry_id += 2;
            off += 2;
        }
        /* skip past the section boundary */
        entry_id += 2;
        off += 2;

        /* Section 2: offsets 0x16..0x26, flag = hidden (0x9000) */
        while (off < NPC_SECTION2_LIMIT) {
            ST16(primary + off, entry_id | NPC_FLAG_HIDDEN);
            ST16(secondary + off, (entry_id | NPC_FLAG_HIDDEN) + 1);
            entry_id += 2;
            off += 2;
        }
        entry_id += 2;
        off += 2;

        /* Section 3: offsets 0x28..0x2C, flag = event (0x7000) */
        while (off < NPC_SECTION3_LIMIT) {
            ST16(primary + off, entry_id | NPC_FLAG_EVENT);
            ST16(secondary + off, (entry_id | NPC_FLAG_EVENT) + 1);
            entry_id += 2;
            off += 2;
        }
    }

    return result;
}

