 * Returns the final running id. On the early-exit path (count==0) the table is zeroed
 * and the callee leaves r2/r3/c/v; the adapter must not overwrite those. */
static u32 fill_npc_entries(u32 first_id, u32 count) {
    zero_fill_npc_table();
    if (count == 0)
        return first_id;

    const u32 FLAG_EVENT  = 0x7000;
    const u32 FLAG_HIDDEN = 0x9000;
    const u32 ENTRY_SIZE  = 0x5C;
    const u32 HALF_SIZE   = 0x2E;

    u32 id = first_id;
    for (u32 i = 0; i < count; i++) {
        u32 entry = A_unk_2026700 + ENTRY_SIZE * i;
        u32 entry_half = entry + HALF_SIZE;

        struct { u32 id; u32 extra; } chk = npc_check_event(id, ENTRY_SIZE * i, FLAG_EVENT, i);
        id = chk.id;
        u32 extra_flag = chk.extra;
        u32 off = 0;

        /* Section 1: event-flagged pairs, offsets 0x00-0x15 */
        for (; off < 0x16; off += 2) {
            u32 val = id | extra_flag;
            ST16(entry + off, val);
            ST16(entry_half + off, val + 1);
            id += 2;
        }
        id += 2;
        off += 2;

        /* Section 2: hidden-flagged pairs, offsets 0x18-0x27 */
        for (; off < 0x28; off += 2) {
            u32 val = id | FLAG_HIDDEN;
            ST16(entry + off, val);
            ST16(entry_half + off, val + 1);
            id += 2;
        }
        id += 2;
        off += 2;

        /* Section 3: event-flagged pairs, offsets 0x2A-0x2D */
        for (; off < 0x2E; off += 2) {
            u32 val = id | FLAG_EVENT;
            ST16(entry + off, val);
            ST16(entry_half + off, val + 1);
            id += 2;
        }
        id += 2;
        off += 2;
    }

    /* register form: on the normal path r2/r3/c/v are computed values, not callee residue;
     * on the early path the ZeroFillByByte callee already set them and we must not overwrite. */
    if (count != 0) {
        R1 = count;
        R2 = FLAG_EVENT;
        R3 = count;
        SET_FLAGS_CMP(count, count);
    }

    return id;
}

