/* A pressed with one of the main entries (0-7) highlighted.  Most entries
 * switch to their submenu (mode 0x10, argument 4); the two entries locked
 * while the "PET communication save disabled" event flag is set (6 and 7)
 * only play the rejection beep, after which the cursor stays movable. */
static void select_menu_entry(u32 menu, u32 toolkit)
{
    u32 cursor = LD8(menu + 4);

    if (pet_comm_save_disabled() && (cursor == 6 || cursor == 7)) {
        play_sound_effect(SOUND_CANT_JACK_IN);
        move_menu_cursor(menu, toolkit);
    } else {
        play_sound_effect(SOUND_MENU_SELECT);
        ST8(menu, 0x10);
        ST8(menu + 1, 4);
    }
}

/* Cursor handling when no selection was consumed: with the selection on the
 * right-hand panel (position 8), UP/DOWN/LEFT close it again; otherwise
 * RIGHT opens it.  Inside the plain 0-7 entry list the key-repeat handler
 * moves the selection with wrap-around instead. */
static void move_menu_cursor(u32 menu, u32 toolkit)
{
    u32 cursor = LD8(menu + 4);

    if (cursor >= 8) {
        if (!button_pressed(JOYPAD_DOWN | JOYPAD_UP | JOYPAD_LEFT))
            return;
        play_sound_effect(SOUND_MENU_CUR_MOVE);
        ST8(menu + 4, LD8(menu + 3));    /* back to the parked selection */
        ST8(menu + 9, 3);                /* short input debounce */
        return;
    }

    if (button_pressed(JOYPAD_RIGHT)) {
        play_sound_effect(SOUND_MENU_CUR_MOVE);
        ST8(menu + 3, cursor);           /* park the selection for the way back */
        ST8(menu + 4, 8);                /* move onto the right-hand panel */
        ST8(menu + 6, 0);
        ST8(menu + 7, 0);
        return;
    }

    {
        u32 joypad = LD32(toolkit + oToolkit_JoypadPtr);
        u32 held = LD16(joypad + oJoypad_LowSensitivityHeld);
        u32 new_cursor = menu_move_cursor_up_down(held, 8, 1, cursor);
        ST8(menu + 4, new_cursor);
    }
}

/* One frame of the PET main menu: redraw the screen, then read input. */
static void pet_menu_screen_update(u32 menu, u32 toolkit)
{
    copy_pet_background();
    copy_navi_select_background();
    init_pet_menu_screen();

    /* While the panel transition animation (anim 0x10) runs, no input. */
    if (!gfx_anim_active(0x10)) {
        u32 debounce = LD8(menu + 9);

        if (debounce != 0) {
            ST8(menu + 9, debounce - 1);
        } else if (screen_fade_active()) {
            if (button_pressed(JOYPAD_START | JOYPAD_B)) {
                start_panel_transition(menu);
            } else if (!button_pressed(JOYPAD_A)) {
                move_menu_cursor(menu, toolkit);
            } else if (LD8(menu + 4) >= 8) {
                /* A on the right-hand panel behaves like START/B. */
                start_panel_transition(menu);
            } else {
                select_menu_entry(menu, toolkit);
            }
        }
    }

    pet_menu_tick_811F1B8();
    pet_menu_tick_811F0C8();
    pet_menu_tick_811F11C();
}

