#define NPC_TABLE_SIZE   0x170
#define NPC_HALF_OFFSET  0x2E
#define NPC_SPECIAL_EVT  0x7000   /* (7 << 12) – event-NPC type tag   */
#define NPC_SPECIAL_HID  0x9000   /* hidden-NPC type tag              */

