/* Write the two 22-u16 arrays for one NPC entry, split into three ranges:
 *   0x00-0x15 : tagged with the callee-supplied special
 *   0x18-0x27 : tagged NPC_SPECIAL_HID  (0x9000)
 *   0x2A-0x2D : tagged NPC_SPECIAL_EVT  (0x7000)
 * Offsets 0x16 and 0x28 are skipped (boundary/gap fields).
 * Each position writes (event | tag) into the first half and
 * (event | tag) + 1 into the second half, stepping event by 2. */
static u32 fill_entry(u32 first, u32 second, u32 event, u32 special) {
    u32 off;

    off = 0;
    while (off < 0x16) {
        ST16(first + off,  (u16)(event | special));
        ST16(second + off, (u16)((event | special) + 1));
        event += 2;
        off   += 2;
    }
    event += 2;          /* skip boundary */
    off   += 2;

    while (off < 0x28) {
        ST16(first + off,  (u16)(event | NPC_SPECIAL_HID));
        ST16(second + off, (u16)((event | NPC_SPECIAL_HID) + 1));
        event += 2;
        off   += 2;
    }
    event += 2;          /* skip boundary */
    off   += 2;

    while (off < NPC_HALF_OFFSET) {
        ST16(first + off,  (u16)(event | NPC_SPECIAL_EVT));
        ST16(second + off, (u16)((event | NPC_SPECIAL_EVT) + 1));
        event += 2;
        off   += 2;
    }
    /* no extra +2 after the last block */

    return event;
}

