 * Returns the register values the original leaves in r1, r2, r3 at exit. */
static NpcInitOut init_npc_entries(u32 start_event, u32 entry_count) {
    zero_fill_npc_table();

    if (entry_count == 0) {
        NpcInitOut out = { 0, 7, NPC_SPECIAL_EVT };
        return out;
    }

    u32 event = start_event;
    for (u32 i = 0; i < entry_count; i++) {
        u32 entry  = A_unk_2026700 + i * NPC_ENTRY_SIZE;
        u32 second = entry + NPC_HALF_OFFSET;
        u32 special;

        event = check_npc_entry_flag(event, i * NPC_ENTRY_SIZE,
                                     NPC_SPECIAL_EVT, i, &special);
        event = fill_entry(entry, second, event, special);
    }

    NpcInitOut out = { entry_count, NPC_SPECIAL_EVT, entry_count };
    return out;
}

