#define NPC_ENTRY_TABLE_SIZE 0x170
#define NPC_ROW_STRIDE       0x5C
#define NPC_HIDDEN_HALF      0x2E
#define NPC_HIDDEN_FLAG      0x7000   /* 7 << 12: tile carries the row's hidden mask */
#define NPC_UNUSED_FLAG      0x9000   /* tile slot forced to "unused" */

struct npc_table_exit {
    u32 count;      /* r1: number of NPC rows processed */
    u32 last_mask;  /* r2: hidden-flag value as the caller reads it (or fill leftover, no rows) */
    u32 final_row;  /* r3: row counter at exit (hidden-flag value when there are no rows) */
    u32 cmp_a;      /* operands for the adapter's CMP that reproduce the exit c/v flags */
    u32 cmp_b;
};

