 * with the running tile ID advancing by 2 per entry. Returns the new tile ID.
 * (nz is a clobber for callers of sub_81280DC, so cmp_a/cmp_b only need to
 * reproduce the c and v bits of the exit flags.) */
static u32 fill_tile_range(u32 tile_base, u32 mask, u32 off_start, u32 off_end,
                           u32 row_base, u32 hidden_base, u32 *cmp_a, u32 *cmp_b_unused) {
    for (u32 off = off_start; off < off_end; off += 2) {
        u32 value = tile_base | mask;
        ST16(row_base + off, value);
        ST16(hidden_base + off, value + 1);
        tile_base += 2;
    }
    return tile_base;
}

/* Pick CMP operands whose C and V match the requested flag pair:
 *   c=1: a >= b unsigned;  v=1: the signed subtraction overflows. */
static void flag_cmp_pair(bool carry, bool overflow, u32 *a, u32 *b) {
    if (carry) {
        *a = overflow ? 0x80000000u : 1u;
        *b = overflow ? 0x7FFFFFFFu : 0u;
    } else {
        *a = overflow ? 0x7FFFFFFFu : 0u;
        *b = overflow ? 0x80000000u : 1u;
    }
}

static struct npc_table_exit build_npc_entry_table(u32 npc_data, u32 npc_count) {
    struct npc_table_exit out;
    bool fill_carry, fill_overflow;
    u32 fill_r2;
    u32 tile_base = npc_data;
    u32 hidden_flag = NPC_HIDDEN_FLAG;

    clear_npc_entry_table(&fill_r2, &fill_carry, &fill_overflow);

    if (npc_count == 0) {
        /* Nothing to build: r2/r3 keep the values set up before the zero fill,
         * and the exit c/v are whatever ZeroFillByByte left on the flags. */
        out.count = npc_count;
        out.last_mask = fill_r2;
        out.final_row = hidden_flag;
        flag_cmp_pair(fill_carry, fill_overflow, &out.cmp_a, &out.cmp_b);
        return out;
    }

    for (u32 row = 0; (s32)row < (s32)npc_count; row++) {
        u32 row_base = NPC_ENTRY_TABLE + row * NPC_ROW_STRIDE;
        u32 hidden_base = row_base + NPC_HIDDEN_HALF;
        u32 entry_mask;

        /* Get this row's starting tile ID and hidden/eventflag mask. */
        tile_base = npc_row_tile_base(tile_base, row * NPC_ROW_STRIDE, hidden_flag, &entry_mask);

        /* First bank: masked tiles, then one skipped slot. */
        tile_base = fill_tile_range(tile_base, entry_mask, 0x00, 0x16, row_base, hidden_base, &out.cmp_a, &out.cmp_b);
        tile_base += 2;

        /* Second bank: tiles forced to the "unused" marker. */
        tile_base = fill_tile_range(tile_base, NPC_UNUSED_FLAG, 0x18, 0x28, row_base, hidden_base, &out.cmp_a, &out.cmp_b);
        tile_base += 2;

        /* Third bank: masked tiles again; no skipped slot after this one. */
        tile_base = fill_tile_range(tile_base, hidden_flag, 0x2A, 0x2E, row_base, hidden_base, &out.cmp_a, &out.cmp_b);
    }

    /* Exit state: the last loop reloaded the hidden flag into r2 and the row
     * counter ended exactly at the row count, so the final CMP was equal. */
    out.count = npc_count;
    out.last_mask = hidden_flag;
    out.final_row = npc_count;
    out.cmp_a = npc_count;
    out.cmp_b = npc_count;
    return out;
}

