/* Body of the PET navi-select menu update; runs the three draw passes afterwards
 * (done by the adapter, since they execute on every path). */
static void navi_select_menu_update(u32 pet, u32 toolkit) {
    pet_menu_prepare();

    /* While the PET's own GFX animation (slot 0x10) plays, only the
     * bookkeeping below is skipped entirely. */
    if (gfx_anim_active(0x10))
        return;

    /* Short input lockout right after a cursor move. */
    u32 cooldown = LD8(pet + 9);
    if (cooldown != 0) {
        ST8(pet + 9, cooldown - 1);
        return;
    }

    /* Input is read while the screen fade is running (the original proceeds
     * from IsScreenFadeActive only when Z is clear). */
    if (!screen_fade_active())
        return;

    /* START or B starts the decision animation straight away. */
    if (button_pressed(0xA /* JOYPAD_START | JOYPAD_B */)) {
        play_decision_animation(pet);
        return;
    }

    /* A confirms the highlighted entry. */
    if (button_pressed(0x1 /* JOYPAD_A */)) {
        u32 selection = LD8(pet + 4);
        if (selection >= 8) {
            play_decision_animation(pet);
            return;
        }
        if (pet_comm_save_disabled() && (selection == 6 || selection == 7)) {
            /* Entries 6/7 cannot be picked while PET comm save is disabled:
             * buzz, but still fall through to the cursor handling below. */
            play_sound_effect(SOUND_CANT_JACK_IN);
        } else {
            /* Open the selected entry. */
            play_sound_effect(SOUND_MENU_SELECT);
            ST8(pet, 0x10);
            ST8(pet + 1, 4);
            return;
        }
    }

    u32 cursor = LD8(pet + 4);
    if (cursor >= 8) {
        /* On the bottom rows, UP/DOWN/LEFT go back to the remembered top entry. */
        if (button_pressed(0xE0 /* JOYPAD_DOWN | JOYPAD_UP | JOYPAD_LEFT */)) {
            play_sound_effect(SOUND_MENU_CUR_MOVE);
            ST8(pet + 4, LD8(pet + 3));
            ST8(pet + 9, 3);
        }
        return;
    }

    if (button_pressed(JOYPAD_RIGHT)) {
        /* RIGHT moves into the bottom rows and remembers the current entry. */
        play_sound_effect(SOUND_MENU_CUR_MOVE);
        ST8(pet + 3, LD8(pet + 4));
        ST8(pet + 4, 8);
        ST8(pet + 6, 0);
        ST8(pet + 7, 0);
        return;
    }

    /* Otherwise the shared menu cursor stepper walks the list using the
     * low-sensitivity (last frame's) held buttons for key repeat. */
    u32 joypad = LD32(toolkit + 4 /* oToolkit_JoypadPtr */);
    u32 held_buttons = LD16(joypad + 4 /* oJoypad_LowSensitivityHeld */);
    ST8(pet + 4, menu_move_cursor_up_down(held_buttons, 8, 1, LD8(pet + 4)));
}

