    /* Sprite inactive → nothing to do. */
    if (LD8(R5 + OBJ_BYTE_ACTIVE) == 0)
        return 0;

    /* Look up base attributes from the type-indexed tile table. */
    table_entry = LD32(A_byte_813470C + (LD32(R5 + OBJ_WORD_TYPE) << 2));

    /* Subtract the vertical offset (Y * 8), then place in upper 16 bits. */
