/* All outputs of sub_8134610: r0-r3 and condition flags for the adapter to replay. */
typedef struct {
    u32 r0, r1, r2, r3;
    u32 nz_val;
    bool set_c, c_val;
    bool set_v, v_val;
} SubObjResult;

/* Compute the tile-layout draw address from the sub-object descriptor at obj.
 * Returns a non-zero address only when the object is enabled, the tile
 * index is in range, and the layout-table entry is non-null. */
static u32 compute_layout_address(u32 obj) {
    if (LD8(obj + oSubObj_Enabled) == 0)
        return 0;

    u32 type  = LD32(obj + oSubObj_Type);
    u32 entry = LD32(A_subobj_tile_table + (type << ADDR_SHIFT_HIGH));
    if (entry == 0)
        return 0;

    s32 offset = (s16)LD16(obj + oSubObj_Offset18);
    u32 upper  = (entry - (offset << ADDR_SHIFT_HIGH)) << ADDR_SHIFT_UPPER;

    u32 sum = LD16(obj + oSubObj_Addr3E) + LD16(obj + oSubObj_Addr3C);
    u32 threshold = (type == SUBOBJ_TYPE_2)
                  ? LD16(obj + oSubObj_Threshold2E)
                  : LD16(obj + oSubObj_Threshold24);

    s32 tile_idx = (s32)(sum - threshold);
    if (tile_idx < 0 || tile_idx >= LAYOUT_COUNT)
        return 0;

    u32 lower = (offset << ADDR_SHIFT_HIGH) + (u32)tile_idx * TILE_COUNT;
    return upper | lower;
}

/* Main logic: draw the sub-object tile layout and update its nibble counter.
 * Returns early (pass-through inputs) when the object is disabled, the tile
 * index is out of range, or the layout address is null. */
static SubObjResult process_sub_obj(u32 obj,
                                    u32 in_r1, u32 in_r2, u32 in_r3,
                                    bool in_c, bool in_v) {
    SubObjResult res;
    res.set_c = false;
    res.set_v = false;

    /* Guard: disabled, out-of-range tile index, or null layout entry. */
    u32 addr = compute_layout_address(obj);
    if (addr == 0) {
        res.r0 = 0;
        res.r1 = in_r1; res.r2 = in_r2; res.r3 = in_r3;
        res.nz_val = 0;
        return res;
    }

    /* Save the nibble byte; build draw flags with the high bit set. */
    u32 saved  = LD8(obj + oSubObj_NibbleByte);
    u32 flags  = (saved & DRAW_FLAGS) | FLAG_HIGH_BIT;

    call_layout_draw(addr, DRAW_MODE, flags, A_draw_param_byte, FLAG_TYPE_A);

    /* If the top nibble was 1, fetch a fresh tile index and store it. */
    if ((saved >> TILE_SHIFT) == 1) {
        /* register form: R1 must hold the dword_81331FC pointer for sub_8120CC8's calling convention */
        u32 fresh = call_get_tile_index(A_dword_81331FC);
        /* register form: sub_8120CC8 leaves its return index in R1 */
        res.r1 = R1;
        ST8(obj + oSubObj_NibbleByte, fresh);
        res.set_v = true;
        res.v_val  = OVERFLOW_FLAG();
    } else {
        res.r1 = (saved >> TILE_SHIFT) - 1;
    }

    /* Pack: low nibble stays, high nibble becomes the shifted R1. */
    u32 cur   = LD8(obj + oSubObj_NibbleByte);
    u32 lower = cur & DRAW_FLAGS;
    u32 upper = res.r1 << TILE_SHIFT;
    res.r0    = lower | upper;
    ST8(obj + oSubObj_NibbleByte, res.r0);

    /* Carry comes from the left-shift of the tile counter. */
    res.set_c = true;
    res.c_val = (res.r1 >> (32 - TILE_SHIFT)) & 1;

    /* r2 = 0xF (mask constant); r3 left by the layout call. */
    res.r2 = DRAW_FLAGS;
    /* register form: R3 left by sub_811FAF4 (or sub_8120CC8), passed through to caller */
    res.r3 = R3;

    res.nz_val = res.r0;
    return res;
}

/* sub_8134610(r5 = sub-object pointer, r1 r2 r3 pass-through) -> r0 r1 r2 r3, nz c v */
Next sub_8134610(void) {
    SubObjResult res = process_sub_obj(R5, R1, R2, R3, CARRY_FLAG(), OVERFLOW_FLAG());
    R0 = res.r0; R1 = res.r1; R2 = res.r2; R3 = res.r3;
    SET_FLAGS_NZ(res.nz_val);
    if (res.set_c) cpu.c = res.c_val;
    if (res.set_v) cpu.v = res.v_val;
    RETURN_TO_CALLER();
}

/* NPC display table at A_unk_2026700: `count` records of 0x5C bytes, each made of two
 * 0x2E-byte arrays of 16-bit entries. The entry value counter runs on across the whole
 * table, stepping past the two unused slot pairs in the middle of each record. */

typedef struct {
    u32 r1;   /* final loop counter (== count) */
    u32 r2;   /* attribute mask left in r2 */
    u32 r3;   /* final loop counter (== count) */
} NpcTableResult;

/* register form: calls ZeroFillByByte outside this file, which has no typed C interface yet */
static void zero_fill(u32 address, u32 byteCount) {
    R0 = address;
    R1 = byteCount;
    GUEST_CALL(ZeroFillByByte);
}

/* register form: calls npc_checkEntryEventFlagOrHidden_812818C outside this file, which has no typed C interface yet.
 * It answers in r0 (the entry value to use) and r2 (the mask for this record's first array). */
static u32 check_npc_entry(u32 value, u32 recordOffset, u32 mask, u32 *outMask) {
    R0 = value;
    R1 = recordOffset;
    R2 = mask;
    GUEST_CALL(npc_checkEntryEventFlagOrHidden_812818C);
    *outMask = R2;
    return R0;
}

/* Stores a run of consecutive 16-bit values into both halves of one record: the first
 * array gets `value|mask`, the second its successor. Returns the advanced counter. */
static u32 fill_record(u32 firstHalf, u32 secondHalf, u32 start, u32 end, u32 mask, u32 value) {
    for (u32 offset = start; offset < end; offset += 2) {
        u32 entry = value | mask;
        ST16(firstHalf + offset, entry);
        ST16(secondHalf + offset, entry + 1);
        value += 2;
    }
    return value;
}

static NpcTableResult build_npc_table(u32 firstValue, u32 count) {
    NpcTableResult result;

    zero_fill(A_unk_2026700, 0x170);

    if (count == 0) {
        /* Nothing to build; r2/r3 keep the values prepared before the clear. */
        result.r1 = 0;
        result.r2 = 7;
        result.r3 = 0x7000;
        return result;
    }

    u32 value = firstValue;
    for (u32 i = 0; i < count; i++) {
        u32 firstHalf = A_unk_2026700 + 0x5C * i;
        u32 secondHalf = firstHalf + 0x2E;
        u32 mask;

        value = check_npc_entry(value, 0x5C * i, 0x7000, &mask);

        value = fill_record(firstHalf, secondHalf, 0x00, 0x16, mask, value);
        value += 2;                                   /* two unused slots */
        value = fill_record(firstHalf, secondHalf, 0x18, 0x28, 0x9000, value);
        value += 2;                                   /* two unused slots */
        value = fill_record(firstHalf, secondHalf, 0x2A, 0x2E, 0x7000, value);
    }

    result.r1 = count;
    result.r2 = 0x7000;
    result.r3 = count;
    return result;
}

/* sub_81280DC(r0 = first entry value, r1 = record count) -> r1, r2, r3, c, v */
Next sub_81280DC(void) {
    NpcTableResult result = build_npc_table(R0, R1);
    R1 = result.r1;
    R2 = result.r2;
    R3 = result.r3;
    SET_FLAGS_CMP(result.r3, result.r1);   /* cmp r3, r1: r3 ends equal to the count */
    RETURN_TO_CALLER();
}

/* Spawn entry used by attacks that create a companion battle object.
 *
 * The caller hands over a spawn description in r0-r3/r5-r7 (this thunk exists to
 * shift those registers back into place around the spawner call, pushing the
 * ones that must survive it):
 *   r0 -> child->ExtraVars
 *   r1 -> nothing on success; only escapes back out in r2 when the spawn fails
 *   r2 -> child->Element (low byte)
 *   r5 -> parent battle object; also passed to the spawner in r5
 *   r6 -> child->DamageAndStaminaDamageCounterDisabler
 *   r7 -> pointer to the slot that receives the child
 *
 * The child is spawned as object type 0x36; the spawner answers with the new
 * object (0 if none) in r5. On failure the original just pops its saved
 * registers and returns; on success it fills the child in, stores the child
 * into the caller's slot, and marks the child's OAM header flag 0x10.
 *
 * Outputs consumed by callers: r2, r3 and r5 (v and the other registers simply
 * pass through the spawner call). */
typedef struct {
    u32 r2; /* success: child's header flags byte | 0x10 ; failure: incoming r1 */
    u32 r3; /* success: parent's AllianceAndDirectionFlip; failure: incoming r2 */
    u32 r5; /* the parent object, unchanged */
} spawn_link_result;

/* register form: calls object_spawnType3 outside this file, which has no typed C interface yet */
static u32 spawn_object_0x36(void) {
    R0 = 0x36;                  /* object type, as the original passes it */
    GUEST_CALL(object_spawnType3);
    return R5;                  /* the spawner leaves the created object (or 0) in r5 */
}

static spawn_link_result spawn_and_link_object_type36(
    u32 extraVars,
    u32 fail_r2,      /* incoming r1, unused on the success path */
    u32 element,
    u32 parent,
    u32 counterFlags,
    u32 slotPtr)
{
    u32 child = spawn_object_0x36();
    spawn_link_result res;

    if (child == 0) {
        /* spawn failed: only the popped registers remain observable */
        res.r2 = fail_r2;
        res.r3 = element;
    } else {
        u32 alliance = LD16(parent + oBattleObject_AllianceAndDirectionFlip);
        u32 headerFlags;

        ST32(child + oBattleObject_ExtraVars, extraVars);
        ST8(child + oBattleObject_Element, element);
        ST32(child + oBattleObject_RelatedObject1Ptr, parent);
        ST32(child + oBattleObject_DamageAndStaminaDamageCounterDisabler, counterFlags);
        ST16(child + oBattleObject_AllianceAndDirectionFlip, alliance);
        ST32(child + oBattleObject_RelatedObject2Ptr, slotPtr);
        ST32(slotPtr, child);

        headerFlags = LD8(child + oObjectHeader_Flags) | 0x10;
        ST8(child + oObjectHeader_Flags, headerFlags);

        res.r2 = headerFlags;
        res.r3 = alliance;
    }

    res.r5 = parent; /* the pop restores the parent pointer in r5 on every path */
    return res;
}

Next sub_80CAC58(void) {
    spawn_link_result result = spawn_and_link_object_type36(R0, R1, R2, R5, R6, R7);
    R2 = result.r2;
    R3 = result.r3;
    R5 = result.r5;
    RETURN_TO_CALLER();
}

