/* Compute the tile / OAM coordinate from the object's world position.
 * Returns 1 when the object is valid and within range, 0 otherwise. */
static int compute_tile_coord(u32 obj, u32 *out_coord, u32 *out_yshift,
                              u32 *out_distance, u32 *out_anim_id) {
    u32 anim_id = LD32(obj + oBattleObject_AnimationId);
    *out_anim_id = anim_id;

    u32 table = LD32(A_TileLookupTable);
    u32 base  = LD32(table + anim_id * 4);

    s32 yshift = (s16)LD16(obj + oBattleObject_YOffset) << 3;
    u32 diff   = (base - (u32)yshift) << 16;

    u32 xsum = LD16(obj + oBattleObject_X2) + LD16(obj + oBattleObject_X1);
    u32 height = (anim_id == 2) ? LD16(obj + oBattleObject_HeightA)
                                 : LD16(obj + oBattleObject_HeightB);
    u32 distance = xsum - height;

    if ((s32)distance < 0 || (s32)distance > 6) {
        *out_distance = distance;
        *out_coord    = diff;
        *out_yshift   = (u32)yshift;
        return 0;
    }

    *out_coord  = diff | ((u32)yshift + distance * 16);
    *out_yshift = (u32)yshift;
    *out_distance = distance;
    return 1;
}

/* Update the two-nibble state byte at [obj+0x16] after resolving tile and category. */
static void update_category_nibble(u32 obj, u32 saved_raw, u32 *out_r1) {
    u32 category = saved_raw >> 4;

    if (category - 1 == 0) {
        /* Category 1: re-query the animation table for the new state and category. */
        u32 new_state;
        u32 new_cat = query_animation(A_AnimationTable, &new_state);
        ST8(obj + oBattleObject_CategoryNibble, new_state);
        *out_r1 = new_cat;
    } else {
        *out_r1 = category - 1;
    }

    u32 state  = LD8(obj + oBattleObject_CategoryNibble) & 0xF;
    u32 shifted = *out_r1 << 4;
    u32 combined = state | shifted;
    ST8(obj + oBattleObject_CategoryNibble, combined);
