} TileResult;

/* Compute the tile BG attribute and update the nibble-packed tile index. */
static TileResult update_tile_slot(u32 obj) {
    TileResult res = {0, 0, 0, 0, 0, false};

    /* Guard byte at obj+0x44 must be non-zero */
    u32 guard = LD8(obj + 0x44);
