    u32 scroll = scroll_raw << 3;

    /* Upper halfword: table value minus scroll, shifted into bits 16-31 */
    u32 upper = (table_val - scroll) << 16;

    /* Lower halfword: Y + H - vertical offset, must be in [0..6] */
    u32 y = LD16(obj + 0x3E);
    u32 h = LD16(obj + 0x3C);
    u32 tile_sum = y + h;

    u32 vert_offset;
    if (alliance == 2)
