    s32 tile_index = (s32)(tile_sum - vert_offset);
    if (tile_index < 0 || tile_index > 6) {
        res.r0 = upper;
        res.r1 = scroll;
        res.r2 = tile_index;
        res.r3 = alliance;
        res.exit_flag = true;
        res.nz_source = (u32)tile_index;   /* NZ from SUBS r2, r4 (or CMP r2, 6) */
        return res;
