    /* Build the full tile attribute: upper | lower half */
    u32 lower = scroll + (u32)(tile_index * 0x10);
    u32 tile_attr = upper | lower;

    /* Save old nibble-packed byte, then render the tile */
    u32 old_byte = LD8(obj + 0x16);
    u32 pal_flag = (old_byte & 0xF) | 0x80000000;

    call_render_tile(tile_attr, 0x20003, pal_flag, A_byte_81331F4, 0x40000000);

    /* Check whether the tile-index nibble needs refreshing */
    u32 saved_nibble = (old_byte >> 4);
