/* Input handling of the select/jack-in state machine. */
static void update_pet_screen(u32 screen, u32 toolkit, u32 entryR4) {
    if (is_gfx_anim_active(0x10))                    /* 0x10: PET window animation */
        return;

    /* A few frames must pass after a cursor move before input is read again */
    u32 cooldown = LD8(screen + 9);
    if (cooldown != 0) {
        ST8(screen + 9, cooldown - 1);
        return;
    }

    /* Input is only handled while a screen fade is running */
    if (!is_screen_fade_active())
        return;

    /* START or B always (re)starts the jack-in sequence, whatever is selected */
    if (is_button_pressed(JOYPAD_START | JOYPAD_B)) {
        start_jack_in(screen);
        return;
    }

    u32 slot = LD8(screen + 4);

    /* r4 value the original holds across the sound calls on the path taken */
    u32 soundR4 = entryR4;

    if (is_button_pressed(JOYPAD_A)) {
        if ((s32)slot >= 8) {
            /* A inside the menu column: jack in from the selection */
            start_jack_in(screen);
            return;
        }

        /* A on one of the navi slots: confirm it */
        soundR4 = slot;
        if (pet_save_disabled() && (slot == 6 || slot == 7)) {
            /* saving comm data is disabled for slots 6/7: refuse the choice,
             * then fall through to plain cursor-move handling */
            play_sound_effect(SOUND_CANT_JACK_IN, soundR4);
        } else {
            play_sound_effect(SOUND_MENU_SELECT, soundR4);
            ST8(screen, 0x10);                       /* mode: transition */
            ST8(screen + 1, 4);
            return;
        }
    }

    if ((s32)slot < 8) {
        /* a navi slot is selected */
        if (is_button_pressed(JOYPAD_RIGHT)) {
            /* RIGHT moves from the navi slots onto the menu column */
            play_sound_effect(SOUND_MENU_CUR_MOVE, soundR4);
            ST8(screen + 3, slot);
            ST8(screen + 4, 8);
            ST8(screen + 6, 0);
            ST8(screen + 7, 0);
            return;
        }

        /* DOWN/UP scroll through the slots using the low-sensitivity pad */
        u32 joypad = LD32(toolkit + oToolkit_JoypadPtr);
        u32 heldButtons = LD16(joypad + oJoypad_LowSensitivityHeld);
        u32 newSlot = menu_move_cursor_up_down(heldButtons, 8, 1, slot);
        ST8(screen + 4, newSlot);
        return;
    }

    /* the menu column is selected: DOWN, UP or LEFT move back to the slots */
    if (is_button_pressed(JOYPAD_DOWN | JOYPAD_UP | JOYPAD_LEFT)) {
        play_sound_effect(SOUND_MENU_CUR_MOVE, soundR4);
        ST8(screen + 4, LD8(screen + 3));
        ST8(screen + 9, 3);                          /* rearm the input cooldown */
    }
}

