    ST16(new_obj + oBattleObject_AllianceAndDirectionFlip, alliance);

    ST32(new_obj + oBattleObject_RelatedObject2Ptr, related_slot_ptr);
    ST32(related_slot_ptr, new_obj);

    u32 flags = LD8(new_obj + oObjectHeader_Flags) | 0x10;
    ST8(new_obj + oObjectHeader_Flags, flags);

    SpawnFieldsResult out;
    out.flags_with_bit = flags;
    out.alliance_flip = alliance;
    return out;
}

/* sub_80CAC58(r0=extraVars, r1=unused->r2out, r2=element, r3=unused,
 *             r4=preserved, r5=sourceObj, r6=damageCtrl, r7=relatedSlotPtr) */
