    SpawnFieldsResult res = spawn_and_configure(R0, R2, R5, R6, R7);
    /* On the null-spawn path r3 passes through as input r2; the struct encodes that. */
    R3 = res.alliance_flip;
    /* On the body path r2 = flags|0x10; on early path the caller's r1 was in r2 via pop. */
    R2 = res.flags_with_bit ? res.flags_with_bit : R1;
    SET_FLAGS_ADD(R2, 0);
    RETURN_TO_CALLER();
