/* sub_81280DC: rebuilds the 16-bit tile-map halfwords for the NPC sprite
 * table at unk_2026700.
 *
 * r0 = first tile number, r1 = number of NPC slots to build.
 * The table (0x170 bytes) is byte-cleared first, then one 0x5C-byte block is
 * filled per slot. A block is two consecutive rows of 23 halfwords (the
 * second row starts at +0x2E): the NPC's tile numbers with tile-flag bits in
 * the upper area. Halfwords 0x0B and 0x14 of every row are skipped; the row
 * is filled as three runs whose flag bits are the callee's pick (leading
 * strip), 0x9000 (middle strip) and the default 0x7000 (trailing strip).
 * For each slot, npc_checkEntryEventFlagOrHidden_812818C decides the first
 * tile number (r0) and the leading strip's flag bits (r2) from the slot's
 * event/hidden state. */

#define NPC_TABLE_BYTES   0x170  /* whole table, cleared with ZeroFillByByte */
#define NPC_BLOCK_STRIDE  0x5C   /* bytes of table per NPC slot */
#define NPC_ROW_STRIDE    0x2E   /* offset of the second row inside a block */
#define NPC_STRIP_A_END   0x16   /* halfword offset where the first run stops */
#define NPC_STRIP_B_END   0x28   /* ... the second run ... */
#define NPC_ROW_END       0x2E   /* ... and the third (row end) */
#define NPC_STRIP_B_BITS  0x9000 /* tile-flag bits used by the middle strip */
#define NPC_DEFAULT_BITS  0x7000 /* 7 << 12, the default tile-flag bits */

/* What the original leaves in r1..r5 (plus the C/V flags it ends with). */
struct NpcTilemapsExit {
    u32 r1;    /* slot count, mirrored back */
    u32 r2;
    u32 r3;
    u32 r4;    /* the original saves/restores these */
    u32 r5;
    u32 cmpA;  /* SET_FLAGS_CMP(cmpA, cmpB) reproduces the final C/V state */
    u32 cmpB;
};

/* Leftover state of the byte-fill callee: when there are no slots, the fill
 * is the last thing that runs, so its register/flag state is what callers
 * see for r2/r3 and C/V. */
struct ZeroFillExit {
    bool carry;
    bool overflow;
    u32 r2;
    u32 r3;
};

/* register form: calls ZeroFillByByte outside this file, which has no typed C interface yet */
static struct ZeroFillExit zero_fill_table(u32 base, u32 bytes) {
    struct ZeroFillExit out;
    R0 = base;
    R1 = bytes;
    GUEST_CALL(ZeroFillByByte);
    out.carry = CARRY_FLAG();
    out.overflow = OVERFLOW_FLAG();
    out.r2 = R2;
    out.r3 = R3;
    return out;
}

/* Result of the per-slot check: the callee answers in r0/r2, and r3/r4 are
 * read back so the caller's running slot number and start offset always
 * match what the machine keeps in those registers. */
struct NpcRowStart {
    u32 firstTile;  /* r0 after the call: tile number where the slot starts */
    u32 flagBits;   /* r2 after the call: flag bits for the leading strip */
    u32 slot;       /* r3 after the call */
    u32 offset;     /* r4 after the call: halfword offset to start writing at */
};

/* register form: calls npc_checkEntryEventFlagOrHidden_812818C outside this file, which has no typed C interface yet */
static struct NpcRowStart npc_row_start(u32 tile, u32 slotOffset, u32 defaultBits, u32 slot) {
    struct NpcRowStart out;
    R0 = tile;
    R1 = slotOffset;
    R2 = defaultBits;
    R3 = slot;
    GUEST_CALL(npc_checkEntryEventFlagOrHidden_812818C);
    out.firstTile = R0;
    out.flagBits = R2;
    out.slot = R3;
    out.offset = R4;
    return out;
}

/* Fills one run of halfwords into both rows of a slot's block. Row A gets
 * tile|bits, row B the paired next tile (previous value + 1, exactly as the
 * machine ORs the counter and then increments it). The tile counter and the
 * halfword offset advance past the run. */
static void write_map_run(u32 rowA, u32 rowB, u32 *tileIO, u32 *offsetIO, u32 bits, u32 runEnd) {
    u32 tile = *tileIO;
    u32 offset = *offsetIO;
    do {
        u32 entry = tile | bits;
        ST16(rowA + offset, entry);      /* tile     into the first row  */
        ST16(rowB + offset, entry + 1);  /* tile + 1 into the second row */
        tile += 2;
        offset += 2;
    } while ((s32)offset < (s32)runEnd);
    *tileIO = tile;
    *offsetIO = offset;
}

/* Pick a compare pair whose CMP produces the given carry/overflow state, so
 * the thin adapter can set the exit flags without branching (n/z of this
 * function are not observed by callers). */
static void carry_overflow_as_cmp(bool carry, bool overflow, u32 *aOut, u32 *bOut) {
    if (overflow) {
        if (carry) {
            /* min - 1 = INT_MAX: overflow, no borrow */
            *aOut = 0x80000000;
            *bOut = 1;
        } else {
            /* INT_MAX - INT_MIN = -1: overflow, borrow */
            *aOut = 0x7FFFFFFF;
            *bOut = 0x80000000;
        }
    } else {
        if (carry) {
            *aOut = 0;
            *bOut = 0;
        } else {
            *aOut = 0;
            *bOut = 1;
        }
    }
}

/* Builds the tile-map table for firstTile/count or, if count is 0, just
 * clears it and reports the fill callee's leftover state. r4/r5 pass through
 * untouched, as the original leaves them via its push/pop. */
static struct NpcTilemapsExit fill_npc_tilemaps(u32 firstTile, u32 count, u32 r4Pass, u32 r5Pass) {
    struct NpcTilemapsExit res;

    struct ZeroFillExit clear = zero_fill_table(A_unk_2026700, NPC_TABLE_BYTES);

    if (count == 0) {
        res.r1 = 0;
        res.r2 = clear.r2;
        res.r3 = clear.r3;
        res.r4 = r4Pass;
        res.r5 = r5Pass;
        carry_overflow_as_cmp(clear.carry, clear.overflow, &res.cmpA, &res.cmpB);
        return res;
    }

    u32 tile = firstTile;  /* running tile number, machine r0 */
    u32 slot = 0;          /* slot number being built, machine r3 */

    do {
        u32 block = A_unk_2026700 + NPC_BLOCK_STRIDE * slot;
        u32 rowA = block;
        u32 rowB = block + NPC_ROW_STRIDE;
        u32 offset = 0;

        struct NpcRowStart start = npc_row_start(tile, NPC_BLOCK_STRIDE * slot, NPC_DEFAULT_BITS, slot);
        tile = start.firstTile;
        slot = start.slot;
        offset = start.offset;

        /* leading strip: tiles and flag bits from the per-slot check */
        write_map_run(rowA, rowB, &tile, &offset, start.flagBits, NPC_STRIP_A_END);
        /* skip one halfword, then the middle strip on the fixed 0x9000 bank */
        tile += 2;
        offset += 2;
        write_map_run(rowA, rowB, &tile, &offset, NPC_STRIP_B_BITS, NPC_STRIP_B_END);
        /* skip one halfword, then the trailing strip on the default bank */
        tile += 2;
        offset += 2;
        write_map_run(rowA, rowB, &tile, &offset, NPC_DEFAULT_BITS, NPC_ROW_END);

        slot += 1;
    } while ((s32)slot < (s32)count);

    res.r1 = count;
    res.r2 = NPC_DEFAULT_BITS;  /* the trailing strip reloaded it after the check */
    res.r3 = slot;              /* the value of the loop's final CMP r3, r1 */
    res.r4 = r4Pass;
    res.r5 = r5Pass;
    res.cmpA = slot;            /* the loop's last comparison */
    res.cmpB = count;
    return res;
}

/* sub_81280DC(r0 = first tile number, r1 = slot count) -> r1 r2 r3, flags c/v */
Next sub_81280DC(void) {
    struct NpcTilemapsExit res = fill_npc_tilemaps(R0, R1, R4, R5);
    R1 = res.r1;
    R2 = res.r2;
    R3 = res.r3;
    R4 = res.r4;
    R5 = res.r5;
    SET_FLAGS_CMP(res.cmpA, res.cmpB);
    RETURN_TO_CALLER();
}

/* ROM data tables addressed by the disassembly. */
#define OBJECT_PTR_TABLE 0x0813470Cu   /* byte_813470C: per-index sprite table */
#define SPRITE_TABLE     0x081331F4u   /* byte_81331F4 */
#define ANIM_TABLE       0x081331FCu   /* dword_81331FC */

/* register form: calls sub_811FAF4 outside this file, which has no typed C
 * interface yet; it reads r0-r4 plus a fifth argument on the stack, and the
 * caller requires r4 to be unchanged afterwards. */
static void sprite_entry(u32 a0, u32 a1, u32 a2, u32 a3, u32 a4, u32 stack_arg) {
    u32 saved_r4 = R4;
    R0 = a0;
    R1 = a1;
    R2 = a2;
    R3 = a3;
    R4 = a4;
    SP -= 4;
    ST32(SP, stack_arg);
    GUEST_CALL(sub_811FAF4);
    SP += 4;
    R4 = saved_r4;
}

/* register form: calls sub_8120CC8 outside this file, which has no typed C
 * interface yet; r4 must be unchanged afterwards. */
static u32 advance_anim(u32 a1) {
    u32 saved_r4 = R4;
    R1 = a1;
    GUEST_CALL(sub_8120CC8);
    R4 = saved_r4;
    return R0;
}

typedef struct {
    u32 r0, r1, r2, r3;
} Sub8134610Result;

/* Update the sprite of the object at `obj`: work out its screen position,
 * queue an OAM entry while it lies inside the draw band, and step the
 * animation byte at offset 0x16.  While the object is inactive r1-r3 are
 * handed back unchanged. */
static Sub8134610Result sub_8134610_update(u32 obj, u32 r1_in, u32 r2_in, u32 r3_in) {
    Sub8134610Result out;

    u8 active = LD8(obj + 0x44);
    if (active == 0) {
        out.r0 = active;
        out.r1 = r1_in;
        out.r2 = r2_in;
        out.r3 = r3_in;
        return out;
    }

    u32 index = LD32(obj + 0x40);

    /* Screen Y (low 16 bits) from the per-index table, minus the object's
     * vertical offset. */
    u32 y_pos = LD32(OBJECT_PTR_TABLE + (index << 2));
    y_pos -= (u32)((s16)LD16(obj + 0x18)) << 3;
    y_pos <<= 16;

    /* Distance from the draw band, using a height that depends on the index. */
    u32 extent = LD16(obj + 0x3E) + LD16(obj + 0x3C);
    u32 height = (index == 2) ? LD16(obj + 0x2E) : LD16(obj + 0x24);
    s32 band = (s32)(extent - height);
    if (band < 0 || band > 6) {
        out.r0 = y_pos;
        out.r1 = 0x20;
        out.r2 = (u32)band;
        out.r3 = index;
        return out;
    }

    /* Pack the OAM attribute word and queue the entry, passing the current
     * animation byte over on the stack. */
    y_pos |= 0x20 + (u32)band * 0x10;

    u8 anim = LD8(obj + 0x16);
    sprite_entry(y_pos, 0x20003, (anim & 0xF) | 0x80000000u, SPRITE_TABLE, 0x40000000u, anim);

    /* Step the animation byte's high nibble down; when it would pass 1, pull
     * the low nibble from the animation table instead. */
    u32 high = anim >> 4;
    u32 r1f;
    if (high != 1) {
        r1f = high - 1;
    } else {
        ST8(obj + 0x16, (u8)advance_anim(ANIM_TABLE));
        r1f = ANIM_TABLE;
    }

    u32 packed = (LD8(obj + 0x16) & 0xF) | (r1f << 4);
    ST8(obj + 0x16, (u8)packed);

    out.r0 = packed;
    out.r1 = r1f << 4;
    out.r2 = 0xF;
    out.r3 = SPRITE_TABLE;
    return out;
}

/* sub_8134610(r5 = object) -> r0-r3, flags */
Next sub_8134610(void) {
    Sub8134610Result res = sub_8134610_update(R5, R1, R2, R3);
    R0 = res.r0;
    R1 = res.r1;
    R2 = res.r2;
    R3 = res.r3;
    SET_FLAGS_NZ(res.r0);
    RETURN_TO_CALLER();
}

/* Result block for sub_80CAC58: the original leaves r2 and r3 in a state the
 * callers read, so the typed function hands both back to the adapter. */
typedef struct {
    u32 r2; /* new object's updated header flags on success, incoming r1 on failure */
    u32 r3; /* owner's alliance/direction halfword on success, incoming r2 on failure */
} Type36SpawnOut;

/* register form: calls object_spawnType3 outside this file, which has no typed C interface yet */
static u32 call_object_spawn_type3(void) {
    R0 = 0x36;                    /* spawn object type 0x36 */
    GUEST_CALL(object_spawnType3);
    return R5;                    /* this caller takes the spawned object from r5, as the original's "mov r0, r5" does */
}

/* Spawn the type-0x36 battle object and initialize it from the caller's state:
 * - extraVars and the low byte of element go into the new object's
 *   oBattleObject_ExtraVars / oBattleObject_Element,
 * - it copies the alliance/direction halfword from ownerObject,
 * - counterDisabler goes into its damage/stamina-counter-disabler field,
 * - it is linked both ways with relatedSlot (*relatedSlot = new object,
 *   new object->RelatedObject2Ptr = relatedSlot),
 * - header flag 0x10 is set on it.
 * ownerObject and relatedSlot are dereferenced unconditionally once the spawn
 * succeeds, exactly as the original does. Returns the new object pointer
 * (0 if the spawn failed) and the outgoing r2/r3 in *out. */
static u32 spawn_type36_object(u32 extraVars, u32 fallbackR2, u32 element,
                               u32 ownerObject, u32 counterDisabler,
                               u32 relatedSlot, Type36SpawnOut *out) {
    u32 spawned = call_object_spawn_type3();

    if (spawned == 0) {
        /* Spawn failed: the original just returns, leaving the popped
         * caller registers in place as pass-through outputs. */
        out->r2 = fallbackR2;
        out->r3 = element;
        return 0;
    }

    ST32(spawned + oBattleObject_ExtraVars, extraVars);
    ST8(spawned + oBattleObject_Element, element);
    ST32(spawned + oBattleObject_RelatedObject1Ptr, ownerObject);
    ST32(spawned + oBattleObject_DamageAndStaminaDamageCounterDisabler, counterDisabler);

    u32 alliance = LD16(ownerObject + oBattleObject_AllianceAndDirectionFlip);
    ST16(spawned + oBattleObject_AllianceAndDirectionFlip, alliance);

    ST32(spawned + oBattleObject_RelatedObject2Ptr, relatedSlot);
    ST32(relatedSlot, spawned);

    u32 flags = LD8(spawned + oObjectHeader_Flags) | 0x10;
    ST8(spawned + oObjectHeader_Flags, flags);

    out->r2 = flags;    /* the orr result the original leaves in r2 */
    out->r3 = alliance; /* the ldrh result the original leaves in r3 */
    return spawned;
}

/* sub_80CAC58(r0 = extra vars, r1 = fallback r2, r2 = element, r5 = owner object,
 *             r6 = damage/stamina-counter disabler, r7 = related-slot pointer)
 * -> r0 = spawned object (unused by callers, left as-is), r2/r3 = outgoing values,
 *    r5/lr = unchanged, V set by the original's last flag-setting instruction
 *    ("mov r0, r5" == adds r0, r5, #0, so C = V = 0). */
Next sub_80CAC58(void) {
    Type36SpawnOut out;
    u32 spawned = spawn_type36_object(R0, R1, R2, R5, R6, R7, &out);
    R2 = out.r2;
    R3 = out.r3;
    SET_FLAGS_ADD(spawned, 0);
    RETURN_TO_CALLER();
}

/*
 * sub_81280DC - rebuild the NPC descriptor table at unk_2026700 (four 0x5C-byte rows).
 *
 * r0 = first NPC tile index, r1 = number of NPC entries to build (r4-r7 hold the caller's
 * values and must survive). The table is cleared with ZeroFillByByte first; then, for every
 * entry, a helper decides which attribute bits this NPC gets, and three runs of
 * "tile index | attribute" halfwords are written into the entry row and its paired copy at
 * +0x2E. Inside one row the halfword slots at 0x16 and 0x28 stay untouched.
 *
 * Results: r1 = entry count (unchanged), r2/r3 = attribute bits / entries filled, r5
 * unchanged, and carry/overflow set exactly like the original's final cmp r3, r1 (callers
 * branch on both). nx: r0/lr are clobbered, r4/r6/r7 are preserved untouched.
 */
#define NPC_ENTRY_TABLE       A_unk_2026700
#define NPC_TABLE_BYTES       0x170   /* the whole four-entry table */
#define NPC_ENTRY_BYTES       0x5C    /* one entry: 46 halfwords plus its paired copy */
#define NPC_ENTRY_COPY_OFF    0x2E    /* where the paired copy starts inside one entry */

/* halfword offsets into one row: run 1 = 0x00..0x14, gap at 0x16, run 2 = 0x18..0x26,
 * gap at 0x28, run 3 = 0x2A..0x2C */
#define RUN1_END_OFF          0x16
#define RUN2_END_OFF          0x28
#define ROW_END_OFF           0x2E

#define ENTRY_ATTR_BITS       0x7000  /* mov r2,#7 + lsl #12: attr OR of runs 1 and 3 */
#define RUN2_ATTR_BITS        0x9000  /* fixed attr OR of run 2 */
#define NPC_CLEAR_R2_SCRATCH  7       /* scratch value the original keeps in r2 over the clear */

struct NpcAttrCheckResult {
    u32 tile;   /* r0 after the check: tile index the row is built from */
    u32 attr;   /* r2 after the check: attribute bits for run 1 */
};

/* register form: calls npc_checkEntryEventFlagOrHidden_812818C outside this file, which has no
 * typed C interface yet. At the call site the original still has r3 = entry index, r4 = 0 and
 * r5-r7 = live row pointers, so they are passed through; the callee answers in r0 and r2. */
static void npc_entry_attr_check(u32 tile, u32 rowOffset, u32 attrBits, u32 entryIndex,
                                 u32 callerR5, u32 shadowRow, u32 row,
                                 struct NpcAttrCheckResult *out) {
    R0 = tile;
    R1 = rowOffset;
    R2 = attrBits;
    R3 = entryIndex;
    R4 = 0;
    R5 = callerR5;
    R6 = shadowRow;
    R7 = row;
    GUEST_CALL(npc_checkEntryEventFlagOrHidden_812818C);
    out->tile = R0;
    out->attr = R2;
}

struct NpcTableClearLeftover {
    u32 r2;        /* scratch r2 the clear call leaves behind */
    bool carry;    /* carry/overflow it leaves behind */
    bool overflow;
};

/* register form: calls ZeroFillByByte outside this file, which has no typed C interface yet.
 * r2 = 7 / r3 = 0x7000 are the original's leftover scratch and r4-r7 still hold the caller's
 * values at this call; when the entry count turns out to be 0, that callee's leftover r2 and
 * carry/overflow flags become part of sub_81280DC's visible result, so they are read back. */
static void npc_clear_entry_table(u32 callerR4, u32 callerR5, u32 callerR6, u32 callerR7,
                                  struct NpcTableClearLeftover *left) {
    R0 = NPC_ENTRY_TABLE;
    R1 = NPC_TABLE_BYTES;
    R2 = NPC_CLEAR_R2_SCRATCH;
    R3 = ENTRY_ATTR_BITS;
    R4 = callerR4;
    R5 = callerR5;
    R6 = callerR6;
    R7 = callerR7;
    GUEST_CALL(ZeroFillByByte);
    left->r2 = R2;
    left->carry = CARRY_FLAG();
    left->overflow = OVERFLOW_FLAG();
}

/* Pick compare operands whose subtraction reproduces an exact carry/overflow pair, so the
 * thin adapter can emit a single cmp for the flag result on every path. */
static void carry_overflow_to_compare(bool carry, bool overflow, u32 *cmpA, u32 *cmpB) {
    if (carry && !overflow)       { *cmpA = 0; *cmpB = 0; }                        /* 0-0: C=1, V=0 */
    else if (!carry && !overflow) { *cmpA = 0; *cmpB = 1; }                        /* 0-1: C=0, V=0 */
    else if (carry)               { *cmpA = 0x80000000; *cmpB = 0x7FFFFFFF; }      /* C=1, V=1 */
    else                          { *cmpA = 0; *cmpB = 0x80000000; }               /* C=0, V=1 */
}

struct NpcEntryFillResult {
    u32 entryCount;    /* -> r1 */
    u32 attrBits;      /* -> r2 */
    u32 entriesFilled; /* -> r3 */
    u32 cmpA;          /* -> flags, via cmp(cmpA, cmpB) */
    u32 cmpB;
};

/* Clear the NPC descriptor table, then rebuild entryCount entries of it starting from tile
 * firstTile. The caller's r5 is forwarded to the per-entry check helper. */
static void rebuild_npc_entry_table(u32 firstTile, u32 entryCount,
                                    u32 callerR4, u32 callerR5, u32 callerR6, u32 callerR7,
                                    struct NpcEntryFillResult *out) {
    struct NpcTableClearLeftover clearLeft;
    npc_clear_entry_table(callerR4, callerR5, callerR6, callerR7, &clearLeft);

    out->entryCount = entryCount;   /* r1 comes back unchanged */

    if (entryCount == 0) {
        /* nothing to build: the early exit keeps r3 = 0x7000 and whatever r2 and
         * carry/overflow ZeroFillByByte left behind */
        out->attrBits = clearLeft.r2;
        out->entriesFilled = ENTRY_ATTR_BITS;
        carry_overflow_to_compare(clearLeft.carry, clearLeft.overflow,
                                  &out->cmpA, &out->cmpB);
        return;
    }

    u32 tile = firstTile;
    s32 filled = 0;
    if ((s32)entryCount > 0) {
        while (filled < (s32)entryCount) {   /* signed, like the original's cmp r3, r1 */
            u32 rowOffset = NPC_ENTRY_BYTES * (u32)filled;
            u32 row = NPC_ENTRY_TABLE + rowOffset;
            u32 shadowRow = row + NPC_ENTRY_COPY_OFF;

            struct NpcAttrCheckResult checked;
            npc_entry_attr_check(tile, rowOffset, ENTRY_ATTR_BITS, (u32)filled,
                                 callerR5, shadowRow, row, &checked);
            tile = checked.tile;

            /* run 1: tile halfwords ORed with the attribute bits the check returned */
            u32 off = 0;
            do {
                u32 packed = tile | checked.attr;
                ST16(row + off, packed);
                ST16(shadowRow + off, packed + 1);
                tile += 2;
                off += 2;
            } while (off < RUN1_END_OFF);
            tile += 2;  off += 2;   /* the 0x16 slot of both rows is skipped */

            /* run 2: fixed 0x9000 attribute bits */
            do {
                u32 packed = tile | RUN2_ATTR_BITS;
                ST16(row + off, packed);
                ST16(shadowRow + off, packed + 1);
                tile += 2;
                off += 2;
            } while (off < RUN2_END_OFF);
            tile += 2;  off += 2;   /* the 0x28 slot of both rows is skipped */

            /* run 3: back to the 0x7000 attribute bits */
            do {
                u32 packed = tile | ENTRY_ATTR_BITS;
                ST16(row + off, packed);
                ST16(shadowRow + off, packed + 1);
                tile += 2;
                off += 2;
            } while (off < ROW_END_OFF);

            filled++;
        }
        out->attrBits = ENTRY_ATTR_BITS;   /* r2 ends as the row-run attribute constant */
    } else {
        /* a negative count also runs the loop zero times: r2 stays the clear's leftover */
        out->attrBits = clearLeft.r2;
    }

    /* r3 stops at the loop's exit value; the final flags come from cmp r3, r1 */
    out->entriesFilled = (u32)filled;
    out->cmpA = (u32)filled;
    out->cmpB = entryCount;
}

