 * The 0x170-byte table is zero-filled first; it holds up to four entries of
 * 0x5C bytes each, and every entry is two adjacent 0x2E-byte half-rows of BG
 * map entries. For each entry, npc_checkEntryEventFlagOrHidden (r0 = running
 * tile id, r1 = entry byte offset, r2 = 0x7000) decides the entry's base tile
 * id; then three runs of tile pairs are written at the same halfword offsets
 * into both half-rows — the first half-row gets tile|flag, the second half-row
 * tile|flag+1 — with flag 0x7000 over offsets 0x00-0x14, 0x9000 over
 * 0x18-0x26, and 0x7000 again over 0x2A-0x2C. The halfwords at byte offsets
 * 0x16 and 0x28 of each half-row are never written, so they stay 0 from the
 * clear. The running tile id carries on from one entry to the next.
 *
 * Exit state: r1 = entry count, r2 = 0x7000 (the last flag run; when there are
 * no entries it is whatever the zero-fill left behind), r3 = entry count
 * (0x7000 when there are none), r4-r7 untouched, carry set / overflow clear
 * from the final entry-count compare (r3 reaches exactly entryCount). r0, nz
 * and lr are not preserved.
 */

#define NPC_TILE_TABLE  A_unk_2026700
#define NPC_TABLE_BYTES 0x170
#define NPC_ENTRY_BYTES 0x5C
#define NPC_ENTRY_HALF  0x2E

/* register form: calls ZeroFillByByte outside this file, which has no typed C interface yet
 * Reads back r2 because that is what the original exits with when the entry
 * count is 0 (r3-r7 are kept by the callee, so no other leftover matters). */
static u32 clear_npc_tile_table(u32 table, u32 byteCount) {
    R0 = table;
    R1 = byteCount;
    /* The original reaches this call with r2 = 7 (the scratch used to build
     * the 0x7000 flag mask) and r3 = 0x7000 (the mask itself). */
    R2 = 7;
    R3 = 0x7000;
    GUEST_CALL(ZeroFillByByte);
    return R2;
}

/* register form: calls npc_checkEntryEventFlagOrHidden_812818C outside this file, which has no typed C interface yet */
static u32 npc_entry_tile(u32 runningTile, u32 entryByteOffset, u32 flagMask, u32 entryIndex,
                          u32 firstHalfRow, u32 secondHalfRow) {
    R0 = runningTile;
    R1 = entryByteOffset;
    R2 = flagMask;
    R3 = entryIndex;
    R4 = 0;               /* the original zeroes this before the call */
    R6 = secondHalfRow;
    R7 = firstHalfRow;
    GUEST_CALL(npc_checkEntryEventFlagOrHidden_812818C);
    return R0;
}

/* Fills the table; reports the exit values of r2/r3 the original ends with. */
static void build_npc_tile_tables(u32 firstTileId, s32 entryCount, u32 *r2Out, u32 *r3Out) {
    u32 tileId = firstTileId;
    s32 entry;

    *r2Out = clear_npc_tile_table(NPC_TILE_TABLE, NPC_TABLE_BYTES);

    if (entryCount == 0) {
        /* ZeroFillByByte keeps r3 intact, so the original exits with r3 = 0x7000. */
        *r3Out = 0x7000;
        return;
    }

    for (entry = 0; entry < entryCount; entry++) {
        u32 firstHalfRow = NPC_TILE_TABLE + entry * NPC_ENTRY_BYTES;
        u32 secondHalfRow = firstHalfRow + NPC_ENTRY_HALF;
        u32 off;

        tileId = npc_entry_tile(tileId, entry * NPC_ENTRY_BYTES, 0x7000, entry,
                                firstHalfRow, secondHalfRow);

        for (off = 0x00; off < 0x16; off += 2) {   /* first flag run: 0x7000 */
            u32 lead = tileId | 0x7000;
            ST16(firstHalfRow + off, lead);
            ST16(secondHalfRow + off, lead + 1);
            tileId += 2;
        }
        tileId += 2;                               /* skid over the empty slot 0x16 */

        for (off = 0x18; off < 0x28; off += 2) {   /* second flag run: 0x9000 */
            u32 lead = tileId | 0x9000;
            ST16(firstHalfRow + off, lead);
            ST16(secondHalfRow + off, lead + 1);
            tileId += 2;
        }
        tileId += 2;                               /* skid over the empty slot 0x28 */

        for (off = 0x2A; off < 0x2E; off += 2) {   /* third flag run: 0x7000 */
            u32 lead = tileId | 0x7000;
            ST16(firstHalfRow + off, lead);
            ST16(secondHalfRow + off, lead + 1);
            tileId += 2;
        }
    }

    /* The original reloads r2 = 0x7000 for the last flag run, and the loop
     * counter reaches exactly entryCount before it falls out. */
    *r2Out = 0x7000;
    *r3Out = (u32)entryCount;
}

