    R1 = entryCount, R2 = r2Out, R3 = r3Out;       /* results (r5 already correct) */
    R4 = r4In, R6 = r6In, R7 = r7In;               /* the calls recorded over these */
    SET_FLAGS_CMP(entryCount, entryCount);         /* equal at exit: C set, V clear */
    RETURN_TO_CALLER();
}

