/*
 * Alliance slot check for a battle object.
 *
 * type_idx (0 or 1) selects which alliance mask (bit 0x20 / 0x40 in obj+0x4C)
 * and which u32 field (+0x5C / +0x60) to compare against.  If the mask bit is
 * clear the object is irrelevant and we return the TST flags.  Otherwise we
 * compute (field - halfword_at_pos_offset), adjust for scroll, and if the
 * result falls in [0, max_val] we call the range-fill helper and clear the
 * active flag; otherwise we set the active flag.
 */
static bool alliance_slot_check(u32 pos_offset, u32 pos_value, u32 base_addr,
                                u32 type_idx, u32 max_val,
                                u32 scroll_field_off, u32 obj, u32 active_flag_obj,
                                u32 *out_r0, u32 *out_r1, u32 *out_r2, u32 *out_r3) {
    u32 flags_word = LD32(obj + oBattleObject_Alliance);  /* obj + 0x4C */
    u32 mask = kAllianceMask[type_idx];

    if ((flags_word & mask) == 0) {
        *out_r0 = mask;
        *out_r1 = flags_word;
        *out_r2 = type_idx << 2;
        *out_r3 = type_idx;
        return false;  /* caller branches on Z; early-return path */
    }

    /* Adjust position by (signed 16-bit at obj+0x18) * 8 */
    s32 scroll_adj = (s16)LD16(obj + 0x18) << 3;
    u32 adjusted_pos = pos_value - (u32)scroll_adj;

    /* Read type-specific u32 field and halfword at pos_offset from obj */
    u32 field_off = kAllianceFieldOff[type_idx];
    u32 field_val = LD32(obj + field_off);
    u32 half_val  = LD16(obj + pos_offset);
    s32 delta     = (s32)field_val - (s32)half_val;

    if (delta < 0 || delta > (s32)max_val) {
        /* Out-of-range: set active flag */
        u32 halfword = half_val; /* r3 at F4 entry in original */
        *out_r0 = f4_call_full(1, active_flag_obj, (u32)delta, halfword, type_idx);
        *out_r1 = R1; *out_r2 = R2; *out_r3 = R3;
    } else {
        /* In-range: compute target address, fill, then clear active flag */
        u32 fill_addr = base_addr + ((u32)delta << 4);
        u32 d4_result = d4_call(adjusted_pos, fill_addr, active_flag_obj,
                                max_val, type_idx);
        *out_r0 = f4_call_mode(0, active_flag_obj);
        *out_r1 = R1; *out_r2 = R2; *out_r3 = R3;
        (void)d4_result; /* value passed through guest state to F4 via R3 */
    }
    return true;  /* callee set the final flags */
}

