#define HOLEOBJ_TILE_LO  0x3C   /* u16 extent of the tile on screen */
#define HOLEOBJ_TILE_HI  0x3E   /* u16 extent of the tile on screen */
#define HOLEOBJ_TRIM_ALT 0x2E   /* u16 span trim used for mode 2 */
#define HOLEOBJ_TRIM_DEF 0x24   /* u16 span trim used otherwise */
