typedef struct {
    u32 r0;
    u32 r1;
    u32 r2;
    u32 r3;
    u32 nz;      /* value the original's final flag-setting instruction evaluated */
} HoleScreenState;

static HoleScreenState update_hole_object(u32 obj, u32 old_r1, u32 old_r2, u32 old_r3)
{
    HoleScreenState out;

    /* effect not active on this object: nothing happens */
    if (LD8(obj + HOLEOBJ_ENABLE) == 0) {
        out.r0 = 0;
        out.r1 = old_r1;
        out.r2 = old_r2;
        out.r3 = old_r3;
        out.nz = 0;
        return out;
    }

    u32 mode = LD32(obj + HOLEOBJ_MODE);
    u32 screen_x = LD32(A_byte_813470C + (mode << 2));
    u32 ystep = (u32)(s16)LD16(obj + HOLEOBJ_Y) << 3;
    u32 packed_pos = (screen_x - ystep) << 16;

    u32 span = LD16(obj + HOLEOBJ_TILE_HI) + LD16(obj + HOLEOBJ_TILE_LO);
    u32 trim = (mode == 2) ? LD16(obj + HOLEOBJ_TRIM_ALT)
                           : LD16(obj + HOLEOBJ_TRIM_DEF);
    span -= trim;

    /* only a small band around the tile edge gets the hole effect */
    if ((s32)span < 0 || span > 6) {
        out.r0 = packed_pos;
        out.r1 = 0x20;
        out.r2 = span;
        out.r3 = mode;
        /* nz as "sub span" / "cmp span,#6" leaves it */
        out.nz = ((s32)span < 0) ? span : span - 6;
        return out;
    }

    /* queue the effect: position packed as (screen x << 16) | tile row bits */
    packed_pos |= 0x20 + (span << 4);

    u32 counter = LD8(obj + HOLEOBJ_STATE);          /* saved across the callee */
    u32 tile_word = (counter & 0xF) | 0x80000000;

    u32 hole_r3;
    spawn_hole_tile(packed_pos, 0x20003, tile_word,
                    A_byte_81331F4, 0x40000000, &hole_r3);

    /* advance the run counter in the high nibble of the slot byte; when it
     * would hit zero, ask for the next slot id instead */
    u32 runs = (counter >> 4) - 1;
    u32 count;
    if (runs != 0) {
        count = runs;
    } else {
        u32 pick_r1, pick_r3;
        ST8(obj + HOLEOBJ_STATE,
            take_next_hole_slot(A_dword_81331FC, &pick_r1, &pick_r3));
        count = pick_r1;
        hole_r3 = pick_r3;
    }

    /* stitch the byte back together: old low nibble, new high nibble */
    u32 state = (LD8(obj + HOLEOBJ_STATE) & 0xF) | (count << 4);
    ST8(obj + HOLEOBJ_STATE, state);

    out.r0 = state;
    out.r1 = count << 4;
    out.r2 = 0xF;
    out.r3 = hole_r3;   /* whatever the last effect callee left in r3 */
    out.nz = state;
    return out;
}

