#define MODE_MASK_BASE   0x08134994u   /* byte_8134994: {0x20, 0x40} */
#define FIELD_OFF_BASE   0x081349A0u   /* off_81349A0:  {0x5C, 0x60, …} */
#define STATE_WORD_OFF   0x4Cu
#define Y_SCALE_OFF      0x18u

typedef struct { u32 r0, r1, r2, r3; } EventOut;

static EventOut check_transition(u32 event_struct, u32 field_off, u32 base_addr,
                                 u32 mode, u32 threshold, u32 id)
{
    /* --- bit test ------------------------------------------------------- */
    u32 state_word = LD32(event_struct + STATE_WORD_OFF);
    u32 mask_idx   = mode << 2;
    u32 mask       = LD32(MODE_MASK_BASE + mask_idx);
    u32 and_result = state_word & mask;

    if (and_result == 0) {
        /* Bit not set: return the loaded values (matches TST r1,r0 + BEQ). */
        EventOut out = { mask, state_word, mask_idx, mode };
        return out;
    }

    /* --- compute position difference ------------------------------------ */
    u32 current_pos    = LD16(event_struct + field_off);
    u32 field_offset   = LD32(FIELD_OFF_BASE + mask_idx);
    u32 sprite_row     = (s32)LDS16(event_struct + Y_SCALE_OFF) * 8;
    u32 ref_pos        = LD32(event_struct + field_offset) - current_pos;
    u32 anim_pos       = base_addr - sprite_row;

    if ((s32)ref_pos < 0) {
        /* Position is before the sprite: signal "out of range". */
        R0 = 1; R1 = id; R2 = 0; R3 = mode;
        GUEST_CALL(sub_81171F4);
        EventOut out = { R0, R1, R2, R3 };
        return out;
    }

    if ((s32)ref_pos > (s32)threshold) {
        /* Position is past the allowed window: same signal. */
        R0 = 1; R1 = id; R2 = 0; R3 = mode;
        GUEST_CALL(sub_81171F4);
        EventOut out = { R0, R1, R2, R3 };
        return out;
    }

    /* --- within range: transform sprite, then signal "normal" ----------- */
    u32 scaled_diff = ref_pos << 4;
    u32 sprite_ptr  = anim_pos + scaled_diff;
    u32 d4_result   = sprite_transform(anim_pos, sprite_ptr, id, threshold);

    R0 = 0; R1 = id; R2 = 0; R3 = d4_result;
    GUEST_CALL(sub_81171F4);
    EventOut out = { R0, R1, R2, R3 };
    return out;
}

