 *             r4=threshold, r5=id, r7=?) -> r0 r1 r2 r3, nz c v */
Next sub_8134930(void) {
    EventOut res = check_transition(R0, R1, R2, R3, R4, R5);
    R0 = res.r0; R1 = res.r1; R2 = res.r2; R3 = res.r3;
