 * are base coordinates, limit bounds the distance to the slot, obj is the
 * object base and ctx is passed on to both sub-calls.  Returns the registers
 * the original leaves behind. */
static CallResult place_in_slot(u32 field_offset, u32 x, u32 y, u32 slot, u32 limit,
                                u32 obj, u32 ctx) {
