    if (!(status & mask)) {
        /* Slot disabled: bail out immediately, the mask is left in r0. */
        out.r0 = mask;
        out.r1 = status;
        out.r2 = slot << 2;
        out.r3 = slot;
        out.nz = 0;                        /* TST found the bit clear */
        return out;
