    u32 start_x = x - (u32)((s32)(s16)LD16(obj + 0x18) * 8);
    s32 distance = (s32)LD32(obj + s_slot_offsets[slot]) - (s32)LD16(obj + field_offset);

    if (distance < 0 || distance > (s32)limit)
        return call_81171F4(1, ctx);       /* out of range: report failure */

    call_81171D4(start_x, y + ((u32)distance << 4), ctx);
    return call_81171F4(0, ctx);           /* in range: report success */
