#define OBJ_Y_OFFSET   0x18  /* s16, offset from the table x, in 8-pixel units */
#define OBJ_BOX_SMALL  0x24  /* row offset used for sprite indices other than 2 */
#define OBJ_BOX_LARGE  0x2e  /* row offset used for sprite index 2 */
#define OBJ_BASE_A     0x3c
#define OBJ_BASE_B     0x3e
#define OBJ_INDEX      0x40  /* 0..2, selects the x-position table entry */
#define OBJ_ACTIVE     0x44  /* non-zero while the object is drawn */

/* ROM data used by this routine. */
#define SPRITE_X_TABLE 0x0813470C  /* byte_813470C: three x positions, indexed by OBJ_INDEX */
#define SPRITE_GFX     0x081331F4  /* byte_81331F4: graphic table handed to the sprite queue */
#define SPRITE_SCRIPT  0x081331FC  /* dword_81331FC: animation script */

