typedef struct {
    u32 out0, out1, out2, out3;  /* values the adapter stores into r0..r3 */
    u32 flags;                   /* value whose N/Z the caller observes */
} ObjectUpdate;

static ObjectUpdate update_object_sprite(u32 obj, u32 r1_in, u32 r2_in, u32 r3_in) {
    ObjectUpdate out;

    if (LD8(obj + OBJ_ACTIVE) == 0) {
        /* Object is switched off: nothing is drawn, r1..r3 keep their values. */
        out.out0 = 0;
        out.out1 = r1_in;
        out.out2 = r2_in;
        out.out3 = r3_in;
        out.flags = 0;
        return out;
    }

    u32 index = LD32(obj + OBJ_INDEX);
    u32 x = (LD32(SPRITE_X_TABLE + index * 4)
             - (u32)((s32)(s16)LD16(obj + OBJ_Y_OFFSET) * 8)) << 16;
    u32 row = (u32)LD16(obj + OBJ_BASE_B) + LD16(obj + OBJ_BASE_A)
              - ((index == 2) ? LD16(obj + OBJ_BOX_LARGE) : LD16(obj + OBJ_BOX_SMALL));

    if ((s32)row < 0 || (s32)row > 6) {
        /* Row falls outside the seven slots the sprite may occupy: skip it. */
        out.out0 = x;
        out.out1 = 0x20;
        out.out2 = row;
        out.out3 = index;
        out.flags = row;
        return out;
