    out.out0 = low | (countdown << 4);
    out.out1 = countdown << 4;
    out.out2 = 0xf;
    out.out3 = r3;
    out.flags = out.out0;
    ST8(obj + OBJ_ANIM, out.out0);
    return out;
}

