    u32 flags = (u32)LD8(newObj + oObjectHeader_Flags) | 0x10;
    ST8(newObj + oObjectHeader_Flags, (u8)flags);

    Spawn36Outputs spawned = { flags, alliance, parent, flags };
    return spawned;
}

/* sub_80CAC58(r0 = extraVars, r1, r2 = element, r5 = parent, r6, r7 = slot)
 *   -> r2, r3, r5 */
Next sub_80CAC58(void) {
    Spawn36Outputs o = spawn_linked_object36(R0, R1, R2, R5, R6, R7);
    R2 = o.r2;
    R3 = o.r3;
    R5 = o.r5;
    SET_FLAGS_NZ(o.nz);
    RETURN_TO_CALLER();
}

/* Table of flag masks for the alliance check (byte_8134994 read as u32) */
static const u32 ALLIANCE_FLAG_MASK[2] = { 0x20, 0x40 };

/* Table of object offsets for the 32-bit counter (off_81349A0 read as u32) */
static const u32 ALLIANCE_COUNTER_OFFSET[2] = { 0x5C, 0x60 };

/* Holds the register results from sub_81171F4 / sub_81171D4 */
typedef struct {
    u32 r0, r1, r2, r3;
    u32 lr;
} RegBundle;

/* register form: calls sub_81171F4 outside this file, which has no typed C interface yet */
static RegBundle call_set_alliance_flag(u32 state, u32 target) {
    R0 = state;
    R1 = target;
    GUEST_CALL(sub_81171F4);
    RegBundle res;
    res.r0 = R0; res.r1 = R1; res.r2 = R2; res.r3 = R3;
    res.lr = LR;
    return res;
}

/* register form: calls sub_81171D4 outside this file, which has no typed C interface yet */
static void call_move_battler(u32 x, u32 pos, u32 slot, u32 y) {
    R0 = x;
    R1 = pos;
    R2 = slot;
    R3 = y;
    GUEST_CALL(sub_81171D4);
}

/* Result of the alliance-index test: either from a callee or the no-action path */
typedef struct {
    u32 r0, r1, r2, r3;
    u32 lr;
    u32 nz_flag_value;   /* 0 means "Z set" for the no-action path; 0xFFFF sentinel means
                            "flags already set by GUEST_CALL, adapter should not overwrite" */
} TestResult;

/* Check whether an alliance index is active and test/reposition the battler slot.
 * halfword_off: u16 offset into object for reading a position value
 * base_val:     u32 starting position (adjusted by scaled height)
 * ptr_base:     u32 base pointer for the positioning call
 * index:        u32 alliance slot (0 or 1)
 * upper_limit:  u32 maximum allowable index offset
 * object:       u32 pointer to the toolkit/battle-state object
 * context:      u32 pointer passed to the flag/movement callees
 * original_lr:  u32 caller's LR (returned unchanged on no-action path)
 * Returns register bundle and flag info for the adapter. */
static TestResult test_alliance_slot(u16 halfword_off, u32 base_val, u32 ptr_base,
                                     u32 index, u32 upper_limit, u32 object, u32 context,
                                     u32 original_lr) {
    u32 flag_word = LD32(object + 0x4C);
    u32 mask = ALLIANCE_FLAG_MASK[index];

    if ((flag_word & mask) == 0) {
        /* Alliance not active – return intermediate values, Z will be set */
        TestResult res;
        res.r0 = mask;
        res.r1 = flag_word;
        res.r2 = index << 2;
        res.r3 = index;
        res.lr = original_lr;
        res.nz_flag_value = 0;
        return res;
    }

    /* Adjust base_val by the object's height (s16 at +0x18, scaled by 8) */
    s32 height = (s16)LD16(object + 0x18);
    u32 adjusted_base = base_val - (u32)(height << 3);

    /* Read the alliance counter at the indexed offset */
    u32 counter_offset = ALLIANCE_COUNTER_OFFSET[index];
    u32 counter = LD32(object + counter_offset);

    /* Read a u16 position from object at halfword_off */
    u32 position = LD16(object + (u32)halfword_off);

    s32 diff = (s32)counter - (s32)position;
    u32 slot = (u32)diff;

    if (diff < 0 || diff > (s32)upper_limit) {
        /* Out of range – set alliance flag active (state = 1) */
        RegBundle callee_res = call_set_alliance_flag(1, context);
        TestResult res;
        res.r0 = callee_res.r0;
        res.r1 = callee_res.r1;
        res.r2 = callee_res.r2;
        res.r3 = callee_res.r3;
        res.lr = callee_res.lr;
        res.nz_flag_value = 0xFFFF;  /* sentinel: GUEST_CALL already set flags */
        return res;
    }

    /* Within range – position the battler and clear the flag */
    u32 scaled_slot = slot << 4;
    u32 final_pos = ptr_base + scaled_slot;
    call_move_battler(adjusted_base, final_pos, context, index);

    RegBundle callee_res = call_set_alliance_flag(0, context);
    TestResult res;
    res.r0 = callee_res.r0;
    res.r1 = callee_res.r1;
    res.r2 = callee_res.r2;
    res.r3 = callee_res.r3;
    res.lr = callee_res.lr;
    res.nz_flag_value = 0xFFFF;
    return res;
}

/* sub_8134930(r0=halfword_offset, r1=base_val, r2=ptr_base, r3=index,
 *             r4=upper_limit, r5=object, r7=context) -> r0 r1 r2 r3 r5 r6 lr, nz c v */
Next sub_8134930(void) {
    TestResult res = test_alliance_slot((u16)R0, R1, R2, R3, R4, R5, R7, LR);
    R0 = res.r0; R1 = res.r1; R2 = res.r2; R3 = res.r3; LR = res.lr;
    if (res.nz_flag_value != 0xFFFF) SET_FLAGS_NZ(res.nz_flag_value);
    RETURN_TO_CALLER();
}

/*
 * sub_8134930 – validate a battle-object draw position for the given axis (index 0/1/2),
 * test the corresponding "visible" flag in the object, and if valid delegate the
 * actual draw via sub_81171D4 then sub_81171F4.
 *
 * r0 = field-offset into the object for the halfword limit
 * r1 = raw position (pixel coordinate on the relevant axis)
 * r2 = draw base address
 * r3 = axis index (0 = x, 1 = y, 2 = z/depth)
 * r4 = limit value (stored, compared against scaled position)
 * r5 = battle-object pointer
 * r7 = render-list / tile-buffer pointer passed to the helpers
 */

/* Per-axis flag masks stored as 32-bit words in ROM. */
#define BATTLE_VISIBLE_FLAG_X   0x20u
#define BATTLE_VISIBLE_FLAG_Y   0x40u

/* Per-axis struct offsets for the halfword coordinate used in the bound check. */
#define BATTLE_POS_X_OFFSET     0x5Cu
#define BATTLE_POS_Y_OFFSET     0x60u
#define BATTLE_POS_Z_LO         5u   /* u16 halves of word at 0x081349AC+0 */
#define BATTLE_POS_Z_HI         6u   /* u16 halves of word at 0x081349AC+4 */

#define BATTLE_FLAG_WORD_OFFSET 0x4Cu
#define BATTLE_SCROLL_OFFSET    0x18u

/* register form: sub_81171F4 sets r0-r3, lr, and all flags; no typed C interface exists */
static void call_pos_done(u32 state, u32 render_list, u32 r3_val, u32 r4_val) {
    R0 = state; R1 = render_list; R3 = r3_val; R4 = r4_val;
    GUEST_CALL(sub_81171F4);
}

/* register form: sub_81171D4 sets r3; no typed C interface exists */
static void call_pos_draw(u32 x, u32 y, u32 render_list, u32 limit) {
    R0 = x; R1 = y; R2 = render_list; R3 = limit;
    GUEST_CALL(sub_81171D4);
}

/* Return the per-axis visibility flag mask for index (0, 1, 2). */
static u32 axis_flag_mask(s32 axis) {
    static const u32 table[] = { BATTLE_VISIBLE_FLAG_X, BATTLE_VISIBLE_FLAG_Y };
    /* axis >= 2 reads past the two-element table (original's 8-byte blob);
       index 2 yields 0x081349A0, always non-zero when ANDed. */
    if (axis >= 0 && axis <= 1) return table[axis];
    return 0u;
}

/* Return the per-axis struct halfword offset for index (0, 1, 2). */
static u32 axis_pos_offset(s32 axis, u32 raw_arg) {
    static const u32 table[] = { BATTLE_POS_X_OFFSET, BATTLE_POS_Y_OFFSET };
    if (axis == 0) return table[0];
    if (axis == 1) return table[1];
    /* axis == 2: original loads from 0x081349AC whose halves are 5 and 6;
       the halfword at (r5 + raw_arg) is compared against the z-limit. */
    return raw_arg;  /* handled by caller via LD16 */
}

/*
 * Main logic.  Returns:
 *   -2  → early exit (flag not set);  caller uses 'tst_val' for NZ flags
 *   other → value for SET_FLAGS_NZ when the call path returned (flags already
 *            set in registers by GUEST_CALL, so adapter should NOT overwrite;
 *            we signal this with a distinct sentinel).
 *
 * Actually simpler: return a struct with the NZ value and a "skip flag-set" bool.
 */
typedef struct {
    u32 nz_value;       /* value to feed SET_FLAGS_NZ (0 means "don't set") */
    bool set_flags;     /* true → adapter should SET_FLAGS_NZ; false → GUEST_CALL set them */
} SubResult;

static SubResult check_battle_position(u32 limit_off, u32 raw_pos, u32 draw_base,
                                       s32 axis, u32 limit, u32 obj, u32 render_list) {
    /* --- flag gate --- */
    u32 flags_word = LD32(obj + BATTLE_FLAG_WORD_OFFSET);
    u32 mask;
    switch (axis) {
        case 0:  mask = BATTLE_VISIBLE_FLAG_X; break;
        case 1:  mask = BATTLE_VISIBLE_FLAG_Y; break;
        default: mask = 0x081349A0u;           /* original: reads 4 bytes past the 8-byte blob */
    }

    u32 tst = flags_word & mask;
    if (tst == 0) {
        /* beq taken: return with TST flags; r0-r3 unchanged by this function */
        SubResult res;
        res.nz_value = tst;
        res.set_flags = true;
        return res;
    }

    /* --- scroll-adjusted position --- */
    s32 scroll = (s16)LD16(obj + BATTLE_SCROLL_OFFSET);
    u32 adjusted_pos = raw_pos - (u32)(scroll << 3);

    /* --- axis-specific position halfword from the object struct --- */
    u32 pos_off;
    switch (axis) {
        case 0:  pos_off = BATTLE_POS_X_OFFSET; break;
        case 1:  pos_off = BATTLE_POS_Y_OFFSET; break;
        case 2:  pos_off = (axis == 2) ? LD32(0x081349A0u + 8) : 0;
                 /* original: r3 = *(off_81349A0 + 8) = 0x081349AC → LD16(obj + 0x081349AC)
                    which effectively reads the z-limit; simplified: */
                 pos_off = 0u;  /* handled below */
                 break;
        default: pos_off = 0; break;
    }

    /* Recompute cleanly: the original loads LD16(obj + limit_off) for the "actual position" */
    u32 actual_pos = LD16(obj + limit_off);
    u32 field_pos;
    if (axis == 0)      field_pos = LD16(obj + BATTLE_POS_X_OFFSET);
    else if (axis == 1) field_pos = LD16(obj + BATTLE_POS_Y_OFFSET);
    else                field_pos = (s16)LD16(obj + (u32)0x081349ACu); /* ROM blob: z offset */

    s32 diff = (s32)field_pos - (s32)actual_pos;

    /* --- bounds check (bge → skip failure; bgt → also failure) --- */
    if (diff < 0 || (s32)limit < diff) {
        call_pos_done(1, render_list, 0, 0);
        SubResult res;
        res.set_flags = false;
        return res;
    }

    /* --- in-bounds: draw then finish --- */
    u32 scaled = (u32)diff << 4;
    u32 draw_y = draw_base + scaled;
    call_pos_draw(adjusted_pos, draw_y, render_list, limit);
    call_pos_done(0, render_list, 0, limit);

    SubResult res;
    res.set_flags = false;
    return res;
}

/* sub_8134930(r0=limit_off, r1=raw_pos, r2=draw_base, r3=axis, r4=limit, r5=obj, r7=render_list) */
Next sub_8134930(void) {
    /* register form: GUEST_CALL paths leave r0-r3/lr/flags in the register file;
       adapter must not overwrite them on those paths, but must set flags on early return. */
    SubResult res = check_battle_position(R0, R1, R2, (s32)R3, R4, R5, R7);
    /* register form: conditional flag write without branching in adapter */
    if (res.set_flags) SET_FLAGS_NZ(res.nz_value);
    RETURN_TO_CALLER();
}

/* sub_8134930 – per-axis sprite bounds check for a battle entity. */

typedef struct { u32 r0, r1, r2, r3, lr; u32 nz_val; bool c; bool v; } RegResult;
typedef struct { s32 nz_val; bool c; bool v; } FlagResult;

/* Table of per-axis activation bitmasks stored in the battle-object flags field (offset 0x4C). */
#define SLOT_ACTIVE_MASK_0  0x20u
#define SLOT_ACTIVE_MASK_1  0x40u

/* Per-axis field offsets into the battle object holding the slot-start position (u32). */
#define SLOT_START_X  0x5Cu
#define SLOT_START_Y  0x60u

/* Tile-row height in pixels (LD16_SIGNED(r5, 0x18) * 8 is subtracted from x). */
#define TILE_ROW_PX  8

/* Pixel size of one slot in the direction being checked (slot_diff * 16 added to coord). */
#define SLOT_SIZE_PX 16

/* register form: calls sub_81171F4 outside this file, which has no typed C interface yet.
 * All eight guest registers (and the link address the callee returns to) are live on
 * entry, so they must be staged via the register file – a plain typed call cannot pass
 * r6/r7/lr through C parameters. */
static RegResult call_set_active(u32 r0, u32 r1, u32 r2, u32 r3,
                                 u32 r4, u32 r5, u32 r6, u32 r7) {
    R0 = r0; R1 = r1; R2 = r2; R3 = r3;
    R4 = r4; R5 = r5; R6 = r6; R7 = r7;
    GUEST_CALL(sub_81171F4);
    return (RegResult){ R0, R1, R2, R3, LR, (cpu.nz), (cpu.c), (cpu.v) };
}

/* register form: calls sub_81171D4 outside this file, which has no typed C interface yet.
 * The callee's side-effects on guest RAM and flags are the result; all live registers
 * must be staged because the function is not otherwise exposed as a typed entry. */
static FlagResult call_place_sprite(u32 r0, u32 r1, u32 r2, u32 r3,
                                    u32 r4, u32 r5, u32 r6, u32 r7) {
    R0 = r0; R1 = r1; R2 = r2; R3 = r3;
    R4 = r4; R5 = r5; R6 = r6; R7 = r7;
    GUEST_CALL(sub_81171D4);
    return (FlagResult){ (cpu.nz), (cpu.c), (cpu.v) };
}

/* Check whether pixel coordinate (x, y) falls inside the active slot range of battle
 * object bobj along the axis selected by axis (0 = horizontal, 1 = vertical).
 *
 * field_off  – u16 field offset into bobj whose value is the entity's own position
 * axis       – 0 or 1; selects activation mask and slot-start field
 * threshold  – maximum valid slot index along the axis
 *
 * Returns the final register state (r0–r3, lr, flags) and preserves r4–r7
 * (re-staged by the adapter from the incoming values). */
static RegResult check_battle_sprite_range(u32 field_off, u32 x, u32 y, u32 axis,
                                           u32 threshold, u32 bobj,
                                           u32 r6_in, u32 r7_in) {
    /* Is this axis enabled for the entity? */
    u32 mask = LD32(bobj + oBattleObject_Flags);   /* offset 0x4C */
    u32 activation = (axis == 0) ? SLOT_ACTIVE_MASK_0 : SLOT_ACTIVE_MASK_1;
    if (!(mask & activation)) {
        /* Axis disabled – early return with flags from the TST (result was zero). */
        u32 nz = mask & activation;  /* == 0 */
        return (RegResult){ field_off, x, y, axis, LR, nz, false, false };
    }

    /* Pixel offset from the entity's tile-row origin. */
    s32 tile_row = (s16)LD16(bobj + 0x18);
    u32 x_offset = x - (u32)(tile_row << 3);

    /* Current slot start position for this axis minus the entity's own field. */
    u32 slot_start_off = (axis == 0) ? SLOT_START_X : SLOT_START_Y;
    s32 slot_diff = (s32)LD32(bobj + slot_start_off) - (s32)LD16(bobj + field_off);

    /* Out-of-bounds (before start) or past the threshold → deactivate. */
    if (slot_diff < 0 || slot_diff > (s32)threshold) {
        return call_set_active(1, r7_in, (u32)slot_diff,
                               (u32)LD16(bobj + field_off),
                               axis, bobj, r6_in, r7_in);
    }

    /* Within range: place the sprite, then mark active. */
    u32 y_adjusted = y + (u32)(slot_diff << 4);   /* slot_diff * SLOT_SIZE_PX */
    call_place_sprite(x_offset, y_adjusted, r7_in, threshold,
                      axis, bobj, r6_in, r7_in);
    /* R2, R3 retain callee's leftover values (original does not re-read them). */
    return call_set_active(0, r7_in, y_adjusted, threshold,
                           axis, bobj, r6_in, r7_in);
}

Next sub_8134930(void) {
    RegResult res = check_battle_sprite_range(R0, R1, R2, R3, R4, R5, R6, R7);
    R0 = res.r0; R1 = res.r1; R2 = res.r2; R3 = res.r3; LR = res.lr;
    SET_FLAGS_NZ(res.nz_val); SET_FLAGS_C(res.c); SET_FLAGS_V(res.v);
    RETURN_TO_CALLER();
}

/* sub_8134610 (bn6f): refresh the anchored effect sprite of the object in r5.
 *
 * Object fields used:
 *   +0x44  gate byte: 0 means "idle this frame", the whole function is skipped
 *   +0x40  slot index selecting an anchor coordinate from the table at
 *          byte_813470C
 *   +0x18  signed 16-bit vertical offset, shifted onto the 8-pixel grid
 *   +0x3C/+0x3E  16-bit pair summing to the sprite's row reach
 *   +0x24/+0x2E  row limit (slot 2 uses [+0x2E], everyone else [+0x24])
 *   +0x16  palette byte: low nibble a countdown nibble, high nibble a phase
 *
 * When the computed row offset stays inside the 7-row window below the
 * anchor, the function composes a sprite word (anchor X | shifted Y half |
 * row offset) and submits it to the sprite composer sub_811FAF4 with the
 * palette encoded in r2.  Afterwards the countdown nibble at +0x16 ticks
 * down; when it expires, sub_8120CC8 hands out a fresh palette index.
 *
 * Both internal callees are real game functions whose leftovers escape: r0
 * and r3 of sub_811FAF4 are reused when the word is recombined, and r1/r3
 * (plus the overflow flag) of sub_8120CC8 end up in the final register state,
 * so both are driven through register-form helpers.
 */

/* Everything the original leaves behind that the adapter must install. */
struct sub_8134610_out {
    u32 r0, r1, r2, r3;   /* final guest registers */
    u32 nzx;              /* value the final ORR acts on (N and Z come from it) */
    u32 c, v;             /* final C and V flag bits */
    u32 cmp_a, cmp_b;     /* CMP operands that reproduce exactly (c, v) */
};

/* register form: calls sub_811FAF4 outside this file, which has no typed C interface yet */
static void call_sub_811FAF4(u32 coord, u32 mode, u32 palette, u32 table, u32 param,
                             u32 *ret_r0, u32 *ret_r3) {
    R0 = coord; R1 = mode; R2 = palette; R3 = table; R4 = param;   /* 0x20003 / 0x40000000 pool words */
    GUEST_CALL(sub_811FAF4);
    *ret_r0 = R0;   /* the original recombines the caller's word with this r0 */
    *ret_r3 = R3;   /* its r3 is still live when the function returns */
}

/* register form: calls sub_8120CC8 outside this file, which has no typed C interface yet */
static u32 call_sub_8120CC8(u32 r0_in, u32 table, u32 *ret_r1, u32 *ret_r3, u32 *ret_v) {
    R0 = r0_in;     /* the sprite word composed for sub_811FAF4 is still in r0 */
    R1 = table;
    GUEST_CALL(sub_8120CC8);
    *ret_r1 = R1;   /* the new high nibble comes from the callee's leftover r1 */
    *ret_r3 = R3;
    *ret_v = OVERFLOW_FLAG();
    return R0;
}

/* The adapter can only emit flags as whole guest operations, so the final
 * (C, V) pair is delivered as operands of one CMP whose borrow and overflow
 * match it.  The CMP's own N/Z are discarded: the adapter sets them from the
 * ORR value afterwards, exactly like the original's tail lsls+orr. */
static void cmp_operands_for(u32 c, u32 v, u32 *a, u32 *b) {
    if (v && !c) {
        *a = 0;              /* 0 - 0x80000000 borrows and overflows  -> C=0 V=1 */
        *b = 0x80000000;
    } else if (v) {
        *a = 0x80000000;     /* 0x80000000 - 1 overflows, no borrow    -> C=1 V=1 */
        *b = 1;
    } else if (c) {
        *a = 2;              /* 2 - 1: no borrow, no overflow          -> C=1 V=0 */
        *b = 1;
    } else {
        *a = 0;              /* 0 - 1 borrows, no overflow             -> C=0 V=0 */
        *b = 1;
    }
}

static struct sub_8134610_out sub_8134610_body(u32 obj, u32 r1_in, u32 r2_in, u32 r3_in,
                                               u32 entry_c, u32 entry_v) {
    struct sub_8134610_out out;
    u32 gate = LD8(obj + 0x44);

    if (gate == 0) {
        /* idle object: leave every register but r0 (and the flags) alone */
        out.r0 = gate;
        out.r1 = r1_in;
        out.r2 = r2_in;
        out.r3 = r3_in;
        out.nzx = gate;         /* tst r0, r0 leaves Z set */
        out.c = entry_c;
        out.v = entry_v;
    } else {
        u32 slot = LD32(obj + 0x40);
        u32 anchor = LD32(A_byte_813470C + (slot << 2));
        u32 y_off = (u32)((s32)(s16)LD16(obj + 0x18) << 3);
        u32 base = (anchor - y_off) << 16;
        u32 reach = (u32)LD16(obj + 0x3E) + (u32)LD16(obj + 0x3C);
        u32 limit = LD16(obj + 0x2E);
        if (slot != 2)
            limit = LD16(obj + 0x24);
        u32 delta = reach - limit;

        if (delta >= 0x80000000 || (s32)delta > 6) {
            /* would land outside the 7-row window: bail out before drawing */
            out.r0 = base;
            out.r1 = y_off;
            out.r2 = delta;
            out.r3 = slot;
            out.nzx = (delta >= 0x80000000) ? delta : delta - 6; /* the SUB/CMP the branch followed */
            out.c = entry_c;
            out.v = entry_v;
        } else {
            u32 palette = LD8(obj + 0x16);
            u32 r0_left, r3_left;
            /* anchor X in the low half, shifted Y and row offset above it */
            call_sub_811FAF4(base | (y_off + (delta << 4)), 0x20003,
                             (palette & 0xF) | 0x80000000, A_byte_81331F4, 0x40000000,
                             &r0_left, &r3_left);

            /* the original spills the palette byte to its stack across the call */
            u32 phase = palette >> 4;
            u32 r1_pre, v_final;
            if (phase != 1) {
                /* countdown still alive: the high nibble just steps down */
                r1_pre = phase - 1;
                v_final = entry_v;      /* nothing between the calls touches V here */
                out.r3 = r3_left;
            } else {
                /* countdown expired: fetch a fresh palette index */
                u32 new_r1, new_r3;
                u32 fetched = call_sub_8120CC8(r0_left, A_dword_81331FC, &new_r1, &new_r3, &v_final);
                ST8(obj + 0x16, fetched);
                r1_pre = new_r1;
                out.r3 = new_r3;
            }
            /* the callee may have rewritten byte_16 - the original re-reads it here */
            u32 reloaded = LD8(obj + 0x16);
            u32 hi = r1_pre << 4;
            u32 stored = (reloaded & 0xF) | hi;
            ST8(obj + 0x16, stored);

            out.r0 = stored;
            out.r1 = hi;
            out.r2 = 0xF;
            out.nzx = stored;
            out.c = (r1_pre >> 28) & 1;  /* carry produced by shifting the high nibble */
            out.v = v_final;
        }
    }

