 *   - slots 6..0 of the first area, where a program tag that also sits in a higher slot is
 *     skipped (only the highest slot applies);
 *   - slots 0..48 of the second and third areas, each applied unconditionally.
 * Then refresh the derived pet stats. */
static void apply_navicust_programs(void) {
    u32 area;
    s32 slot;

    zero_fill_by_byte(byte_2006DD8, 8);

    slot = 6;
    area = get_work_area_2006CF8();
    do {
        u32 entry = LD8(area + slot);
