        slot--;
    } while (slot >= 0);

    slot = 0;
    area = get_work_area_813BD10();
    while (slot < 0x31) {
        u32 entry = LD8(area + slot);
        if (entry != 0) {
            u16 id = LD16(toolkit_entry_ptr(entry - 1));
            if (id != 0)
                run_ncp_handler(id);
        }
        slot++;
    }

    slot = 0;
    area = get_work_area_2006CC0();
    while (slot < 0x31) {
        u32 entry = LD8(area + slot);
        if (entry != 0) {
            u16 id = LD16(toolkit_entry_ptr(entry - 1));
            if (id != 0)
                run_ncp_handler(id);
        }
        slot++;
    }

    petnavi_apply_stat3e();
    navicust_finish();
}

