 * Pass 1 (slots 6→0): resolve each NCP, check for duplicate type bytes,
 *   dispatch to the per-NCP handler (e.g. SuperArmor, FldrPak, Rush …).
 * Pass 2 (slots 0→0x30): dispatch NCP handlers for the field-area programs.
 * Pass 3 (slots 0→0x30): dispatch NCP handlers for the pet-area programs.
 * Finally update Pet Navi stats and run the post-processing hook.
 */
static void apply_navicust_programs(void) {
    /* Clear the active-type tracking array before the first pass. */
    zero_fill(A_byte_2006DD8, NCP_TRACK_SLOTS);

    /* --- Pass 1: NCP programs, high-priority slots first --- */
    u32 work_area = get_ncp_work_area();

    for (s32 slot = NCP_FIRST_SLOTS - 1; slot >= 0; slot--) {
        u32 program_id = LD8(work_area + (u32)slot);
        if (!program_id)
            continue;

        u32 entry = toolkit_entry_ptr(program_id - 1);
        u16 ncp = LD16(entry);
        if (!ncp)
            continue;

        /* Look up the program-definition record; its first byte is the
         * "type" tag used for duplicate suppression. */
        u32 prog_ptr = get_ncp_program_def(ncp);
        u32 r2_from_def = R2;   /* sub_813B780 also fills R2 */
        u32 type = LD8(prog_ptr);

