            ST8(A_byte_2006DD8 + (u32)slot, type);
            /* If the same type is already tracked in a later slot,
             * defer handling to that slot's iteration. */
            for (u32 j = (u32)slot + 1; j < NCP_TRACK_SLOTS; j++) {
                if ((u8)LD8(A_byte_2006DD8 + j) == (u8)type) {
                    skip = true;
                    r2 = j + 1;
                    r3 = (u32)(u8)LD8(A_byte_2006DD8 + j);
                    break;
