            if (!skip) {
                /* Loop completed without match; registers at exit: */
                r2 = NCP_TRACK_SLOTS;
                r3 = (u32)(u8)LD8(A_byte_2006DD8 + (NCP_TRACK_SLOTS - 1));
            }
