            ncp_dispatch(ncp, work_area, (u32)slot, r1, r2, r3);
    }

    /* --- Pass 2: field-area NCP programs --- */
    work_area = get_field_work_area();

    for (u32 slot = 0; slot < NCP_LATER_SLOTS; slot++) {
        u32 program_id = LD8(work_area + slot);
        if (!program_id)
            continue;

        u32 entry = toolkit_entry_ptr(program_id - 1);
        u16 ncp = LD16(entry);
        if (!ncp)
            continue;

        u32 r1 = R1;   /* toolkit also returns R1 */
        u32 r2 = R2;   /* toolkit also returns R2 */
        u32 r3 = R3;
        ncp_dispatch(ncp, work_area, slot, r1, r2, r3);
    }

    /* --- Pass 3: pet-area NCP programs --- */
    work_area = get_pet_work_area();

    for (u32 slot = 0; slot < NCP_LATER_SLOTS; slot++) {
        u32 program_id = LD8(work_area + slot);
        if (!program_id)
            continue;

