        u32 r2 = R2;
        u32 r3 = R3;
        ncp_dispatch(ncp, work_area, slot, r1, r2, r3);
    }

    /* --- Post-processing --- */
    petnavi_update_stats(0, 0, work_area);
    ncp_finalize();
