            if (duplicate)
                break;   /* stop scanning – lower slots already handled */
        }

        dispatch_ncp_handler(ncp_sel & ~3u, (u32)slot + 1, ncp_sel,
                             (u32)slot, custom_area);
    next_slot:
        if (--slot < 0)
            break;
    }

    /* --- Second pass: 0x31 NCP entries in area 1 ---
     * Same dispatch but no duplicate check. */
    slot = 0;
    u32 area1 = get_ncp_area_1_ptr();
    for (; slot < NCP_AREA_MAX; slot++) {
        u32 prog_id = LD8(area1 + (u32)slot);
        if (prog_id == 0)
            continue;
        u32 entry = get_toolkit_entry_ptr(prog_id - 1);
        u16 ncp_sel = (u16)LD16(entry);
        if (ncp_sel == 0)
            continue;
        dispatch_ncp_handler(ncp_sel & ~3u, 0, ncp_sel, (u32)slot, area1);
    }

    /* --- Third pass: 0x31 NCP entries in area 2 --- */
    slot = 0;
    u32 area2 = get_ncp_area_2_ptr();
    u16 last_ncp = 0;
    for (; slot < NCP_AREA_MAX; slot++) {
        u32 prog_id = LD8(area2 + (u32)slot);
