            continue;
        u32 entry = get_toolkit_entry_ptr(prog_id - 1);
        u16 ncp_sel = (u16)LD16(entry);
        if (ncp_sel == 0)
            continue;
        last_ncp = ncp_sel;
        dispatch_ncp_handler(ncp_sel & ~3u, 0, ncp_sel, (u32)slot, area2);
    }

    /* Reconcile pet-navi stats after all programs are applied.
     * The callee reads r4 (last NCP selector), r6 (loop exit index), r7 (area ptr). */
    petnavi_update_stat((u32)last_ncp, (u32)slot, area2);
    finalize_navicust();
