/* Apply all equipped NavCust programs to the battle.
 * Iterates NavCust chip slots (6→0) with duplicate suppression,
 * then two sets of support/extra NCPs (0→0x30) without suppression,
 * dispatching each through the navicust_jt_NCPs jump table. */
static void apply_all_navicust_programs(u32 r5) {
    /* Clear the 8-byte "seen NCP category" tracking table */
    zero_fill_bytes(NAVICUST_TYPE_TABLE, NAVICUST_TYPE_TABLE_SIZE);

    /* --- Loop 1: NavCust chip slots 6 down to 0 (with duplicate check) --- */
    s32 slot = 6;
    u32 slot_area = get_navcust_slot_area();

    for (; slot >= 0; slot--) {
        u32 r6_val = (u32)(s32)slot;
        u8 ncp_id = LD8(slot_area + r6_val);
        if (ncp_id == 0) continue;

        u32 entry = get_ncp_entry_ptr(ncp_id - 1);
        u16 ncp_code = LD16(entry);
        if (ncp_code == 0) continue;

        u32 type_ptr = get_ncp_type_ptr(ncp_code);
        u8 ncp_type = LD8(type_ptr);

        if (ncp_type != 0) {
            /* Mark this category and scan for a duplicate in higher slots */
            ST8(NAVICUST_TYPE_TABLE + r6_val, ncp_type);
            bool duplicate = FALSE;
            for (u32 j = r6_val + 1; j < NAVICUST_TYPE_TABLE_SIZE; j++) {
                if (LD8(NAVICUST_TYPE_TABLE + j) == ncp_type) {
                    duplicate = TRUE;
                    break;
                }
            }
            if (duplicate) continue;
        }

        /* Dispatch the NCP handler; track r6 (loop counter) and r5 */
        NcpDispatchResult dr = ncp_dispatch(ncp_code, 0, 0,
                                            (u32)ncp_code, r5, r6_val, slot_area);
        r5 = dr.r5;
        slot = (s32)dr.r6;
    }

    /* --- Loop 2: first set of extra NCPs, index 0→0x30 --- */
    u32 extra_area_1 = get_navcust_extra_area_1();
    u32 i = 0;
    for (; i < NAVICUST_EXTRA_COUNT; i++) {
        u8 ncp_id = LD8(extra_area_1 + i);
        if (ncp_id == 0) continue;

        u32 entry = get_ncp_entry_ptr(ncp_id - 1);
        u16 ncp_code = LD16(entry);
        if (ncp_code == 0) continue;

        NcpDispatchResult dr = ncp_dispatch(ncp_code, 0, 0,
                                            (u32)ncp_code, r5, i, extra_area_1);
        r5 = dr.r5;
        i = dr.r6;
    }

    /* --- Loop 3: second set of extra NCPs, index 0→0x30 --- */
    u32 extra_area_2 = get_navcust_extra_area_2();
    u32 k = 0;
    for (; k < NAVICUST_EXTRA_COUNT; k++) {
        u8 ncp_id = LD8(extra_area_2 + k);
        if (ncp_id == 0) continue;

        u32 entry = get_ncp_entry_ptr(ncp_id - 1);
        u16 ncp_code = LD16(entry);
        if (ncp_code == 0) continue;

        NcpDispatchResult dr = ncp_dispatch(ncp_code, 0, 0,
                                            (u32)ncp_code, r5, k, extra_area_2);
        r5 = dr.r5;
        k = dr.r6;
    }

    /* Finalise: update petNavi stats and run post-processing */
    petnavi_set_stat(0, k, extra_area_2);
    navicust_post_process(0, r5, k, extra_area_2);
}

