/* sub_8134610 — menu cursor box update (bn6f asm36.s:8737)
 *
 * r5 points at a menu object.  With its "visible" byte (+0x44) clear nothing
 * happens at all.  Otherwise the function
 *
 *   1. queues one draw of the blinking selection box with the box renderer
 *      (sub_811FAF4):
 *         X = cursorBase[screen] - (s16)[obj+0x18] * 8   (packed in the high half)
 *         slot = [obj+0x3E] + [obj+0x3C] - (screen == 2 ? [obj+0x2E] : [obj+0x24])
 *         the draw only happens while slot is 0..6, Y = 0x20 + slot * 16
 *         low half = Y; the box size is 0x20003 and the blink byte's low
 *         nibble is passed as the style with flag bit 31 set;
 *   2. ticks the blink byte at +0x16: its high nibble counts blink steps
 *      down, and on the last step sub_8120CC8 reads the next blink entry out
 *      of the dword_81331FC table (its r0 becomes the byte value, its r1 the
 *      new high nibble).
 *
 * Behaviour notes taken from the machine code: the prologue `adds r0, #0`
 * zeroes C and V before the tst, so the idle exit always reports C=V=0 and
 * Z set; r1..r3 come out untouched on the idle path; r4 is used as scratch
 * but the push/pop in the original always restores it; r0 keeps the full
 * 32-bit orr result even though only its low byte reaches memory.
 */

/* field offsets inside the cursor object (indexed from r5, as in the disassembly) */
#define oMenu_Visible  0x44  /* u8: box active                                      */
#define oMenu_Screen   0x40  /* u32: menu screen (folder pages, 2 = custom screen)  */
#define oMenu_Scroll   0x18  /* s16: scroll offset, 8 screen pixels per unit        */
#define oMenu_SlotX    0x3E  /* u16: slot position, added to the row component      */
#define oMenu_SlotY    0x3C  /* u16: slot position, added to the column component   */
#define oMenu_Bound2   0x2E  /* u16: slot bound while screen == 2                   */
#define oMenu_Bound1   0x24  /* u16: slot bound otherwise                           */
#define oMenu_Blink    0x16  /* u8: high nibble = blink steps left, low = phase     */

struct cursor_update_result {
    u32 r0, r1, r2, r3, r4;  /* guest r0..r4 on return                        */
    u32 nz;                  /* N = bit31(value), Z = (value == 0)            */
    bool c, v;               /* carry / overflow on return                    */
};

struct blink_entry {         /* what sub_8120CC8 leaves behind on return      */
    u32 byte_value;          /* r0: new value stored to [obj+0x16]            */
    u32 high_nibble;         /* r1: value shifted into the byte's high nibble */
    u32 r3;                  /* r3: survives untouched to the function's end  */
    bool v;                  /* V as left by the call (nothing overwrites it) */
};

/* Signed-overflow flag (V) of `a - b == result`, as SUBS/CMP would set it. */
static bool sub_overflows(u32 a, u32 b, u32 result) {
    return (s32)((a ^ b) & (a ^ result)) < 0;
}

/* register form: calls sub_811FAF4 outside this file, which has no typed C interface yet */
static u32 queue_box_draw(u32 pos, u32 size, u32 style, u32 templates, u32 mode) {
    R0 = pos;          /* box position: X << 16 | Y */
    R1 = size;         /* 0x20003: box dimensions for the renderer */
    R2 = style;        /* blink phase nibble with flag bit 31 set */
    R3 = templates;    /* &byte_81331F4: box template table */
    R4 = mode;         /* 0x40000000: renderer mode bits */
    GUEST_CALL(sub_811FAF4);
    return R3;         /* r3 as the call left it — the guest's final r3 unless
                        * fetch_blink_entry runs afterwards and replaces it */
}

/* register form: calls sub_8120CC8 outside this file, which has no typed C interface yet */
static struct blink_entry fetch_blink_entry(u32 table) {
    struct blink_entry e;
    R1 = table;        /* &dword_81331FC; r0/r2/r3 stay exactly as sub_811FAF4
                        * left them, matching the leftover registers the
                        * original call passes on */
    GUEST_CALL(sub_8120CC8);
    e.byte_value = R0;
    e.high_nibble = R1;
    e.r3 = R3;
    e.v = (bool)OVERFLOW_FLAG();
    return e;
}

static struct cursor_update_result run_cursor_update(u32 obj, u32 entryR1, u32 entryR2,
                                                     u32 entryR3, u32 entryR4) {
    struct cursor_update_result out;

    u32 visible = LD8(obj + oMenu_Visible);
    if (visible == 0) {
        /* Idle object, straight out of the tst.  C and V are clear because
         * the `adds r0, #0` before the tst always zeroes both. */
        out.r0 = visible;
        out.r1 = entryR1;
        out.r2 = entryR2;
        out.r3 = entryR3;
        out.r4 = entryR4;
        out.nz = visible;
        out.c = false;
        out.v = false;
        return out;
    }

    /* Box X position: per-screen table value minus the scroll offset scaled
     * by 8.  The Y half is filled in once the slot is known to be in range. */
    u32 screen = LD32(obj + oMenu_Screen);
    u32 x_base = LD32(A_byte_813470C + screen * 4);
    u32 x_off = (u32)(s16)LD16(obj + oMenu_Scroll) << 3;
    u32 box_pos = (x_base - x_off) << 16;

    /* The box is drawn only while the summed slot position is 0..6; screen 2
     * compares against a different bound field. */
    u32 slot_pos = (u16)LD16(obj + oMenu_SlotX) + (u16)LD16(obj + oMenu_SlotY);
    u32 bound = (screen == 2) ? (u16)LD16(obj + oMenu_Bound2) : (u16)LD16(obj + oMenu_Bound1);
    s32 slot = (s32)slot_pos - (s32)bound;

    if (slot < 0) {
        /* the `subs slot_pos, bound` that failed is the last flag-setting op */
        out.r0 = box_pos;
        out.r1 = 0x20;
        out.r2 = (u32)slot;
        out.r3 = screen;
        out.r4 = entryR4;
        out.nz = (u32)slot;
        out.c = slot_pos >= bound;   /* carry = no borrow */
        out.v = sub_overflows(slot_pos, bound, (u32)slot);
        return out;
    }
    if (slot > 6) {
        /* the `cmp slot, #6` that failed is the last flag-setting op */
        u32 diff = (u32)slot - 6;
        out.r0 = box_pos;
        out.r1 = 0x20;
        out.r2 = (u32)slot;
        out.r3 = screen;
        out.r4 = entryR4;
        out.nz = diff;
        out.c = true;                /* slot > 6, never a borrow */
        out.v = sub_overflows((u32)slot, 6, diff);
        return out;
    }

    u32 blink = LD8(obj + oMenu_Blink);
    u32 r3_after_draw = queue_box_draw(
        box_pos | (0x20 + (u32)slot * 0x10),   /* X << 16 | Y */
        0x20003u,
        (blink & 0xF) | 0x80000000u,           /* blink phase in the low nibble */
        A_byte_81331F4,
        0x40000000u);

    /* Tick the blink state: the high nibble of +0x16 counts down to 1, and on
     * the last step the next blink value comes out of the table. */
    u32 steps = blink >> 4;
    u32 shifted;    /* value the `lsl #4` moves into the high nibble */
    bool vflag;
    u32 finalR3;

    if (steps == 1) {
        struct blink_entry next = fetch_blink_entry(A_dword_81331FC);
        ST8(obj + oMenu_Blink, next.byte_value);
        shifted = next.high_nibble;
        vflag = next.v;
        finalR3 = next.r3;
    } else {
        shifted = steps - 1;
        vflag = sub_overflows(steps, 1, shifted);
        finalR3 = r3_after_draw;
    }

    /* Rebuild the byte: low nibble stays, high nibble takes the shifted value. */
    u32 new_byte = (LD8(obj + oMenu_Blink) & 0xF) | (shifted << 4);
    ST8(obj + oMenu_Blink, new_byte);

    /* N/Z come from the orr (its full 32-bit result stays in r0), C from the
     * lsl that built the high nibble, and V from the step decrement (or, if
     * the blink entry was fetched, from that call). */
    out.r0 = new_byte;
    out.r1 = shifted << 4;
    out.r2 = 0xF;
    out.r3 = finalR3;
    out.r4 = entryR4;
    out.nz = new_byte;
    out.c = ((shifted >> 28) & 1) != 0;
    out.v = vflag;
    return out;
}

Next sub_8134610(void) {
    struct cursor_update_result out = run_cursor_update(R5, R1, R2, R3, R4);
    R0 = out.r0, R1 = out.r1, R2 = out.r2, R3 = out.r3, R4 = out.r4;
    SET_FLAGS_NZ(out.nz);   /* cpu.nz keeps N/Z as the value that produced them */
    SET_FLAGS_C(out.c);
    SET_FLAGS_V(out.v);
    RETURN_TO_CALLER();
}

