             call_battle_findPlayer(LD8(self + oBattleObject_Alliance) ^ 1u));
        ST32(attackVars + oAIAttackVars_Unk_30, LD32(self + oBattleObject_ExtraVars + 4));
        call_object_setAttack4(9);
