/* Process one NCP slot in the primary (duplicate-checked) loop.
 * Returns true if the slot should skip the dispatch (empty, null id, or duplicate). */
static bool ncp_slot_skip(u32 workarea, s32 slot, u32 *ncp_id_out, u32 *func_ptr_out,
                          u32 *jt_off_out, u32 *r2_out, u32 *r3_out) {
    u32 prog_id = LD8(workarea + (u32)slot);
    if (prog_id == 0) return true;

    u32 entry = toolkit_get_entry_ptr(prog_id - 1);
    u32 ncp_id = LD16(entry);
