        /* No duplicate: r2 ends at NCP_DUP_SIZE, r3 = last byte read (index 7, always 0) */
        *r2_out = NCP_DUP_SIZE;
        *r3_out = LD8(NCP_DUP_ARRAY_ADDR + 7);
