/* Main logic: apply all equipped NavCust Programs to the pet navi. */
static void apply_navicust_programs(void) {
    /* Clear the 8-byte duplicate-detection scratch array */
    zero_fill_ncp_dup_array();

    /* --- Phase 1: primary 7 nav-cust slots with duplicate suppression --- */
    u32 workarea = get_ncp_primary_workarea();
    for (s32 slot = NCP_PRIMARY_SLOTS - 1; slot >= 0; slot--) {
        u32 ncp_id, func_ptr, jt_off, r2_val, r3_val;
        if (ncp_slot_skip(workarea, slot, &ncp_id, &func_ptr, &jt_off, &r2_val, &r3_val))
            continue;
        ncp_dispatch_primary(func_ptr, jt_off, ncp_id, r2_val, r3_val, slot, workarea);
    }

    /* --- Phase 2: first extended slot set (up to 0x31 entries) --- */
    u32 ncp_id_ext = 0, jt_off_ext = 0;
    workarea = get_ncp_ext_workarea();
    for (u32 slot = 0; slot < NCP_EXT_SLOTS; slot++) {
        u32 func_ptr, r3_val;
        if (ncp_slot_skip_ext(workarea, slot, &ncp_id_ext, &func_ptr, &jt_off_ext, &r3_val))
            continue;
        ncp_dispatch_extended(func_ptr, jt_off_ext, ncp_id_ext, r3_val, slot, workarea);
    }

    /* --- Phase 3: second extended slot set --- */
    workarea = get_ncp_extra_workarea();
    for (u32 slot = 0; slot < NCP_EXT_SLOTS; slot++) {
        u32 func_ptr, r3_val;
        if (ncp_slot_skip_ext(workarea, slot, &ncp_id_ext, &func_ptr, &jt_off_ext, &r3_val))
            continue;
        ncp_dispatch_extended(func_ptr, jt_off_ext, ncp_id_ext, r3_val, slot, workarea);
    }

    /* --- Finalize: update pet-navi stats and run post-application logic --- */
    petnavi_apply_stat_update(ncp_id_ext, (s32)NCP_EXT_SLOTS, workarea);
    finalize_navicust_apply();
}

