             battle_find_player(LD8(battle_obj + oBattleObject_Alliance) ^ 1));
        ST32(attack_vars + oAIAttackVars_Unk_30,
             LD32(battle_obj + oBattleObject_ExtraVars + 4));
        object_set_attack4(9);
        return;
