    /* Sub-state < 3: advance it, pick between attacks 0xc and 0xa by RNG */
    ST8(ai_state + oAIState_Unk_05, sub_state + 1);
    ST8(attack_vars + oAIAttackVars_Unk_03, get_ai_difficulty_tier());

