/* Repack a helper's footprint into the function's exit state: callers see
 * r0-r3 straight from the helper, the entry width limit back in r4, and the
 * helper's N/Z flags (nzcased as a value; C/V are already as the callee
 * left them). */
static LaneStepExit exit_from_helper(CalleeFootprint via, u32 width_limit)
{
    LaneStepExit out;
    out.r0 = via.r0;
    out.r1 = via.r1;
    out.r2 = via.r2;
    out.r3 = via.r3;
    out.r4 = width_limit;
    out.nz_value = via.z ? 0 : (via.n ? 0x80000000u : 1u);
    return out;
}

static LaneStepExit tick_lane_step(u32 coord_field, u32 origin_x, u32 origin_y,
                                   u32 lane, u32 width_limit, u32 state, u32 slot)
{
    u32 pending_mask = LD32(A_byte_8134994 + lane * 4);   /* lane bit of the flags word */
    u32 move_flags   = LD32(state + 0x4C);

    if ((move_flags & pending_mask) == 0) {
        /* Lane idle: the original falls straight out of the tst, leaving
         * the mask in r0, the flags word in r1, lane<<2 in r2 and the lane
         * number in r3, with NZ from the tst. */
        LaneStepExit idle = { pending_mask, move_flags, lane * 4, lane,
                              width_limit, move_flags & pending_mask };
        return idle;
    }

    u32 lane_field  = LD32(A_off_81349A0 + lane * 4);     /* 0x5C for lane 0, 0x60 for lane 1 */
    u32 step_target = LD32(state + lane_field);           /* coordinate this slide runs to */
    u32 coord_now   = LD16(state + coord_field);          /* current coordinate for this lane */
    s32 travelled   = (s32)(step_target - coord_now);     /* how far the step has come */
    s32 dir_shift   = (s32)(s16)LD16(state + 0x18);       /* facing: shifts x by dir*8 */

    if (travelled < 0) {
        /* Slid backwards: keep the step queued. */
        return exit_from_helper(
            call_81171F4(1, slot, (u32)travelled, coord_now, lane), width_limit);
    }
    if (travelled > (s32)width_limit) {
        /* Step too wide for one go: keep the step queued. */
        return exit_from_helper(
            call_81171F4(1, slot, (u32)travelled, width_limit, lane), width_limit);
    }

    /* In range: draw the sprite at its position for this step... */
    CalleeFootprint placed = call_81171D4(origin_x - ((u32)dir_shift << 3),
                                          origin_y + ((u32)travelled << 4),
                                          slot, coord_now, lane);
    /* ...then clear the lane's pending bit now that the step is placed.
     * sub_81171D4 leaves r2/r3 behind and the final call sees them, so
     * hand those along exactly as the original does. */
    return exit_from_helper(
        call_81171F4(0, slot, placed.r2, placed.r3, lane), width_limit);
}

