    LaneStepExit res = tick_lane_step(R0, R1, R2, R3, R4, R5, R7);
    R0 = res.r0;
    R1 = res.r1;
    R2 = res.r2;
    R3 = res.r3;
    R4 = res.r4;
    SET_FLAGS_NZ(res.nz_value);
    RETURN_TO_CALLER();
}

