        u32 piece_id = LD16(toolkit_ncp_entry_ptr(piece - 1));
        last_piece_id = piece_id;
        if (piece_id == 0)
            continue;
        run_ncp_handler(piece_id, slot, extra_area_1);
    }

    /* Second extra work area: same, unconditionally. */
    u32 extra_area_2 = get_second_extra_area_ptr();
    for (u32 slot = 0; slot < 0x31; slot++) {
        u32 piece = LD8(extra_area_2 + slot);
        if (piece == 0)
            continue;
        u32 piece_id = LD16(toolkit_ncp_entry_ptr(piece - 1));
        last_piece_id = piece_id;
        if (piece_id == 0)
            continue;
        run_ncp_handler(piece_id, slot, extra_area_2);
    }

    refresh_pet_ncp_stats(last_piece_id, extra_area_2);
