     * "lsl r2, slot, #2", i.e. bit 30 of the slot — clear for the two valid
     * slots.  ADDS x,0 reproduces exactly that (N/Z from x, carry clear); it
     * clears V where tst would preserve it, which only differs when the
     * caller happens to enter with V set. */
    SET_FLAGS_ADD(flagWord & liveBit, 0);
    return liveBit;  /* r0 = the live-bit word that was loaded for the test */
