 * (the calibration callee's own r0, or the tested live bit). */
static u32 refresh_item_cell(u32 destField, u32 coord, u32 firstTile, u32 slot,
                             u32 rowLimit, u32 obj, u32 handle)
{
    u32 flagWord = LD32(obj + 0x4C);
    u32 liveBit  = LD32(ITEM_LIVE_BIT_TABLE + slot * 4);

    /* Slot not live (bit 0x20/0x40 clear in the +0x4C word): nothing to do. */
    if ((flagWord & liveBit) == 0)
        return skip_item_refresh(flagWord, liveBit, slot);

    /* Screen x of the item: caller's coordinate minus its scroll offset
     * (signed halfword at +0x18) counted in 8-pixel steps. */
    u32 x = coord - ((u32)(((s16)LD16(obj + 0x18)) << 3));

    /* How far the item still has to travel: its current position (word field
     * 0x5C/0x60 per slot) minus the destination (u16 field named by r0). */
    u32 current = LD32(obj + LD32(ITEM_CUR_FIELD_TABLE + slot * 4));
    u32 destination = (u32)LD16(obj + destField);
    s32 travel = (s32)(current - destination);

    if (travel < 0 || travel > (s32)rowLimit)
        /* The item has run past its column: clear the cell and report it. */
        return report_item_change(1, handle, (u32)travel, destination, false);

    /* Still inside the row: draw the cell at the reached tile. */
    blit_item_cell(x, firstTile + ((u32)travel << 4), handle, destination);

    /* r2/r3 at this point are whatever the blit left behind, exactly as in
     * the original before it calls sub_81171F4; do not touch them. */
    return report_item_change(0, handle, 0, 0, true);
}

