static void ai_select_attack(u32 battle_obj, u32 ai_state, u32 attack_vars) {
    u32 warmup = LD8(ai_state + oAIState_Unk_04);

    if (warmup >= 2) {
        /* Active phase: reset warmup, pick a pattern */
        ST8(ai_state + oAIState_Unk_04, 0);
        u32 pattern = LD8(ai_state + oAIState_Unk_05);

        if (pattern < 3) {
            /* Advance pattern index and roll RNG to choose attack vs defend */
            ST8(ai_state + oAIState_Unk_05, pattern + 1);
            u32 roll = get_positive_rng() & 0xF;

            if (roll >= 6) {
                /* Direct-attack pattern */
                ST8(attack_vars + oAIAttackVars_Unk_03, get_ai_difficulty_tier());
                ST16(attack_vars + oAIAttackVars_Unk_18, calc_direct_attack_power());
                set_attack_0(0xC);
            } else {
                /* Defend pattern */
                ST8(attack_vars + oAIAttackVars_Unk_03, get_ai_difficulty_tier());
                ST8(attack_vars + oAIAttackVars_Unk_02, 1);
                sub_80FDFE4_wrapper(0);
                ST16(attack_vars + oAIAttackVars_Unk_18, calc_defend_attack_power());
                ST16(attack_vars + oAIAttackVars_Unk_0c, calc_defend_extra());
                u32 ally = LD8(battle_obj + oBattleObject_Alliance);
                ST32(attack_vars + oAIAttackVars_Unk_2c, find_opposing_player(ally ^ 1));
                set_attack_0(0xA);
            }
        } else {
            /* Pattern cycle complete: reset index, use ranged pattern */
            ST8(ai_state + oAIState_Unk_05, 0);
            ST8(attack_vars + oAIAttackVars_Unk_03, get_ai_difficulty_tier());
            ST8(attack_vars + oAIAttackVars_Unk_02, 2);
            ST16(attack_vars + oAIAttackVars_Unk_18, calc_ranged_attack_power());
            ST8(attack_vars + oAIAttackVars_Unk_0c, calc_ranged_extra());
            sub_80FDFE4_wrapper(1);
            set_attack_0(0xB);
        }
    } else {
        /* Warmup phase: increment counter and prepare setup attack (type 9) */
        ST8(ai_state + oAIState_Unk_04, warmup + 1);
        ST8(attack_vars + oAIAttackVars_Unk_03, get_ai_difficulty_tier());
        ST32(attack_vars + oAIAttackVars_Unk_28, (A_sub_80FE4D0 | 1));
        ST16(attack_vars + oAIAttackVars_Unk_18, calc_warmup_attack_power());
        u32 ally = LD8(battle_obj + oBattleObject_Alliance);
        ST32(attack_vars + oAIAttackVars_Unk_2c, find_opposing_player(ally ^ 1));
        ST32(attack_vars + oAIAttackVars_Unk_30,
             LD32(battle_obj + oBattleObject_ExtraVars + 4));
        set_attack_4(9);
    }
}

