/* Difference between the tracked value and the window start decides hide vs reposition. */
static RegResult refresh_entry_row_sprite(u32 ctx, u32 windowOffset, u32 xBase,
                                          u32 rowBase, u32 slot, u32 limit,
                                          u32 liveR6, u32 objId) {
    u32 enableMask = LD32(A_byte_8134994 + (slot << 2));   /* 0x20 / 0x40 per slot */
    u32 enableBits = LD32(ctx + 0x4C);

    if ((enableBits & enableMask) == 0) {
        /* Slot switched off: nothing to move, nothing to hide. Same registers left
         * behind as the original (r0 mask, r1 flags, r2 slot*4, r3 slot) and the
         * same flags the tst left (Z=1, N=0). */
        RegResult res = { enableMask, enableBits, slot << 2, slot, 0u };
        return res;
