    u32 xPos = xBase - ((u32)(s16)LD16(ctx + 0x18) << 3);  /* scroll-scaled screen x */
    u32 tracked = LD32(ctx + LD32(A_off_81349A0 + (slot << 2))); /* +0x5C / +0x60 */
    u32 windowStart = LD16(ctx + windowOffset);
    s32 delta = (s32)(tracked - windowStart);

    if (delta < 0)
        return call_set_object_shown(1, objId, (u32)delta, windowStart,
                                     slot, ctx, liveR6, objId);
    if (delta > (s32)limit)
        return call_set_object_shown(1, objId, (u32)delta, limit,
                                     slot, ctx, liveR6, objId);

    /* In range: repaint the row at its slot, then leave it shown. */
    RegResult moved = call_set_object_frame_pos(xPos, rowBase + ((u32)delta << 4), objId,
                                                limit, slot, ctx, liveR6, objId);
    return call_set_object_shown(0, objId, moved.r2, moved.r3,
                                 slot, ctx, liveR6, objId);
}

