 * terminal select_attack_by_idN / GUEST_CALL in each branch. */
static void ai_attack_state_advance(u32 battle_obj, u32 ai_state, u32 attack_vars) {
    u32 phase = LD8(ai_state + oAIState_Unk_04);

    if (phase < 2) {
        /* Warmup: increment the countdown, prepare default attack slot and
         * register a continuation callback so the object re-enters this logic. */
        ST8(ai_state + oAIState_Unk_04, phase + 1);
        ST8(attack_vars + oAIAttackVars_Unk_03, get_ai_difficulty_tier());
        ST32(attack_vars + oAIAttackVars_Unk_28, (A_sub_80FE4D0 | 1));
        ST16(attack_vars + oAIAttackVars_Unk_18, calc_warmup_attack_range());

        u32 alliance = (LD8(battle_obj + oBattleObject_Alliance) ^ 1) & 0xFF;
        ST32(attack_vars + oAIAttackVars_Unk_2c, find_opposing_player(alliance));
        ST32(attack_vars + oAIAttackVars_Unk_30,
             LD32(battle_obj + oBattleObject_ExtraVars + 4));
        select_attack_by_id4(9);
        return;
    }

    /* Active cycle: reset main phase, inspect sub-phase to choose attack style. */
    ST8(ai_state + oAIState_Unk_04, 0);
    u32 sub_phase = LD8(ai_state + oAIState_Unk_05);

    if (sub_phase < 3) {
        /* Sub-phases 0..2: advance counter, roll RNG for special vs normal. */
        ST8(ai_state + oAIState_Unk_05, sub_phase + 1);
        u32 rng = get_positive_signed_rng() & 0xF;
        ST8(attack_vars + oAIAttackVars_Unk_03, get_ai_difficulty_tier());

        if (rng >= 6) {
            /* Special attack (rare, ~62.5% chance → 10/16) */
            ST16(attack_vars + oAIAttackVars_Unk_18, calc_special_attack_range());
            select_attack_by_id0(0xC);
            return;
