        /* Normal attack: mode 0, single-target toward opposing player. */
        ST8(attack_vars + oAIAttackVars_Unk_02, 1);
        set_attack_targeting_mode(0);
        ST16(attack_vars + oAIAttackVars_Unk_18, calc_normal_attack_range());
        ST16(attack_vars + oAIAttackVars_Unk_0c, calc_normal_attack_speed());

        u32 alliance = (LD8(battle_obj + oBattleObject_Alliance) ^ 1) & 0xFF;
        ST32(attack_vars + oAIAttackVars_Unk_2c, find_opposing_player(alliance));
        select_attack_by_id0(0xA);
        return;
    }

    /* Sub-phase 3+: charged/alternate attack, reset sub-phase counter. */
    ST8(ai_state + oAIState_Unk_05, 0);
    ST8(attack_vars + oAIAttackVars_Unk_03, get_ai_difficulty_tier());
    ST8(attack_vars + oAIAttackVars_Unk_02, 2);
    ST16(attack_vars + oAIAttackVars_Unk_18, calc_charged_attack_range());
    ST8(attack_vars + oAIAttackVars_Unk_0c, calc_charged_attack_speed());
    set_attack_targeting_mode(1);
    select_attack_by_id0(0xB);
}

