    R1 = size;
    GUEST_CALL(ZeroFillByEightWords);
}

/* Build a 30-entry item/count lookup table at unk_20343E0 from the first `num_entries`
 * records at word_202A020, then pack each found count back into the record's +0x14 field.
 * Returns the number of non-empty records processed. */
static u32 build_item_count_table(u32 num_entries) {
    u32 table = A_unk_20343E0;
    u32 source = A_word_202A020;
    u32 source_end = source + num_entries * 0x20;

    /* Zero the 120-byte table (30 entries of {u16 item_id, u16 count}) */
    zero_fill_eight_words(table, 0x78);

    u32 item_count = 0;

    /* Pass 1: tally item IDs from source records into the table */
    for (u32 entry = source; (s32)entry < (s32)source_end; entry += 0x20) {
        u16 item_id = LD16(entry);
        if (item_id == 0)
            continue;

        item_count++;

        /* Find existing entry for this item, or first empty slot */
        u32 pos = 0;
        u16 tbl_item;
        for (;;) {
            tbl_item = LD16(table + pos);
            if (tbl_item == 0 || tbl_item == item_id)
                break;
            pos += 4;
        }

        if (tbl_item == item_id) {
            /* Match: increment the count field at +2 */
            ST16(table + pos + 2, LD16(table + pos + 2) + 1);
        } else {
            /* Empty slot: store new item_id and count = 1 */
            ST16(table + pos, item_id);
            ST16(table + pos + 2, 1);
        }
    }

    /* Pass 2: pack the count from the table into each source record's +0x14 u32 field
     *         as (count << 16) | original_low16 */
    for (u32 entry = source; (s32)entry < (s32)source_end; entry += 0x20) {
        u16 sub_item = LD16(entry + 0x14);
        if (sub_item == 0)
            continue;

        u32 pos = 0;
        u16 tbl_item;
        for (;;) {
            tbl_item = LD16(table + pos);
            if (tbl_item == 0 || tbl_item == sub_item)
                break;
            pos += 4;
        }

        u16 count = LD16(table + pos + 2);
        u32 packed = ((u32)count << 16) | (LD32(entry + 0x14) & 0xFFFF);
        ST32(entry + 0x14, packed);
    }

    return item_count;
}

/* sub_8134EA8(r0 = num_source_records) -> r0 = non-empty record count */
Next sub_8134EA8(void) {
    R0 = build_item_count_table(R0);
    SET_FLAGS_NZ(R0);
    RETURN_TO_CALLER();
}

#define MSGBOX_MODE_OFF      0x1D2
#define MSGBOX_TABLE_ENTRY   0x08040FC4
#define MSGBOX_JUMP_TABLE    A_chatbox_EB_msgboxJumpTable
#define MSGBOX_ADVANCE_TABLE A_byte_804102C
#define MSGBOX_CURSOR_TABLE  A_byte_8045DCC

struct MsgboxOut {
    u32 r0;      /* final R0: callee result (0-path) or advance table address */
    u32 r1;      /* final R1: callee result or advance amount */
    u32 r4;      /* final R4: possibly advanced past message entry */
    u32 flag_a;  /* ADDS operand a (r4_before for advance, 0 for Z-flag path) */
    u32 flag_b;  /* ADDS operand b */
};

/* register form: dispatch through the E8 msgbox jump table and post-call
 * pointer advance.  The target handler is one of four known functions
 * selected by the type byte's repeating 4-cycle (types 16-17 map to 2-3).
 * GUEST_CALL clobbers the live register file; the callee's own push/pop
 * and bx LR are handled by the emulated call/return. */
static MsgboxOut dispatch_msgbox(u32 type) {
    MsgboxOut out;
    R0 = MSGBOX_JUMP_TABLE;
    R1 = type << 2;
    R2 = MSGBOX_MODE_OFF;
    LR = MSGBOX_TABLE_ENTRY;

    u32 group = (type < 16) ? (type & 3) : (type - 14);
    switch (group) {
        case 0: GUEST_CALL(chatbox_804103E);             break;
        case 1: GUEST_CALL(chatbox_8041090);             break;
        case 2: GUEST_CALL(chatbox_closeAndReset_80410F8); break;
        case 3: GUEST_CALL(chatbox_804110C);             break;
    }

    if (R0 != 0) {
        /* advance the message data pointer by the entry size for this type */
        u32 cur_type = LD8(R4 + 1);
        u32 advance  = LD8(MSGBOX_ADVANCE_TABLE + cur_type);
        out.r0 = MSGBOX_ADVANCE_TABLE;
        out.r1 = advance;
        out.r4 = R4 + advance;
        out.flag_a = R4;
        out.flag_b = advance;
    } else {
        /* callee returned zero: pass through its registers, Z-flag set */
        out.r0 = 0;
        out.r1 = R1;
        out.r4 = R4;
        out.flag_a = 0;
        out.flag_b = 0;
    }
    return out;
}

/* Process one chatbox / message-box command entry.
 * Writes the display mode (and cursor coordinates for types 4-7) into the
 * properties buffer, then dispatches to the type-specific handler. */
static MsgboxOut chatbox_msgbox_process(u32 data, u32 props) {
    u32 type = LD8(data + 1);
    u32 mode_off = props + MSGBOX_MODE_OFF;

    if (type >= 0x10) {
        ST8(mode_off, 6);
    } else if (type >= 0xC) {
        ST8(mode_off, 5);
    } else if (type >= 8) {
        ST8(mode_off, 4);
    } else if (type <= 3) {
        ST8(mode_off, 0);
    } else {
        /* types 4-7: read the explicit mode from the message, then
         * look up cursor coordinates when the sub-type is valid */
        ST8(mode_off, LD8(data + 2));

        u32 sub = LD8(data + 3);
        if (sub != 0xFF) {
            u32 entry = MSGBOX_CURSOR_TABLE + (sub << 2);
            ST8(props + oChatbox_CursorIdx, LD16(entry));
            ST8(props + oChatbox_Unk_1B,    LD16(entry + 2));
        }
    }

    return dispatch_msgbox(type);
}

/* chatbox_E8_msgbox(r4 = msg data, r5 = ChatBoxProperties, …) */
Next chatbox_E8_msgbox(void) {
    MsgboxOut out = chatbox_msgbox_process(R4, R5);
    R0 = out.r0;
    R1 = out.r1;
    R4 = out.r4;
    SET_FLAGS_ADD(out.flag_a, out.flag_b);
    RETURN_TO_CALLER();
}

