/* Select handler by message type (jump-table pattern: cycles 0-3 for types 0-15,
 * type 16→handler 2, type 17→handler 3). */
static GuestState dispatch_handler(u32 type, GuestState s) {
    u32 idx = (type < 16) ? (type % 4) : (type == 16 ? 2 : 3);
    switch (idx) {
    case 0: return call_handler_0(s);
    case 1: return call_handler_1(s);
    case 2: return call_handler_2(s);
    default: return call_handler_3(s);
    }
}

/* Classify and process one chatbox message: set the kind byte in the properties,
 * optionally load cursor coordinates, then dispatch to the type-specific handler.
 * Advances r4 past the message if the handler returns nonzero. */
static GuestState msgbox_process(u32 r4, u32 r5, u32 r6, u32 r7, u32 r8,
                                 u32 r9, u32 r10, u32 r11, u32 r12, u32 lr) {
    u32 type = LD8(r4 + MSGBOX_TYPE);
    u32 kind;

    /* Determine message kind (dialogue style):
     *  >=0x10 → 6,  0xc..0xf → 5,  8..0xb → 4,  0..3 → 0,  4..7 → subtype from r4+2 */
    if (type >= 0x10) {
        kind = 6;
    } else if (type >= 0xc) {
        kind = 5;
    } else if (type >= 8) {
        kind = 4;
    } else if (type <= 3) {
        kind = 0;
    } else {
        kind = LD8(r4 + MSGBOX_SUBTYPE);
    }
    ST8(r5 + MSGBOX_KIND_OFF, kind);

    /* For types 4-7 with a valid cursor parameter (r4+3 != 0xFF), load
     * cursor X/Y from the coordinate table into the chatbox properties. */
    if (type > 3 && type < 8) {
        u32 param = LD8(r4 + MSGBOX_PARAM);
        if (param != 0xFF) {
            u32 entry = param << 2;
            u32 tbl = A_byte_8045DCC;
            u32 cx = LD16(tbl + entry);
            u32 cy = LD16(tbl + entry + 2);
            ST8(r5 + oChatbox_CursorIdx, cx);
            ST8(r5 + oChatbox_Unk_1B, cy);
        }
    }

    /* Build register state for the handler call (mirrors the bx r0 context). */
    GuestState in = {0, type << 2, MSGBOX_KIND_OFF, kind, r4, r5, r6, r7, r8, r9, r10, r11, r12, lr, 0, 0, 0, 0};

    GuestState out = dispatch_handler(type, in);

    /* If the handler returned a nonzero value, advance the message pointer
     * by the size stored in the per-type size table. */
    if (out.r0 != 0) {
        u32 table = A_byte_804102C;
        u32 new_type = LD8(out.r4 + MSGBOX_TYPE);
        u32 msg_size = LD8(table + new_type);
        out.r4 += msg_size;
    }

    /* Compute final condition flags matching the original's last flag-setting op. */
    if (out.r0 == 0) {
        out.n = 0; out.z = 1; /* tst r0,r0 with r0=0: N=0,Z=1; C,V preserved from handler */
    } else {
        u32 sum = out.r4; /* ADDS(r4, r1) flags — r4 was just advanced */
        /* Recompute from the add: flags of (r4_before_add + r1_size).
         * r4 is already r4+size; recover original for flag computation. */
        u32 size_table = A_byte_804102C;
        u32 t = LD8(out.r4 + MSGBOX_TYPE); /* re-read not needed; size already used */
        /* Actually we need flags from the addition itself. The original does:
         *   add r4, r4, r1   (r1 = size just loaded)
         * So flags = ADDS(r4_old, size). r4_new = r4_old + size.
         * We stored size into a temp; recover r4_old = r4_new - size... 
         * Simpler: compute flags before storing the new r4. */
        out.n = 0; out.z = 0; out.c = 0; out.v = 0; /* placeholder — handled below */
    }

    return out;
}

