/* Dispatch the per-message-type handler selected by the jump table. */
static u32 dispatch_handler(u32 msg_type, u32 r2, u32 r3) {
    u32 handler = msg_type & 3;
    if (msg_type == 16) handler = 2;
    if (msg_type == 17) handler = 3;
    switch (handler) {
        case 0:  return call_handler_03E(r2, r3);
        case 1:  return call_handler_090(r2, r3);
        case 2:  return call_handler_0F8(r2, r3);
        default: return call_handler_10C(r2, r3);
    }
}

/* Set the chatbox display state byte and, for inline-text types, the cursor coordinates. */
static void configure_msgbox(u32 chatbox, u32 data_ptr, u32 msg_type, u32 sub_type) {
    ST8(chatbox + MSGBOX_STATE_OFFSET, kBoxStateMap[msg_type]);

    if (sub_type != 0xFF) {
        u32 coord_entry = A_byte_8045DCC + (sub_type << 2);
        ST8(chatbox + oChatbox_CursorIdx, (u32)LD16(coord_entry));
        ST8(chatbox + oChatbox_Unk_1B, (u32)LD16(coord_entry + 2));
    }
}

/* Advance the message pointer past the current command.
 * Returns 0 if no advance occurs (caller skips it), or the new r4. */
static u32 advance_msg_ptr(u32 data_ptr, u32 handler_ret) {
    if (handler_ret == 0)
        return 0;

    u32 type = LD8(data_ptr + 1);
    if (type & MSG_TYPE_MASK)
        return type;

    u32 cmd_len = (u32)LD8(A_byte_804102C + type);
    return data_ptr + cmd_len;
}

/* Process one chat message-box command: set display state, call the type-specific
 * handler, and advance the message pointer if the handler signals completion. */
static u32 process_msgbox_command(u32 data_ptr, u32 chatbox) {
    u32 msg_type = LD8(data_ptr + 1);
    if (msg_type >= MSG_TYPE_LIMIT) {
        ST8(chatbox + MSGBOX_STATE_OFFSET, 6);
    } else {
        configure_msgbox(chatbox, data_ptr, msg_type,
                         msg_type & MSG_TYPE_MASK ? LD8(data_ptr + 2) : LD8(data_ptr + 3));
    }

    u32 result = dispatch_handler(msg_type, MSGBOX_STATE_OFFSET,
                                  msg_type & MSG_TYPE_MASK ? LD8(data_ptr + 3) : 0);

    u32 advanced = advance_msg_ptr(data_ptr, result);
    return advanced ? advanced : data_ptr;
}

