/* Select and invoke the jump-table target for a message type.
 * Types 0–15 cycle through the four targets (type % 4).
 * Type 16 → closeAndReset, type 17 → chatbox_804110C. */
static RegState dispatch_jump_target(u32 type, RegState in) {
    u32 idx = type & 3;
    if (type == 16) return call_target_close(in);
    if (type == 17) return call_target_110C(in);
    switch (idx) {
        case 0: return call_target_show(in);
        case 1: return call_target_advance(in);
        case 2: return call_target_close(in);
        default: return call_target_110C(in);
    }
}

/* chatbox_E8_msgbox: classify a message, set its box-type field, dispatch
 * to the appropriate handler, then advance the message pointer if the
 * handler returned non-zero. */
static RegState process_msgbox(u32 r4, u32 r5, u32 r6, u32 r7, u32 r8,
                               u32 r9, u32 r10, u32 r11, u32 r12) {
    /* Read message type from the second byte of the message buffer. */
    u32 msg_type = LD8(r4 + 1);
    u32 box_type;

    if (msg_type >= 0x10)
        box_type = 6;
    else if (msg_type >= 0xC)
        box_type = 5;
    else if (msg_type >= 8)
        box_type = 4;
    else if (msg_type <= 3)
        box_type = 0;
    else
        box_type = LD8(r4 + 2);

    /* Write the box-type code into ChatBoxPropreties. */
    ST8(r5 + BOX_TYPE_OFFSET, box_type);

    /* For mid-range types (4–7), an extra byte may carry cursor-position data. */
    if (msg_type >= 4 && msg_type <= 7) {
        u8 extra = LD8(r4 + 3);
        if (extra != 0xFF) {
            u32 entry = LD32(A_byte_8045DCC + (extra << 2));
            ST8(r5 + oChatbox_CursorIdx, (u8)(entry & 0xFFFF));
            ST8(r5 + oChatbox_Unk_1B,    (u8)(entry >> 16));
        }
    }

    /* Call the appropriate jump-table handler. */
    RegState in = {0,0,0,0, r4, r5, r6, r7, r8, r9, r10, r11, r12,
                   MSGBOX_RETURN_ADDR, false, false};
    RegState out = dispatch_jump_target(msg_type, in);

    /* If the handler returned zero, leave everything as-is (TST set Z).
     * Otherwise advance the message pointer by the per-type table entry. */
    if (out.r0 != 0) {
        u32 table_base = A_byte_804102C;
        u32 cur_type = LD8(out.r4 + 1);
        u32 advance = LD8(table_base + cur_type);
        out.r4 += advance;
        out.r1 = advance;
        out.r0 = table_base;
    }

    return out;
}

