/* Chatbox E8 message-box command handler.
 * Reads the command opcode at [cmdPtr+1], writes the display type to
 * ChatBoxProperties, optionally stores cursor position (opcodes 4-7),
 * then dispatches to the appropriate rendering handler via a jump table.
 * Returns the possibly-advanced command pointer and the nz/c/v flags
 * set by the final ADD (or TST if no advance). */
static u32 msgbox_process(u32 cmdPtr, u32 propsPtr, u32 cmdType,
                          u32 *out_nz, u32 *out_c, u32 *out_v) {
    u32 boxId = msgbox_fixed_type(cmdType);

    if (boxId == 0xFF) {
        /* Opcodes 4-7: the message-box ID and optional cursor come from data bytes */
        boxId = LD8(cmdPtr + 2);
