    u32 newCmdPtr = call_msgbox_handler(cmdType, boxId, cmdPtr);

    /* Reproduce the flag state from the original's final instruction:
     * if the handler returned 0 → TST r0,r0 (nz from r0); if we advanced
     * the pointer → ADDS r4,r4,r1 (nz,c,v from that addition). */
    if (newCmdPtr == cmdPtr) {
        /* Handler returned zero: flags come from TST r0, r0 where r0==0 → Z set */
        *out_nz = 0;
        *out_c = 0;
        *out_v = 0;
