        /* Flags from ADDS r4, r4, advance */
        u32 typeAfterCall = LD8(newCmdPtr + 1); /* already read inside helper; re-derive advance */
        u32 advance = LD8(A_byte_804102C + typeAfterCall);
        u32 r4_before = cmdPtr; /* approximate: if handler modified r4 this differs, but original uses post-call r4 */
        /* The original: r4 = ADDS(r4_post_handler, advance).
         * We stored the result; reconstruct the subtraction for flags.
         * r4_result - advance == r4_post_handler. */
        u32 result = newCmdPtr;
        *out_nz = result;
        /* Carry: check unsigned addition overflow */
        u32 sum = (result - advance) + advance;
        *out_c = (result < advance) ? 1 : 0;
        /* V: signed overflow check */
        s32 a = (s32)(result - advance);
        s32 b = (s32)advance;
        *out_v = ((a ^ b) >= 0) && ((result ^ a) < 0) ? 1 : 0;
    }

    return newCmdPtr;
}

