typedef struct {
    u32 usedCount; /* -> r0 */
    u32 r1Leave;   /* -> r1 */
    u32 r2Leave;   /* -> r2 */
} IdTally;

static IdTally tally_record_ids(u32 recordCount, u32 r2In) {
    IdTally out;
    u32 table    = A_unk_20343E0;
    u32 records  = A_word_202A020;
