    u32 used     = 0;
    u32 r1       = zero_fill_tally_table(table, 0x78);
    u32 r2       = r2In;
    u32 rec;

    /* Pass 1: count used records and tally their ids. */
    for (rec = records; (s32)rec < (s32)tableEnd; rec += 0x20) {
        u32 id = LD16(rec);
        if (id == 0)
            continue;
        used++;
        r2 = used;
        u32 slot;
        for (slot = 0; ; slot += 4) {
            u32 slotId = LD16(table + slot);
            if (slotId == 0) {
