            if (slotId == id) {
                u32 count = LD16(table + slot + 2) + 1;
                ST16(table + slot + 2, count);
                r1 = count;
                break;
            }
        }
    }

    /* Pass 2: stamp each record's tally field with count<<16 | id. */
    for (rec = records; (s32)rec < (s32)tableEnd; rec += 0x20) {
        u32 id = LD16(rec + 0x14);
        if (id == 0)
            continue;
        u32 slot;
        for (slot = 0; ; slot += 4) {
            u32 slotId = LD16(table + slot);
