                break;
        }
        u32 count = LD16(table + slot + 2);
        ST32(rec + 0x14, (count << 16) | id);
        r1 = id;
    }

    out.usedCount = used;
    out.r1Leave   = r1;
    out.r2Leave   = r2;
    return out;
}

