static struct chatbox_msg_step chatbox_msgbox_step(u32 msg, u32 chatbox) {
    u32 cmd = LD8(msg + 1);
    u32 style;
    u32 scratch;

    if (cmd >= 4 && cmd < 8) {
        /* These commands carry their own style byte and cursor position. */
        style = LD8(msg + 2);
        ST8(chatbox + oChatbox_MsgStyle, style);
        scratch = LD8(msg + 3);
        if (scratch != 0xFF) {
            u32 entry = byte_8045DCC + (scratch << 2);
            ST8(chatbox + oChatbox_CursorIdx, LD16(entry));
            ST8(chatbox + oChatbox_Unk_1B, LD16(entry + 2));
            scratch <<= 2;
        }
    } else {
        /* The command id itself selects the style byte. */
        if (cmd >= 0x10)
            scratch = 6;
        else if (cmd >= 0xC)
            scratch = 5;
        else if (cmd >= 8)
            scratch = 4;
        else
            scratch = 0;                 /* commands 0-3 */
        style = scratch;
        ST8(chatbox + oChatbox_MsgStyle, style);
    }

    u32 handler = LD32(chatbox_EB_msgboxJumpTable + cmd * 4);
    struct handler_answer answer;
    switch (cmd) {
    case 0: case 4: case 8: case 12:
        answer = call_chatbox_804103E(handler, cmd * 4, oChatbox_MsgStyle, scratch, msg, chatbox);
        break;
    case 1: case 5: case 9: case 13:
        answer = call_chatbox_8041090(handler, cmd * 4, oChatbox_MsgStyle, scratch, msg, chatbox);
        break;
    case 2: case 6: case 10: case 14: case 16:
        answer = call_chatbox_closeAndReset_80410F8(handler, cmd * 4, oChatbox_MsgStyle, scratch, msg, chatbox);
        break;
    case 3: case 7: case 11: case 15: case 17:
        answer = call_chatbox_804110C(handler, cmd * 4, oChatbox_MsgStyle, scratch, msg, chatbox);
        break;
    default:
        answer.r0 = 0;
        answer.r1 = cmd * 4;
        break;
    }

    if (answer.r0 != 0) {
        /* Handler wants more: step over this command. */
        u32 size = LD8(byte_804102C + cmd);
        return (struct chatbox_msg_step){ byte_804102C, size, msg + size, msg, size };
    }
    return (struct chatbox_msg_step){ 0, answer.r1, msg, 0, 0 };
}

/* chatbox_E8_msgbox(r4 = message record, r5 = chatbox state) -> r0/r1/r4 and flags */
Next chatbox_E8_msgbox(void) {
    struct chatbox_msg_step step = chatbox_msgbox_step(R4, R5);
    R0 = step.r0;
    R1 = step.r1;
    R4 = step.r4;
    SET_FLAGS_ADD(step.flag_a, step.flag_b);
    RETURN_TO_CALLER();
}

/* sub_8134EA8 — tally pass over the 32-byte records at word_202A020.
 *
 * The caller's r0 says how many records to walk.  Pass 1 visits every record
 * (the original tests the loop counter at the bottom, so the first record is
 * always visited, even with a count of 0): each record whose id halfword at
 * +0x00 is nonzero is counted, and its id is added to the tally table at
 * unk_20343E0 ({u16 id, u16 count} pairs, zero-filled on entry).  Pass 2 walks
 * the records again and, for every record whose word at +0x14 is nonzero,
 * stores (tally count << 16) | old low half back into +0x14.
 * Returns the number of records that had a nonzero id.
 * The original clobbers r1/r2 as it goes; r3-r7 are pushed/popped untouched. */

#define RECORD_ARRAY        A_word_202A020
#define RECORD_STRIDE       0x20
#define RECORD_VALUE_OFFSET 0x14   /* word that receives (count << 16) | old low half */
#define TALLY_TABLE         A_unk_20343E0
#define TALLY_TABLE_BYTES   0x78
#define TALLY_ENTRY_STRIDE  4      /* {u16 id, u16 count} per entry */

/* register form: calls ZeroFillByEightWords outside this file, which has no typed C interface yet.
 * Also returns the r1 the callee leaves behind: when neither pass below writes r1, that
 * leftover is exactly what the original ends up returning in r1. */
static u32 zero_fill_tally_table(u32 dst, u32 size) {
    R0 = dst;
    R1 = size;
    GUEST_CALL(ZeroFillByEightWords);
    return R1;
}

typedef struct {
    u32 tallied;  /* -> r0: number of records with a nonzero id */
    u32 r1_out;   /* -> r1: value the original leaves behind */
    u32 r2_out;   /* -> r2: value the original leaves behind */
} RecordTally;

static RecordTally tally_records(u32 record_count, u32 r2_in)
{
    RecordTally res;
    u32 table = TALLY_TABLE;
    u32 record_end = RECORD_ARRAY + record_count * RECORD_STRIDE;
    u32 r1 = zero_fill_tally_table(table, TALLY_TABLE_BYTES);
    u32 tallied = 0;
    u32 rec;

    /* Pass 1: count records with an id and tally the ids into the table. */
    rec = RECORD_ARRAY;
    do {
        u32 id = LD16(rec);
        if (id != 0) {
            u32 slot;
            tallied++;
            for (slot = 0; ; slot += TALLY_ENTRY_STRIDE) {
                u32 entry_id = LD16(table + slot);
                if (entry_id == 0) {
                    /* free slot: start a new tally with count 1 */
                    ST16(table + slot, id);
                    ST8(table + slot + 2, 1);
                    r1 = 0;
                    break;
                }
                if (entry_id == id) {
                    /* already tallied: bump its count */
                    r1 = LD16(table + slot + 2) + 1;
                    ST16(table + slot + 2, r1);
                    break;
                }
            }
        }
        rec += RECORD_STRIDE;
    } while ((s32)rec < (s32)record_end);

    /* Pass 2: pack each record's tally count into the high half of its +0x14 word. */
    rec = RECORD_ARRAY;
    do {
        u32 value = LD16(rec + RECORD_VALUE_OFFSET);
        if (value != 0) {
            u32 slot;
            for (slot = 0; ; slot += TALLY_ENTRY_STRIDE) {
                u32 entry_id = LD16(table + slot);
                if (entry_id == 0 || entry_id == value)
                    break;
            }
            {
                u32 count = LD16(table + slot + 2);
                u32 word = LD32(rec + RECORD_VALUE_OFFSET);
                ST32(rec + RECORD_VALUE_OFFSET, (count << 16) | (word & 0xFFFF));
                r1 = word & 0xFFFF;
            }
        }
        rec += RECORD_STRIDE;
    } while ((s32)rec < (s32)record_end);

    res.tallied = tallied;
    res.r1_out = r1;
    /* r2 is only ever written by the counter bumps, so it keeps the incoming
     * value when no record had an id. */
    res.r2_out = (tallied != 0) ? tallied : r2_in;
    return res;
}

/* sub_8134EA8(r0 = record count) -> r0, r1/r2 as the original leaves them */
Next sub_8134EA8(void) {
    RecordTally res = tally_records(R0, R2);
    R0 = res.tallied;
    R1 = res.r1_out;
    R2 = res.r2_out;
    RETURN_TO_CALLER();
}

/* The shared tally buffer (unk_20343E0) holds up to 30 entries of { u16 value; u16 count; }. */
#define TALLY_SLOT_SIZE   4
#define TALLY_BUFFER_SIZE 0x78
/* word_202A020 is an array of records; the two tallied u16 values live at these offsets. */
#define TALLY_RECORD_SIZE      0x20
#define TALLY_VALUE_A_OFFSET   0x00
#define TALLY_VALUE_B_OFFSET   0x14

typedef struct {
    u32 count;   /* r0: number of records whose offset-0 value is non-zero */
    u32 reg1;    /* r1: leftover of the last buffer lookup */
    u32 reg2;    /* r2: equals count once anything was tallied, else the caller's r2 */
} TallyResult;

/* register form: calls ZeroFillByEightWords outside this file, which has no typed C interface yet */
static void zero_fill_by_eight_words(u32 addr, u32 length) {
    R0 = addr;
    R1 = length;
    GUEST_CALL(ZeroFillByEightWords);
}

/* Tally the u16 value at offset 0 of the first `recordCount` records of word_202A020 into the
 * shared buffer, counting how many records have a non-zero value; then store each record's
 * offset-0x14 tally in the upper half of that record's u32 field. */
static TallyResult tally_records(u32 recordCount, u32 reg1In, u32 reg2In) {
    const u32 buffer     = unk_20343E0;
    const u32 records    = word_202A020;
    const u32 recordsEnd = records + recordCount * TALLY_RECORD_SIZE;
    u32 count = 0;
    u32 reg1 = reg1In;
    u32 reg2 = reg2In;
    u32 record;

    zero_fill_by_eight_words(buffer, TALLY_BUFFER_SIZE);

    /* First pass: build the value -> occurrence-count list and count the non-zero records. */
    for (record = records; record < recordsEnd; record += TALLY_RECORD_SIZE) {
        u32 value = LD16(record + TALLY_VALUE_A_OFFSET);
        u32 slot = 0;

        if (value == 0)
            continue;

        count++;
        reg2 = count;

        for (;;) {
            reg1 = LD16(buffer + slot);
            if (reg1 == 0) {                  /* value not listed yet: append it with count 1 */
                ST16(buffer + slot, value);
                slot += 2;
                ST8(buffer + slot, 1);
                slot += 2;
                break;
            }
            if (value == reg1) {              /* value already listed: bump its count */
                slot += 2;
                reg1 = LD16(buffer + slot) + 1;
                ST16(buffer + slot, reg1);
                slot += 2;
                break;
            }
            slot += TALLY_SLOT_SIZE;
        }
    }

    /* Second pass: write each record's offset-0x14 tally into the high half of its u32 field. */
    for (record = records; record < recordsEnd; record += TALLY_RECORD_SIZE) {
        u32 value = LD16(record + TALLY_VALUE_B_OFFSET);
        u32 slot = 0;

        if (value == 0)
            continue;

        for (;;) {
            reg1 = LD16(buffer + slot);
            if (reg1 == 0 || value == reg1)
                break;
            slot += TALLY_SLOT_SIZE;
        }

        slot += 2;
        reg1 = value;                         /* low half of the record's u32 is preserved */
        ST32(record + TALLY_VALUE_B_OFFSET, ((u32)LD16(buffer + slot) << 16) | reg1);
    }

    return (TallyResult){ count, reg1, reg2 };
}

/* sub_8134EA8(r0 = record count) -> r0 = tally count; r1/r2 = leftovers of the last lookup */
Next sub_8134EA8(void) {
    TallyResult result = tally_records(R0, R1, R2);
    R0 = result.count;
    R1 = result.reg1;
    R2 = result.reg2;
    RETURN_TO_CALLER();
}

/* sub_8134EA8 -- tally helper over the record array at word_202A020.
 *
 * First zeroes a 30-slot tally table (0x78 bytes at unk_20343E0, each slot
 * being { u16 id; u16 count; }), then makes two passes over record_count
 * records of 0x20 bytes each:
 *   pass 1: every record with a nonzero id halfword at +00 is counted -- a new
 *           {id, 1} slot is appended to the table, or an existing slot's count
 *           is incremented;
 *   pass 2: every record with a nonzero id halfword at +14 has that id's tally
 *           count stored into the upper half of its +14 word.
 * Returns the number of records that had a nonzero id at +00.
 * r3-r7 are preserved; r1/r2 end as loop scratch exactly like the original. */

#define ID_TABLE       A_unk_20343E0   /* 0x78 bytes: 30 slots of { u16 id; u16 count; } */
#define RECORD_ARRAY   A_word_202A020  /* record_count records of 0x20 bytes each */
#define RECORD_STRIDE  0x20
#define RECORD_ID      0x00            /* u16: id tallied in pass 1 */
#define RECORD_ID2     0x14            /* u16: id stamped with its tally in pass 2 */

typedef struct { u32 r1, r2; } CalleeLeftovers;

/* register form: calls ZeroFillByEightWords outside this file, which has no typed C interface yet.
 * ZeroFillByEightWords itself answers in no register, but the original keeps whatever that call
 * leaves behind in r1/r2 when there is nothing to scan, so hand those leftovers back too. */
static CalleeLeftovers clear_id_table(void) {
    CalleeLeftovers left;
    R0 = ID_TABLE;
    R1 = 0x78;
    GUEST_CALL(ZeroFillByEightWords);
    left.r1 = R1;
    left.r2 = R2;
    return left;
}

typedef struct {
    u32 nonzero_records; /* -> r0 */
    u32 r1_out;          /* -> r1: scratch, as the original leaves it */
    u32 r2_out;          /* -> r2: scratch, as the original leaves it */
} TallyResult;

static TallyResult tally_record_ids(u32 record_count, u32 r2_incoming) {
    TallyResult out;
    u32 table = ID_TABLE;
    u32 end = RECORD_ARRAY + record_count * RECORD_STRIDE;
    CalleeLeftovers left = clear_id_table();
    u32 r1 = left.r1;
    u32 r2 = left.r2;    /* only r1/r2 scratch: starts as the caller's r2 */
    u32 nonzero = 0;

    /* Pass 1: count how many records carry each id at +00. */
    for (u32 rec = RECORD_ARRAY; (s32)rec < (s32)end; rec += RECORD_STRIDE) {
        u32 id = LD16(rec + RECORD_ID);
        if (id == 0)
            continue;
        nonzero++;
        r2 = nonzero;
        u32 slot = 0;
        for (;;) {
            u32 entry_id = LD16(table + slot);
            if (entry_id == 0) {
                /* first sighting: append {id, count 1} */
                ST16(table + slot, id);
                ST8(table + slot + 2, 1);
                r1 = 0;
                break;
            }
            if (entry_id == id) {
                /* seen before: bump its count */
                r1 = LD16(table + slot + 2) + 1;
                ST16(table + slot + 2, r1);
                break;
            }
            slot += 4;
        }
    }

    /* Pass 2: stamp each record's second id (+14) with the tally count for it. */
    for (u32 rec = RECORD_ARRAY; (s32)rec < (s32)end; rec += RECORD_STRIDE) {
        u32 id = LD16(rec + RECORD_ID2);
        if (id == 0)
            continue;
        u32 slot = 0;
        for (;;) {
            u32 entry_id = LD16(table + slot);
            if (entry_id == 0 || entry_id == id)
                break;
            slot += 4;
        }
        u32 count = LD16(table + slot + 2);
        ST32(rec + RECORD_ID2, (count << 16) | id);
        r1 = id;
    }

    out.nonzero_records = nonzero;
    out.r1_out = r1;
    out.r2_out = r2;
    return out;
}

/* sub_8134EA8(r0 = record count, r2 = caller's scratch) ->
 *   r0 = records with a nonzero id, r1/r2 = scratch as the original leaves them */
Next sub_8134EA8(void) {
    TallyResult out = tally_record_ids(R0, R2);
    R0 = out.nonzero_records;
    R1 = out.r1_out;
    R2 = out.r2_out;
    RETURN_TO_CALLER();
}

/* sub_8134EA8 -- tally battle-record ids.
 *
 * Scans the first r0 records of the 0x20-byte record array at word_202A020:
 *   Pass 1 counts the records whose u16 id at +0x00 is non-zero and builds a
 *   tally of those ids in a freshly cleared table at unk_20343E0 (0x78 bytes,
 *   4-byte slots of u16 id followed by u16 count).
 *   Pass 2 gives every record with a non-zero u16 id at +0x14 its tally count
 *   by packing (count << 16) | id into the 32-bit field there. An id missing
 *   from the table reads a count of 0 from the first empty slot, exactly like
 *   the original's scan.
 * Returns the pass-1 record count in r0. r1/r2 are scratch in the original;
 * their final values are reproduced exactly (r1 keeps the last tally result
 * touched, r2 the running count), and r3-r7 are preserved. */

#define RECORD_ARRAY     A_word_202A020
#define RECORD_STRIDE    0x20
#define RECORD_ID        0x00   /* u16 id tallied in pass 1 */
#define RECORD_ID_COUNT  0x14   /* u16 id, low half of the u32 count|id pair */
#define TALLY_TABLE      A_unk_20343E0
#define TALLY_TABLE_SIZE 0x78   /* 30 slots of u16 id + u16 count */

typedef struct {
    u32 count;       /* -> r0: records seen in pass 1 */
    u32 r1_final;    /* -> r1: final value of the original's scratch r1 */
    u32 r2_final;    /* -> r2: final value of the original's scratch r2 */
} id_tally_result;

/* register form: calls ZeroFillByEightWords outside this file, which has no typed C interface yet */
static void clear_tally_table(void) {
    R0 = TALLY_TABLE;
    R1 = TALLY_TABLE_SIZE;
    GUEST_CALL(ZeroFillByEightWords);
}

/* Index of the slot holding id, or of the first empty slot if it is not
 * tallied yet. The table is zero-filled, so the scan stops there -- or, when
 * all 30 slots are taken, keeps scanning past the table exactly like the
 * original does. */
static u32 find_tally_slot(u32 id) {
    u32 slot = 0;
    for (;;) {
        u16 entry_id = LD16(TALLY_TABLE + slot);
        if (entry_id == 0 || entry_id == id)
            return slot;
        slot += 4;
    }
}

static id_tally_result tally_record_ids(u32 record_count, u32 r1_final, u32 r2_final) {
    id_tally_result out;
    u32 end = RECORD_ARRAY + record_count * RECORD_STRIDE;
    u32 seen = 0;

    clear_tally_table();

    /* Pass 1: count live records and tally their ids. */
    for (u32 rec = RECORD_ARRAY; (s32)rec < (s32)end; rec += RECORD_STRIDE) {
        u32 id = LD16(rec + RECORD_ID);
        if (id == 0)
            continue;
        r2_final = ++seen;
        u32 slot = find_tally_slot(id);
        if (LD16(TALLY_TABLE + slot) == 0) {
            /* not tallied yet: start a new entry with a count of 1 */
            ST16(TALLY_TABLE + slot, id);
            ST8(TALLY_TABLE + slot + 2, 1);
            r1_final = 0;
        } else {
            u32 count = (u32)LD16(TALLY_TABLE + slot + 2) + 1;
            ST16(TALLY_TABLE + slot + 2, count);
            r1_final = count;
        }
    }

    /* Pass 2: hand each record with a second id its tally count. */
    for (u32 rec = RECORD_ARRAY; (s32)rec < (s32)end; rec += RECORD_STRIDE) {
        u32 id = LD16(rec + RECORD_ID_COUNT);
        if (id == 0)
            continue;
        u32 slot = find_tally_slot(id);
        u32 count = (u32)LD16(TALLY_TABLE + slot + 2);
        ST32(rec + RECORD_ID_COUNT, (count << 16) | id);
        r1_final = id;
    }

    out.count = seen;
    out.r1_final = r1_final;
    out.r2_final = r2_final;
    return out;
}

Next sub_8134EA8(void) {
    id_tally_result out = tally_record_ids(R0, R1, R2);
    R0 = out.count;
    R1 = out.r1_final;
    R2 = out.r2_final;
    RETURN_TO_CALLER();
}

/* Table of (u16 id, u16 count) records filled in by sub_8134EA8. */
#define ID_TABLE       0x020343E0   /* unk_20343E0 */
#define ID_TABLE_SIZE  0x78

/* List of 0x20-byte entity records: id at +0x00, key at +0x14. */
#define ENTITY_LIST    0x0202A020   /* word_202A020 */
#define ENTITY_STRIDE  0x20
#define ENTITY_ID_OFF  0x00
#define ENTITY_KEY_OFF 0x14

/* register form: calls ZeroFillByEightWords outside this file, which has no typed C interface yet */
static void clear_id_table(void) {
    R0 = ID_TABLE;
    R1 = ID_TABLE_SIZE;
    GUEST_CALL(ZeroFillByEightWords);
}

/* Result of scan_entity_ids().  The original leaves the entity count in r0
 * and, as a by-product of its two loops, values in r1 and r2 that callers
 * observe, so all three are returned. */
typedef struct {
    u32 idCount;    /* r0: entities whose id is non-zero */
    u32 lastValue;  /* r1: last key stored (pass 2), else the count written
                       for the last id (pass 1), else 0 */
    u32 tally;      /* r2: idCount, or tallyIn when no id was found */
} IdScanResult;

/* Collect the distinct ids of the first `entityCount` entity records into the
 * id table with a usage count each, then write every record's key count into
 * the high half of its key field.  Returns the number of entities with a
 * non-zero id. */
static IdScanResult scan_entity_ids(u32 entityCount, u32 tallyIn) {
    IdScanResult result;
    u32 entity, end, slot, id, entry;

    clear_id_table();

    end = ENTITY_LIST + entityCount * ENTITY_STRIDE;
    result.idCount = 0;
    result.lastValue = 0;
    result.tally = tallyIn;

    /* First pass: give each non-zero id a table slot, or bump its count. */
    for (entity = ENTITY_LIST; entity < end; entity += ENTITY_STRIDE) {
        id = LD16(entity + ENTITY_ID_OFF);
        if (id == 0)
            continue;
        result.idCount++;
        result.tally = result.idCount;

        for (slot = 0; ; slot += 4) {
            entry = LD16(ID_TABLE + slot);
            if (entry == 0) {
                ST16(ID_TABLE + slot, id);        /* new id ...        */
                ST8(ID_TABLE + slot + 2, 1);      /* ... with count 1  */
                result.lastValue = 0;
                break;
            }
            if (entry == id) {
                u32 n = LD16(ID_TABLE + slot + 2) + 1;
                ST16(ID_TABLE + slot + 2, n);
                result.lastValue = n;
                break;
            }
        }
    }

    /* Second pass: store each record's key count in its key field. */
    for (entity = ENTITY_LIST; entity < end; entity += ENTITY_STRIDE) {
        u32 key = LD16(entity + ENTITY_KEY_OFF);
        if (key == 0)
            continue;

        for (slot = 0; ; slot += 4) {
            entry = LD16(ID_TABLE + slot);
            if (entry == 0 || entry == key)
                break;
        }
        result.lastValue = key;
        ST32(entity + ENTITY_KEY_OFF,
             (LD16(ID_TABLE + slot + 2) << 16) | key);
    }

    return result;
}

/* sub_8134EA8(r0 = entity count, r2 = incoming tally) -> r0 */
Next sub_8134EA8(void) {
    IdScanResult scan = scan_entity_ids(R0, R2);
    R0 = scan.idCount;
    R1 = scan.lastValue;
    R2 = scan.tally;
    RETURN_TO_CALLER();
}

