 * (the original ends in `adds r4,r4,r1` on one exit path and in a plain
 * `tst r0,r0` on the other; see msgbox_command_step). */
struct msgbox_step_result {
    u32 r0;
    u32 r1;
    u32 r4;
    u32 flag_a;
    u32 flag_b;
};

/* Run one msgbox script command.
 *
 * script points at the chatbox script command (byte 1 is the opcode, byte 2/3
 * carry parameters), chatbox at the chatbox properties.  Every opcode first
 * stores a window style byte at chatbox+0x1D2, then the opcode's handler
 * runs with r0 = jump table base, r1 = opcode * 4, r2 = 0x1D2 and r3 set per
 * opcode class.  The handlers are the ones in chatbox_EB_msgboxJumpTable:
 * opcodes 0-15 cycle through the same four entries, opcode 16 closes and
 * resets the box, opcode 17 shares chatbox_804110C.
 *
 * When the handler answers non-zero the command is finished: the opcode's
 * length is read from byte_804102C[opcode], added to the script pointer, and
 * the length is what the original leaves in r1.  When it answers 0 the script
 * pointer stays put and r1 keeps the handler's leftover. */
static struct msgbox_step_result msgbox_command_step(u32 script, u32 chatbox)
{
    struct msgbox_step_result res;
    struct msgbox_handler_call call;
    u32 cmd = LD8(script + 1);
    u32 table = A_chatbox_EB_msgboxJumpTable;
    u32 arg3;

    if (cmd >= 0x10) {
        ST8(chatbox + CHATBOX_STYLE_BYTE, 6);
        arg3 = 6;
    } else if (cmd >= 0x0C) {
        ST8(chatbox + CHATBOX_STYLE_BYTE, 5);
        arg3 = 5;
    } else if (cmd >= 0x08) {
        ST8(chatbox + CHATBOX_STYLE_BYTE, 4);
        arg3 = 4;
    } else if (cmd <= 0x03) {
        ST8(chatbox + CHATBOX_STYLE_BYTE, 0);
        arg3 = 0;
    } else {
        /* Opcodes 4-7 take the style from the command itself; byte 3 picks an
         * entry of the cursor coordinate table (x, y halfwords) unless it is
         * 0xFF, which leaves the cursor where it is. */
        ST8(chatbox + CHATBOX_STYLE_BYTE, LD8(script + 2));
        arg3 = LD8(script + 3);
        if (arg3 != 0xFF) {
            u32 coord = A_byte_8045DCC + arg3 * 4;
            ST8(chatbox + oChatbox_CursorIdx, LD16(coord));
            ST8(chatbox + oChatbox_Unk_1B, LD16(coord + 2));
            arg3 *= 4;
        }
    }

    switch (cmd < 0x10 ? cmd & 3 : 2 + (cmd & 1)) {
    case 0:  call = call_chatbox_804103E(table, cmd * 4, CHATBOX_STYLE_BYTE, arg3); break;
    case 1:  call = call_chatbox_8041090(table, cmd * 4, CHATBOX_STYLE_BYTE, arg3); break;
    case 2:  call = call_chatbox_closeAndReset_80410F8(table, cmd * 4, CHATBOX_STYLE_BYTE, arg3); break;
    default: call = call_chatbox_804110C(table, cmd * 4, CHATBOX_STYLE_BYTE, arg3); break;
    }

    res.r0 = call.r0;
    if (call.r0 == 0) {
        /* Command still running: script pointer unchanged, r1 keeps the
         * handler's leftover.  The original's last flag-setting instruction
         * here is `tst r0,r0` with r0 == 0 (Z set, N clear) and the handler's
         * C/V still in place.  The adapter expresses both exit paths with one
         * SET_FLAGS_ADD, so pick operands whose sum is 0 and whose carry and
         * overflow reproduce the handler's flags. */
        res.r1 = call.r1;
        res.r4 = script;
        if (!call.carry && !call.overflow) {
            res.flag_a = 0;
            res.flag_b = 0;
        } else if (call.carry && !call.overflow) {
            res.flag_a = 1;             /* 1 + 0xFFFFFFFF: sum 0, carry set */
            res.flag_b = 0xFFFFFFFF;
        } else if (call.carry) {
            res.flag_a = 0x80000000;    /* sum 0, carry and overflow set */
            res.flag_b = 0x80000000;
        } else {
            /* Carry clear with overflow set cannot be produced by one ADDS
             * of a zero sum; keep the carry correct and drop the overflow. */
            res.flag_a = 0;
            res.flag_b = 0;
        }
    } else {
        /* Command finished: skip it by its length from byte_804102C (the
         * original leaves that length in r1) and reproduce the final
         * `adds r4, r4, r1` directly. */
        u32 len = LD8(A_byte_804102C + cmd);
        res.r1 = len;
        res.r4 = script + len;
        res.flag_a = script;
        res.flag_b = len;
    }
    return res;
}

