{
    struct msgbox_step_result res = msgbox_command_step(R4, R5);
    R0 = res.r0;
    R1 = res.r1;
    R4 = res.r4;
    SET_FLAGS_ADD(res.flag_a, res.flag_b);
    RETURN_TO_CALLER();
}

