                    /* A program whose flag byte is zero runs without being packed. */
                    u32 tableOffset = (prog >> 2) << 2;
                    NcpHandlerRegs after = run_ncp_handler(
                        ncp_handler_addr(prog, tableOffset), tableOffset,
                        r2, *r3, prog, slot, work);
                    *r3 = after.r3;
                    *r4 = after.r4;
                    r6After = after.r6;
                }
            }
        }

        u32 next = r6After - 1;
        if ((s32)next < 0)
            break;
        slot = next;
    }
