        u32 r6After = slot;

        u32 equipByte = LD8(work + slot);
        if (equipByte != 0) {
            u32 r2 = 0;
            u32 entry = get_ncp_entry_ptr(equipByte - 1, &r2);
            u32 prog = LD16(entry);
            if (prog != 0) {
