 * and flags themselves.  On the stop path r1-r3 and the C/V flags must keep whatever the
 * handler left behind; on the advance path r0/r1/r4 take new values and the flags must be
 * the exact ADDS ones.  None of that is expressible from plain C. */
static void msgbox_dispatch_epilogue(void) {
    if (R0 == 0) {
        /* tst r0, r0 with result 0: N clear, Z set, C/V untouched */
        SET_FLAGS_NZ(R0);
        return;
    }
    R0 = A_byte_804102C;                           /* ldr r0, =byte_804102C */
    u32 step = LD8(A_byte_804102C + LD8(R4 + 1));  /* per-command script length */
    R1 = step;
    SET_FLAGS_ADD(R4, step);                       /* adds r4, r4, r1 */
    R4 = R4 + step;
