        arg3 = 5;
    } else if (cmd >= 8) {
        ST8(props + CHATBOX_TEXTMARGIN_OFF, 4);
        arg3 = 4;
    } else if (cmd <= 3) {
        ST8(props + CHATBOX_TEXTMARGIN_OFF, 0);
        arg3 = 0;
    } else {
        /* Commands 4-7: margin comes from the script, plus an optional cursor position. */
        ST8(props + CHATBOX_TEXTMARGIN_OFF, LD8(script + 2));
        arg3 = LD8(script + 3);
