    case MSGBOX_HANDLER_804103E:
        call_chatbox_804103E(entry, cmd4, CHATBOX_TEXTMARGIN_OFF, arg3); break;
    case MSGBOX_HANDLER_8041090:
        call_chatbox_8041090(entry, cmd4, CHATBOX_TEXTMARGIN_OFF, arg3); break;
    case MSGBOX_HANDLER_CLOSE:
        call_chatbox_closeAndReset(entry, cmd4, CHATBOX_TEXTMARGIN_OFF, arg3); break;
    case MSGBOX_HANDLER_804110C:
        call_chatbox_804110C(entry, cmd4, CHATBOX_TEXTMARGIN_OFF, arg3); break;
