/* ---------------------------------------------------------------------------
 * sub_8134EA8 - tally the ids shared by entries of the battle object table.
 *
 *   object table (word_202A020): `objectCount` entries of 0x20 bytes each.
 *   histogram    (unk_20343E0): slots of { u16 id; u16 count; } (4 bytes).
 *
 * Pass 1 histograms the u16 id at entry+0x00.  Pass 2 writes the shared-id
 * count into the high half of the word at entry+0x14, keeping the entry's own
 * id in the low half.  Returns how many entries had a non-zero tally id.
 * ------------------------------------------------------------------------- */

#define OBJECT_TABLE       0x0202A020   /* word_202A020 */
#define OBJECT_ENTRY_SIZE  0x20
#define OBJECT_TALLY_ID    0x00         /* u16 id counted in pass 1 */
#define OBJECT_SHARED_ID   0x14         /* low u16 id; high u16 receives the count */

#define HISTOGRAM_TABLE    0x020343E0   /* unk_20343E0 */
#define HISTOGRAM_BYTES    0x78
#define HISTOGRAM_SLOT     4            /* bytes per { u16 id; u16 count; } slot */

typedef struct {
    u32 countedObjects;  /* r0: entries that carried a non-zero tally id       */
    u32 scratch;         /* r1: value the original happens to leave in its r1  */
    u32 runningCount;    /* r2: running total, or the caller's r2 if none ran  */
} TallyResult;

/* register form: calls ZeroFillByEightWords outside this file, which has no typed C interface yet */
static void clear_histogram(u32 address, u32 size) {
    R0 = address;
    R1 = size;
    GUEST_CALL(ZeroFillByEightWords);
}

static TallyResult tally_object_ids(u32 objectCount, u32 r2In) {
    TallyResult result;
    u32 total = 0;
    u32 r1 = 0;                     /* ZeroFillByEightWords leaves r1 cleared */
    u32 i, slot;

    clear_histogram(HISTOGRAM_TABLE, HISTOGRAM_BYTES);

    /* Pass 1: build the histogram of the ids stored at offset 0x00. */
    for (i = 0; i < objectCount; i++) {
        u32 object = OBJECT_TABLE + i * OBJECT_ENTRY_SIZE;
        u16 id = LD16(object + OBJECT_TALLY_ID);
        if (id == 0)
            continue;

        total++;
        for (slot = 0; ; slot += HISTOGRAM_SLOT) {
            u16 slotId = LD16(HISTOGRAM_TABLE + slot);
            if (slotId == 0) {                      /* free slot: start a new entry */
                ST16(HISTOGRAM_TABLE + slot, id);
                ST16(HISTOGRAM_TABLE + slot + 2, 1);
                r1 = 0;
                break;
            }
            if (slotId == id) {                     /* known id: bump its count */
                u16 newCount = LD16(HISTOGRAM_TABLE + slot + 2) + 1;
                ST16(HISTOGRAM_TABLE + slot + 2, newCount);
                r1 = newCount;
                break;
            }
        }
    }

    /* Pass 2: store each entry's shared-id count beside the id at offset 0x14. */
    for (i = 0; i < objectCount; i++) {
        u32 object = OBJECT_TABLE + i * OBJECT_ENTRY_SIZE;
        u16 id = LD16(object + OBJECT_SHARED_ID);
        if (id == 0)
            continue;

        for (slot = 0; ; slot += HISTOGRAM_SLOT) {
            u16 slotId = LD16(HISTOGRAM_TABLE + slot);
            if (slotId == 0 || slotId == id)        /* free slot, or this id's slot */
                break;
        }
        u16 count = LD16(HISTOGRAM_TABLE + slot + 2);
        ST32(object + OBJECT_SHARED_ID, ((u32)count << 16) | id);
        r1 = id;
    }

    result.countedObjects = total;
    result.scratch = r1;
    result.runningCount = (total != 0) ? total : r2In;
    return result;
}

