}

/* chatbox_E8_msgbox (0x08040F70) - chatbox message-script interpreter step.
 *
 * r4 points at the current script command, r5 at the chatbox's
 * ChatBoxProperties. The command byte at script+1 picks one of four handler
 * routines through a jump table that repeats a four-entry cycle (commands 16
 * and 17 have their own entries at the end: close-and-reset, and finish).
 * Before dispatching, the command class stores a print mode to
 * ChatBoxProperties+0x1D2; commands 4-7 take that mode from the stream and
 * also reposition the text cursor from a coordinate table. If the handler
 * returns non-zero the command is finished and the script pointer is moved
 * past it using a per-command length table. */

#ifndef oChatbox_Unk_1D2
#define oChatbox_Unk_1D2 0x1D2 /* print mode byte in ChatBoxProperties (dword_8041024) */
#endif

/* What one handler call leaves behind. r1 is needed because the original
 * keeps the callee's r1 when the script is not advanced, but replaces it
 * with the command length when it is. */
struct MsgboxHandlerExit {
    u32 r0;
    u32 r1;
};

/* register form: calls chatbox_804103E outside this file, which has no typed C interface yet */
static struct MsgboxHandlerExit call_chatbox_804103E(u32 self, u32 cmd_x4, u32 mode_off, u32 param)
{
    struct MsgboxHandlerExit left;
    R0 = self;
    R1 = cmd_x4;
    R2 = mode_off;
    R3 = param;
    GUEST_CALL(chatbox_804103E);
    left.r0 = R0;
    left.r1 = R1;
    return left;
}

/* register form: calls chatbox_8041090 outside this file, which has no typed C interface yet */
static struct MsgboxHandlerExit call_chatbox_8041090(u32 self, u32 cmd_x4, u32 mode_off, u32 param)
{
