/* register form: calls chatbox_closeAndReset_80410F8 outside this file, which has no typed C interface yet */
static struct MsgboxHandlerExit call_chatbox_closeAndReset_80410F8(u32 self, u32 cmd_x4, u32 mode_off, u32 param)
{
