/* register form: calls chatbox_804110C outside this file, which has no typed C interface yet */
static struct MsgboxHandlerExit call_chatbox_804110C(u32 self, u32 cmd_x4, u32 mode_off, u32 param)
{
    struct MsgboxHandlerExit left;
    R0 = self;
    R1 = cmd_x4;
    R2 = mode_off;
