/* Dispatch on the command number the way the jump table does. The original
 * branches to the table entry with the entry's own address still in r0, so
 * hand that value on as the first argument. */
static struct MsgboxHandlerExit run_msgbox_handler(u32 cmd, u32 cmd_x4, u32 mode_off, u32 param)
{
    u32 self = LD32(A_chatbox_EB_msgboxJumpTable + cmd * 4);

    if (cmd == 16)
        return call_chatbox_closeAndReset_80410F8(self, cmd_x4, mode_off, param);
    if (cmd == 17)
        return call_chatbox_804110C(self, cmd_x4, mode_off, param);
    switch (cmd & 3) {
    case 0:  return call_chatbox_804103E(self, cmd_x4, mode_off, param);
    case 1:  return call_chatbox_8041090(self, cmd_x4, mode_off, param);
    case 2:  return call_chatbox_closeAndReset_80410F8(self, cmd_x4, mode_off, param);
    default: return call_chatbox_804110C(self, cmd_x4, mode_off, param);
    }
}

/* Everything the original leaves in r0/r1/r4, plus the value the exit flags'
 * N and Z bits encode (TST r0,r0 on the wait path, ADDS r4,r4,r1 on the
 * advance path - both encode N/Z from the value given here; C/V stay as the
 * handler call left them on the wait path, exactly as in the original). */
struct ChatboxMsgboxStep {
    u32 r0;
    u32 r1;
    u32 script;
    u32 nz_source;
};

static struct ChatboxMsgboxStep chatbox_msgbox_step(u32 script, u32 props)
{
    u32 cmd = LD8(script + 1);
    u32 mode;
    u32 param;

    /* Store the print mode the command class asks for. */
    if (cmd <= 3)
        mode = 0;
    else if (cmd < 8)
        mode = LD8(script + 2); /* commands 4-7 carry it in the stream */
    else if (cmd < 0xC)
        mode = 4;
    else if (cmd < 0x10)
        mode = 5;
    else
        mode = 6;
    ST8(props + oChatbox_Unk_1D2, mode);

    /* Commands 4-7 also move the cursor from a table of x/y coordinate
     * pairs; 0xFF in the stream means "leave the cursor alone". The handlers
     * receive the table offset (or 0xFF) rather than the cursor id. */
    if (cmd > 3 && cmd < 8) {
        u32 cursor = LD8(script + 3);
        if (cursor != 0xFF) {
            u32 coord = A_byte_8045DCC + cursor * 4;
            ST8(props + oChatbox_CursorIdx, LD16(coord));
            ST8(props + oChatbox_Unk_1B, LD16(coord + 2));
            cursor *= 4;
        }
        param = cursor;
    } else {
        param = mode;
    }

    struct MsgboxHandlerExit handler =
        run_msgbox_handler(cmd, cmd * 4, oChatbox_Unk_1D2, param);

    if (handler.r0 == 0) {
        /* Command still running: r0 is the zero just tested, and r1 and the
         * script pointer are untouched. */
        return (struct ChatboxMsgboxStep){ handler.r0, handler.r1, script, 0 };
    }

    /* Command finished: re-read the command (the handler may have edited the
     * stream) and skip the whole command. The original's tail leaves r0 =
     * length-table address, r1 = length, r4 = advanced script pointer. */
    u32 step = LD8(A_byte_804102C + LD8(script + 1));
    script += step;
    return (struct ChatboxMsgboxStep){ A_byte_804102C, step, script, script };
}

/* chatbox_E8_msgbox(r4 = script pointer, r5 = chatbox properties).
 * r2/r3 and the other callee-leaved registers are already in place from the
 * GUEST_CALL; the adapter only writes what the typed function computed. */
Next chatbox_E8_msgbox(void)
{
    struct ChatboxMsgboxStep out = chatbox_msgbox_step(R4, R5);
    R0 = out.r0;
    R1 = out.r1;
    R4 = out.script;
    SET_FLAGS_NZ(out.nz_source);
    RETURN_TO_CALLER();
}

/*
 * sub_8134EA8 -- rebuild the tally table at unk_20343E0 from the record list
 * at word_202A020.
 *
 * The records are 0x20 bytes apart; each one carries a u16 id at +0x00 and a
 * u32 at +0x14 whose low half holds a second id.
 *
 *   Pass 1: the tally table (4-byte slots: u16 id, u8 count) is zero-filled,
 *           then every record with a non-zero id gets a slot -- its count is
 *           incremented if the id is already present, otherwise a new slot is
 *           started with a count of 1.
 *   Pass 2: every record with a non-zero second id looks its slot up again and
 *           stores the result back into its +0x14 field as
 *           (tally count << 16) | second id.
 *
 * r0 returns the number of records that had an id. r2 holds that running
 * counter in the original; it is left untouched when no record qualified.
 */

/* register form: calls ZeroFillByEightWords outside this file, which has no typed C interface yet */
static void zero_fill_tally_table(u32 dest, u32 wordCount) {
    R0 = dest;
    R1 = wordCount;
    GUEST_CALL(ZeroFillByEightWords);
}

typedef struct {
    u32 recordsProcessed; /* -> r0 */
    u32 r1;               /* -> r1 */
    u32 r2;               /* -> r2 */
} RecordTally;

static RecordTally tally_records_into_table(u32 recordCount, u32 r2In)
{
    RecordTally out;
    u32 records = A_word_202A020;
    u32 recordsEnd = records + recordCount * 0x20;
    u32 table = A_unk_20343E0;

    zero_fill_tally_table(table, 0x78);
    /* ZeroFillByEightWords counts its size parameter down to zero, so r1
     * reads 0 from here on until one of the scans below assigns it. */
    u32 r1 = 0;
    u32 r2 = r2In;   /* running counter, shared with the stack slot in the original */
    u32 processed = 0;

    /* Pass 1: count each record's id into the tally table. */
    for (u32 rec = records; (s32)rec < (s32)recordsEnd; rec += 0x20) {
        u32 id = LD16(rec);
        if (id == 0)
            continue;                     /* unused record: skip entirely */

        processed++;
        r2 = processed;

        u32 slot = 0;
        for (;;) {
            u32 slotId = LD16(table + slot);
            r1 = slotId;
            if (slotId == 0) {
                /* free slot: start a new tally at 1 */
                ST16(table + slot, id);
                ST8(table + slot + 2, 1);
                break;
            }
            if (slotId == id) {
                /* existing slot: bump its count */
                u32 countAddr = table + slot + 2;
                r1 = LD16(countAddr) + 1;
                ST16(countAddr, r1);
                break;
            }
            slot += 4;
        }
    }

    /* Pass 2: write each record's tally back into its +0x14 field. */
    for (u32 rec = records; (s32)rec < (s32)recordsEnd; rec += 0x20) {
        u32 id2 = LD16(rec + 0x14);
        if (id2 == 0)
            continue;

        u32 slot = 0;
        for (;;) {
            u32 slotId = LD16(table + slot);
            r1 = slotId;
            if (slotId == 0 || slotId == id2)
                break;                    /* empty and matching slots are both used as-is */
            slot += 4;
        }

        u32 count = LD16(table + slot + 2);
        u32 field = LD32(rec + 0x14);
        r1 = field & 0xFFFF;
        ST32(rec + 0x14, (count << 16) | r1);
    }

    out.recordsProcessed = processed;
    out.r1 = r1;
    out.r2 = r2;
    return out;
}

/* sub_8134EA8(r0 = record count, r2 = counter pass-through) -> r0 r1 r2;
 * r3-r7 are only carried through. */
Next sub_8134EA8(void) {
    RecordTally out = tally_records_into_table(R0, R2);
    R0 = out.recordsProcessed;
    R1 = out.r1;
    R2 = out.r2;
    RETURN_TO_CALLER();
}

/* dword_8041024 holds 0x1D2: every msgbox opcode stores a class/derived byte to
 * chatbox+0x1D2 (the disassembly has no named field for this offset). */
#define MSGBOX_MODE_BYTE 0x1D2

/* Register state one msgbox script command leaves behind for its caller. */
typedef struct {
    u32 r0_out;    /* r0: 0, or the address of the command-length table once consumed */
    u32 r1_out;    /* r1: the command length once consumed, else the handler's r1 */
    u32 r4_out;    /* r4: the command stream pointer, stepped past a consumed command */
    u32 tst_value; /* value the original's trailing tst/adds leaves N and Z on */
} MsgboxCmdResult;

/* register form: calls chatbox_804103E, chatbox_8041090, chatbox_closeAndReset_80410F8 and
 * chatbox_804110C outside this file, which have no typed C interface yet. This also bridges
 * the register/flag state around the original's `mov lr,pc; bx r0`: the `lsl r1,r1,#2` flag
 * state going in, and the `tst r0,r0` / `adds r4,r4,r1` tail coming out. The handler's r1
 * survives to the caller when it returns zero, so it is captured here. */
static MsgboxCmdResult call_msgbox_handler(u32 entry, u32 opcode_x4, u32 arg3, u32 cmd,
                                           bool v_cleared_by_parse)
{
    /* Flags at the original's bx: N=0 and Z=(opcode==0) from the shift, C=0 (bit 30 of a
     * byte-sized opcode shifts out as 0), V untouched by the shift -- but the opcode 4-7
     * parse performs an address `add` that clears V on that path. Each ADDS below only
     * pins C=0 with the required V; SET_FLAGS_NZ then fixes N and Z. */
    if (v_cleared_by_parse || !OVERFLOW_FLAG())
        SET_FLAGS_ADD(0, 0);                    /* 0+0: C=0, V=0 */
    else
        SET_FLAGS_ADD(0x40000000, 0x40000000);  /* 0x40000000+0x40000000: C=0, V=1 */
    SET_FLAGS_NZ(opcode_x4);

    R0 = entry;   /* the original dispatches with the jump-table word itself in r0 */
    R1 = opcode_x4;
    R2 = MSGBOX_MODE_BYTE;
    R3 = arg3;

    switch (entry) {
    case 0x0804103F: GUEST_CALL(chatbox_804103E); break;               /* opcodes 0/4/8/12  */
    case 0x08041091: GUEST_CALL(chatbox_8041090); break;               /* opcodes 1/5/9/13  */
    case 0x080410F9: GUEST_CALL(chatbox_closeAndReset_80410F8); break; /* opcodes 2/6/10/16 */
    case 0x0804110D: GUEST_CALL(chatbox_804110C); break;               /* opcodes 3/7/11/17 */
    }

    u32 handler_ret = R0;
    u32 handler_r1 = R1;

    if (handler_ret == 0) {
        /* tst r0,r0 -> eq: the command stays put; r0 is 0, the handler's r1 survives. */
        return (MsgboxCmdResult){ .r0_out = 0, .r1_out = handler_r1,
                                  .r4_out = cmd, .tst_value = 0 };
    }

    /* Handled: step the command stream past this command. The length is keyed by the
     * opcode byte re-read from the stream, which the handler may have edited. */
    u32 length = LD8(A_byte_804102C + LD8(cmd + 1));
    u32 advanced = cmd + length;
    SET_FLAGS_ADD(cmd, length);  /* the original's adds r4, r4, r1 */
    return (MsgboxCmdResult){ .r0_out = A_byte_804102C, .r1_out = length,
                              .r4_out = advanced, .tst_value = advanced };
}

/* Run one msgbox script command: cmd points at the command word (cmd[1] = opcode,
 * cmd[2..3] = operands), box at the chatbox property struct. Writes the mode/cursor bytes
 * the opcode class implies, runs the opcode's handler and, when the handler reports the
 * command as handled, steps cmd past it. */
static MsgboxCmdResult run_msgbox_command(u32 cmd, u32 box)
{
    u32 opcode = LD8(cmd + 1);
    u32 arg3;
    bool v_cleared = false;

    /* The opcode class selects the byte written to box+0x1D2 (and passed in r3)... */
    if (opcode >= 0x10) {
        ST8(box + MSGBOX_MODE_BYTE, 6);
        arg3 = 6;
    } else if (opcode >= 0xC) {
        ST8(box + MSGBOX_MODE_BYTE, 5);
        arg3 = 5;
    } else if (opcode >= 8) {
        ST8(box + MSGBOX_MODE_BYTE, 4);
        arg3 = 4;
    } else if (opcode <= 3) {
        ST8(box + MSGBOX_MODE_BYTE, 0);
        arg3 = 0;
    } else {
        /* ...while opcodes 4-7 carry the mode byte inline, plus an optional cursor
         * position as an index into the halfword pairs of byte_8045DCC (0xFF = none). */
        ST8(box + MSGBOX_MODE_BYTE, LD8(cmd + 2));
        u32 idx = LD8(cmd + 3);
        if (idx != 0xFF) {
            u32 coords = A_byte_8045DCC + idx * 4;
            ST8(box + oChatbox_CursorIdx, LD16(coords));   /* ChatBoxProperties.csrCoord */
            ST8(box + oChatbox_Unk_1B, LD16(coords + 2));  /* ChatBoxProperties.unk_1B  */
            idx *= 4;
            v_cleared = true;   /* the address add above clears V in the original */
        }
        arg3 = idx;   /* the handler receives idx*4, or 0xFF when there was no lookup */
    }

    u32 entry = LD32(A_chatbox_EB_msgboxJumpTable + opcode * 4);
    return call_msgbox_handler(entry, opcode * 4, arg3, cmd, v_cleared);
}

Next chatbox_E8_msgbox(void) {
    MsgboxCmdResult left_behind = run_msgbox_command(R4, R5);
    R0 = left_behind.r0_out;
    R1 = left_behind.r1_out;
    R4 = left_behind.r4_out;
    SET_FLAGS_NZ(left_behind.tst_value);
    RETURN_TO_CALLER();
}
